window.CZ_SET = {"채총21":[{"h":"1. 특정물채권","q":"특정물 채무자는 그 물건을 인도하기까지 ____를 부담하며(제374조), 이는 추상적 과실을 의미한다.","a":"선관주의의무"},{"h":"1. 특정물채권","q":"특정물 채무자는 ____의 현상대로 그 물건을 인도하여야 한다(제462조).","a":"이행기"},{"h":"1. 특정물채권","q":"제462조의 '이행기'는 통설에 따르면 ____를 의미한다.","a":"실제 인도할 때"},{"h":"1. 특정물채권","q":"특정물이 변질·훼손되어도 그 상태로 인도하면 되고, 동일성을 상실하면 ____는 소멸한다(채무불이행 문제는 아님).","a":"인도의무"},{"h":"가. 종류채권의 특정(제375조 제2항)","q":"'채권자 동의 얻어 지정'하는 방법에서, 합의가 없고 채무자가 지정권을 행사하지 않으면 ____ 규정(제381조)을 준용하여 지정권이 채권자에게 이전한다.","a":"선택채권"},{"h":"가. 종류채권의 특정(제375조 제2항)","q":"'채무자가 이행에 필요한 행위를 완료'하였는지는 ____(제460조)을 기준으로 판단한다.","a":"변제제공"},{"h":"가. 종류채권의 특정(제375조 제2항)","q":"지참채무는 ____이 있어야 특정된다 — 채권자 주소에 도달하여 채권자가 언제든지 수령할 수 있는 상태에 놓인 때.","a":"현실제공"},{"h":"가. 종류채권의 특정(제375조 제2항)","q":"추심채무는 목적물을 분리하여 변제준비 완료를 통지하고 수령을 최고하는 ____이 있어야 특정된다.","a":"구두제공"},{"h":"나. 특정의 효과","q":"종류채권이 특정되면 ____이 채권자에게 이전한다 — 특정 이후 멸실되면 채무자의 채무는 소멸한다.","a":"물건의 위험"},{"h":"3. 외화채권","q":"채무자가 대용급부권(제378조)을 행사하는 경우 환산시기는 변제기가 아니라 ____이다(전합).","a":"현실로 이행할 때"},{"h":"3. 외화채권","q":"채권자가 대용권을 행사하여 재판상 청구하는 경우 환산시기는 채무자가 현실로 이행할 때에 가장 가까운 ____이다(전합).","a":"사실심 변론종결시"},{"h":"4. 이자채권","q":"민사 법정이율은 연 ____%이다(제379조).","a":"5"},{"h":"4. 이자채권","q":"상사 법정이율은 연 ____%이다(상법 제54조).","a":"6"},{"h":"4. 이자채권","q":"금전대차 약정이자의 최고이자율은 2021. 7. 7. 이후 체결·갱신된 계약의 경우 연 ____%이다.","a":"20"},{"h":"가. 최고이자율 적용 범위","q":"이자제한법 최고이자율을 초과하는 이자를 채무자가 임의로 지급하면 초과분은 ____에 충당된다.","a":"원본"},{"h":"가. 최고이자율 적용 범위","q":"이자제한법의 최고이자율은 금전대차 계약상 '이자'에만 적용되고 ____에는 적용되지 않는다(2016다259769).","a":"위약벌"},{"h":"나. 이자제한법상 '이자'·간주이자","q":"전합에 따르면 ____는 중도상환 시의 손해배상액 예정일 뿐 금전대차의 대가가 아니므로 이자제한법상 간주이자가 아니다.","a":"중도상환수수료"},{"h":"다. 소송촉진법 지연손해금","q":"금전채무의 이행을 구하는 소를 제기한 경우 소장 송달 다음 날부터 적용되는 소송촉진법상 비율은 연 ____%이다(2019. 6. 1. 시행).","a":"12"},{"h":"라. 이자채권의 독립성","q":"변제기가 도래한 지분적 이자채권은 독립성이 있어 분리 양도할 수 있고, 소멸시효 기간은 제163조 제1호에 따라 ____년이다.","a":"3"},{"h":"라. 이자채권의 독립성","q":"원본채권이 시효로 소멸하면 그 효과가 ____하므로 지분적 이자채권도 소멸한다.","a":"소급"},{"h":"5. 선택채권","q":"선택채권에서 선택권자에 관한 규정이나 약정이 없으면 선택권은 ____에게 있다(제380조).","a":"채무자"}],"채총20":[{"h":"2. 채무의 분류","q":"보호의무를 채무의 범주에 넣을지 논의가 있으나, 통설은 ____로 해결한다.","a":"불법행위"},{"h":"가. 부수적 의무 위반 → 계약 해제 가부","q":"토지매매계약의 분묘이장의무, 영상물 제작공급계약의 시사회 준비의무처럼 ____ 의무를 위반한 것만으로는 계약을 해제할 수 없다.","a":"부수적"},{"h":"나. 보호의무 인정 사례","q":"숙박업자가 고객에 대한 안전배려의무를 위반하면 ____으로 인한 채무불이행책임을 진다.","a":"불완전이행"},{"h":"3. 채권의 기본적 효력","q":"채권의 기본적 효력은 청구력·____·강제력이다.","a":"급부보유력"},{"h":"3. 채권의 기본적 효력","q":"소구력과 집행력이 모두 없는 채무를 ____라 한다 — 예: 부제소특약, 채권자 패소확정판결.","a":"자연채무"},{"h":"3. 채권의 기본적 효력","q":"소구력은 있으나 집행력이 없는 채무를 ____라 한다 — 예: 부집행특약.","a":"책임 없는 채무"},{"h":"3. 채권의 기본적 효력","q":"물상보증인과 저당부동산의 제3취득자는 ____의 예이다.","a":"채무 없는 책임"}],"채총22":[{"h":"가. 임대차 목적물 화재","q":"임차 건물 부분에서 난 화재가 임차 외 건물 부분까지 번진 경우, 임차 외 부분의 손해에 대하여는 ____이 임차인의 의무위반과 상당인과관계 등을 증명하여야 한다(전합).","a":"임대인"},{"h":"가. 임대차 목적물 화재","q":"숙박계약에서 원인미상의 화재로 객실에 생긴 손해는 특별한 사정이 없는 한 ____가 부담한다.","a":"숙박업자"},{"h":"3. 이행지체 — 요건","q":"불법행위로 인한 손해배상채무는 최고 없이도 ____ 당일부터 지체책임이 발생한다.","a":"불법행위일"},{"h":"3. 이행지체 — 요건","q":"반환시기의 정함이 없는 소비대차에서는 대주가 ____을 정하여 최고하고 그 기간이 경과한 때 이행지체가 된다(제603조 제2항).","a":"상당기간"},{"h":"3. 이행지체 — 요건","q":"채권이 가압류되어 있어도 이행기가 도래하면 제3채무자는 지체책임을 지고, 이를 면하려면 제487조에 따라 ____하면 된다(전합).","a":"공탁"},{"h":"3. 이행지체 — 요건","q":"신원보증인의 채무는 기한의 정함이 없는 채무이므로 ____을 받아야 지체책임을 진다.","a":"이행청구"},{"h":"3. 이행지체 — 요건","q":"기한 없는 채권이 양도되고 소송계속 중 양도통지가 도달한 경우, 채무자는 통지 도달 ____부터 지체책임을 진다.","a":"다음 날"},{"h":"3. 이행지체 — 효과","q":"이행지체의 효과(두문자 강·손·해·책)는 강제이행, 손해배상, 해제, ____이다.","a":"책임가중"},{"h":"4. 이행불능 — 개념","q":"이행불능은 절대적·물리적 불능이 아니라 ____에 비추어 채권자가 이행의 실현을 기대할 수 없는 경우를 말한다.","a":"사회통념"},{"h":"4. 이행불능 — 효과","q":"이행불능의 효과(두문자 전·해·대)는 전보배상, 해제, ____이다.","a":"대상청구권"},{"h":"4. 이행불능 — 효과","q":"집합건물의 대지지분권은 전유부분과 ____ 관계에 있으므로, 점포의 소유권이전등기가 불능이면 대지지분의 이전도 불능이 된다.","a":"불가분"},{"h":"다. 대상청구권","q":"대상청구권의 요건은 급부가 ____ 불능이 되고, 채무자가 그로 인해 대상을 취득하며, 불능과 대상 취득 사이에 상당인과관계가 있을 것이다.","a":"후발적"},{"h":"다. 대상청구권","q":"대상청구권은 계약의 유지를 전제로 하므로, 유동적 무효인 토지거래허가구역 내 매매에서 토지가 수용되어 계약이 ____가 된 경우에는 인정되지 않는다.","a":"확정적 무효"},{"h":"다. 대상청구권","q":"대상청구권은 ____ 청구권이므로, 행사하여야 효력이 생기고 채무자가 취득한 권리의 양도나 이익의 반환을 구하게 된다.","a":"채권적"},{"h":"다. 대상청구권","q":"대상청구권의 행사범위가 손해를 한도로 제한되는지 견해가 대립하나, 대법원은 ____에 가깝다.","a":"무제한설"},{"h":"5. 이행거절","q":"채무자가 이행하지 않을 의사를 명백히 표시한 경우, 채권자는 이행기 전이라도 ____ 없이 계약을 해제할 수 있다.","a":"최고"},{"h":"5. 이행거절","q":"이행거절을 이유로 해제하려면 채무자의 이행거절 의사가 ____이어야 한다.","a":"명백하고 종국적"}],"채총23":[{"h":"2. 손해의 개념·분류","q":"손해의 개념에 관한 통설·판례는 ____이다 — 위법행위가 없었다면 존재했을 이익과 위법행위 후 현재 이익의 차이.","a":"차액설"},{"h":"2. 손해의 개념·분류","q":"손해 3분설은 적극적 손해, 소극적 손해(일실이익), ____로 나눈다.","a":"정신적 손해"},{"h":"2. 손해의 개념·분류","q":"신뢰이익의 배상은 ____을 한도로 한다(통설·판례, 제535조 제1항 단서 근거).","a":"이행이익"},{"h":"2. 손해의 개념·분류","q":"채무불이행으로 인한 손해배상청구권은 본래의 채권과 ____을 가지므로 소멸시효 기간이 같다.","a":"동일성"},{"h":"3. 손해배상의 범위(제393조)","q":"특별손해에서 예견가능성을 판단하는 기준시는 ____이다(통설·판례).","a":"채무불이행시"},{"h":"3. 손해배상의 범위(제393조)","q":"소유권이전등기의무를 이행할 수 없게 된 경우 매수인의 손해는 원칙적으로 ____ 당시의 시가이고, 그 후의 가격 등귀는 특별손해이다.","a":"이행불능"},{"h":"3. 손해배상의 범위(제393조)","q":"영업용 물건이 멸실된 경우의 휴업손해는 ____손해에 해당한다(전합).","a":"통상"},{"h":"3. 손해배상의 범위(제393조)","q":"수리비가 건물의 시가를 넘는 경제적 수리불능의 경우 손해배상액은 건물의 ____ 범위 내로 제한된다.","a":"교환가치"},{"h":"나. 과실상계(제396조, 제763조)","q":"일부청구와 과실상계에 관하여 통설·판례는 ____이다 — 손해 전액에서 과실비율만큼 감액한 잔액이 청구액을 넘으면 청구 전액을 인용한다.","a":"외측설"},{"h":"나. 과실상계(제396조, 제763조)","q":"과실상계와 ____를 모두 하여야 하는 경우에는 과실상계를 먼저 한다.","a":"손익상계"},{"h":"나. 과실상계(제396조, 제763조)","q":"국민건강보험 급여를 받은 피해자의 손해배상청구에서는 전체 기왕치료비에서 먼저 ____을 공제한 후 과실상계를 한다.","a":"공단 부담금"},{"h":"나. 과실상계(제396조, 제763조)","q":"손해배상액의 예정, 해제로 인한 원상회복, 피해자의 부주의를 이용한 고의의 불법행위에는 ____가 적용되지 않는다.","a":"과실상계"},{"h":"나. 과실상계(제396조, 제763조)","q":"손해담보계약에 기한 담보권리자의 청구는 손해배상청구가 아니라 ____이므로 과실상계가 준용·유추되지 않는다.","a":"이행청구"},{"h":"나. 과실상계(제396조, 제763조)","q":"호의동승자가 운행자를 상대로 손해배상을 청구하는 경우, 운전자의 과실은 ____ 과실로 참작되지 않는다.","a":"피해자측"},{"h":"다. 금전채무불이행 특칙(제397조)","q":"제397조 제1항 단서는 약정이율이 ____ 이상인 경우에만 적용된다.","a":"법정이율"},{"h":"다. 금전채무불이행 특칙(제397조)","q":"금전채무불이행에서 채권자는 손해를 증명할 필요가 없고, 채무자는 ____을 항변하지 못한다(제397조 제2항).","a":"무과실"},{"h":"4. 손해배상액의 예정","q":"위약금은 손해배상액의 예정으로 ____된다(제398조 제4항).","a":"추정"},{"h":"4. 손해배상액의 예정","q":"위약벌에는 제398조 제2항을 유추적용한 ____이 인정되지 않는다(현재 판례).","a":"감액"},{"h":"4. 손해배상액의 예정","q":"손해배상액의 예정이 있으면 채권자는 손해의 발생과 금액을 증명할 필요가 없으나, ____ 사실과 예정의 존재·내용은 증명하여야 한다.","a":"채무불이행"},{"h":"4. 손해배상액의 예정","q":"채무불이행을 이유로 계약을 해제·해지하더라도 원칙적으로 손해배상액의 예정은 ____되지 않는다.","a":"실효"}],"채총24":[{"h":"채권자지체(제400조)","q":"채권자지체의 법적 성질에 관한 통설·판례는 ____이다 — 채권자의 귀책사유를 요하지 않는다.","a":"법정책임설"},{"h":"채권자지체(제400조)","q":"채권자지체만으로는 채무자가 손해배상을 청구하거나 계약을 ____할 수 없다.","a":"해제"},{"h":"채권자지체(제400조)","q":"당사자가 급부수령의무·이행협력의무를 약정하였거나 ____상 그 의무가 인정되는 특별한 사정이 있으면, 그 위반으로 계약 목적을 달성할 수 없을 때 채무자가 계약을 해제할 수 있다.","a":"신의칙"},{"h":"채권자지체의 효과","q":"변제제공의 효과로 채무자는 ____ 책임을 면한다(제461조).","a":"채무불이행"},{"h":"채권자지체의 효과","q":"수령지체 중에는 채무자의 주의의무가 경감되어 ____이 없으면 불이행으로 인한 책임을 지지 않는다(제401조).","a":"고의 또는 중과실"},{"h":"채권자지체의 효과","q":"수령지체 중에는 채무자가 ____를 지급할 의무를 면한다(제402조).","a":"이자"},{"h":"채권자지체의 효과","q":"수령지체로 목적물의 보관 또는 변제의 비용이 증가한 때 그 증가액은 ____의 부담으로 한다(제403조).","a":"채권자"},{"h":"채권자지체의 효과","q":"수령지체 중 쌍방의 책임 없는 사유로 이행불능이 되면 ____이 채권자에게 이전하여 채무자는 반대급부를 청구할 수 있다(제538조 제1항 2문).","a":"대가위험"}],"채총25":[{"h":"1. 요건(제404조)","q":"채권자대위소송에서 피보전채권의 존재, 보전의 필요성, 채무자의 권리 불행사 요건이 흠결되면 소는 ____된다.","a":"각하"},{"h":"1. 요건(제404조)","q":"채권자대위소송에서 피대위권리가 존재하지 않는 것으로 밝혀지면 청구는 ____된다.","a":"기각"},{"h":"가. 피보전채권","q":"피보전채권의 이행기가 도래하지 않았더라도 법원의 허가를 받거나 피대위권리의 행사가 ____인 경우에는 대위할 수 있다.","a":"보존행위"},{"h":"나. 보전의 필요성","q":"피보전채권이 금전채권이면 원칙적으로 채무자의 ____이 보전의 필요성 요건이다(통설·판례).","a":"무자력"},{"h":"나. 보전의 필요성","q":"보전의 필요성 판단기준(두문자 밀·현·간)은 피보전채권과 피대위권리의 밀접한 관련, 현실적 이행의 유효·적절한 확보, 채무자의 재산관리 자유에 대한 부당한 ____이 없을 것이다.","a":"간섭"},{"h":"나. 보전의 필요성","q":"수임인의 ____청구권(제688조 제2항)을 보전하기 위한 대위는 금전채권임에도 채무자의 무자력을 요하지 않는다.","a":"대변제"},{"h":"나. 보전의 필요성","q":"금전채권을 보전하기 위한 공유물분할청구권의 대위행사는 원칙적으로 ____이 인정되지 않는다(전합).","a":"보전의 필요성"},{"h":"다. 채무자의 권리 불행사","q":"채무자가 이미 제3채무자를 상대로 소를 제기하여 패소판결이 확정된 경우, 채권자의 대위소송은 ____이 없어 각하된다.","a":"당사자적격"},{"h":"라. 피대위권리","q":"이혼으로 인한 재산분할청구권은 협의·심판으로 구체화되기 전에는 채권자대위의 대상도, ____에 속하는 재산도 아니다.","a":"파산재단"},{"h":"라. 피대위권리","q":"유류분반환청구권은 ____상 일신전속권이므로, 유류분권리자가 권리를 쓰겠다는 확정적 의사를 밝히지 않는 한 대위할 수 없다.","a":"행사"},{"h":"라. 피대위권리","q":"위자료청구권은 ____상 일신전속권이 아니어서 상속되지만, 합의·판결로 구체적으로 확정되기 전에는 대위할 수 없다.","a":"귀속"},{"h":"가. 행사방법","q":"대위소송에서 금전지급·물건인도·____를 구하는 경우에는 대위채권자가 직접 자기에게 이행하라고 청구할 수 있다.","a":"등기말소"},{"h":"나. 대위권행사의 통지(제405조 제2항)","q":"대위권 행사의 통지를 받거나 이를 안 채무자가 그 후 피대위권리를 ____하여도 채권자에게 대항하지 못한다.","a":"처분"},{"h":"나. 대위권행사의 통지(제405조 제2항)","q":"채무자의 채무불이행으로 계약이 ____된 것은 제405조 제2항의 '처분'이 아니므로, 제3채무자는 이를 채권자에게 대항할 수 있다(전합).","a":"법정해제"},{"h":"나. 대위권행사의 통지(제405조 제2항)","q":"대위권 행사의 통지 후 피대위채권에 대하여 내려진 ____은, 우선권 있는 채권에 기한 것이라는 특별한 사정이 없는 한 무효이다.","a":"전부명령"},{"h":"라. 제3채무자의 지위","q":"채권자대위소송에서 제3채무자는 피보전채권의 ____ 완성을 주장할 수 없다 — 그 원용은 시효로 직접 이익을 받는 자만 할 수 있다.","a":"소멸시효"},{"h":"나. 보전의 필요성","q":"금전채권을 보전하기 위한 대위에서 채무자의 무자력은 ____ 당시를 기준으로 채권자가 주장·증명하여야 한다.","a":"변론종결"}],"채총27":[{"h":"제3자에 의한 채권침해","q":"제3자에 의한 채권침해는 결국 ____(제750조)의 문제로 해결한다.","a":"불법행위"},{"h":"제3자에 의한 채권침해","q":"채권은 ____ 효력이 없어 채권자 상호 간에 자유경쟁이 허용되므로, 제3자가 채권을 침해하였다고 곧바로 불법행위가 되지는 않는다.","a":"배타적"},{"h":"제3자에 의한 채권침해","q":"독립한 경제주체 사이의 경쟁적 계약관계에서 단순히 계약 내용을 알면서 이를 위반하는 계약을 체결한 것만으로는 고의·과실과 ____이 인정되지 않는다.","a":"위법성"},{"h":"제3자에 의한 채권침해","q":"3자간 등기명의신탁에서 수탁자가 부동산을 처분하면 횡령죄로 처벌되지 않더라도, 신탁자의 ____을 침해하는 불법행위가 된다.","a":"소유권이전등기청구권"},{"h":"제3자에 의한 채권침해","q":"제3자가 채무자와 적극 공모하거나 사회상규에 반하는 부정한 수단으로 채무자의 ____을 감소시켜 채권의 실행을 곤란하게 하면 불법행위가 된다.","a":"책임재산"}],"채총26":[{"h":"1. 요건(제406조)","q":"사해행위취소소송에서 피보전채권이 존재하지 않으면, 채권자대위소송과 달리 청구를 ____한다.","a":"기각"},{"h":"가. 피보전채권","q":"사해행위 이후 성립한 채권도, 사해행위 당시 기초가 되는 법률관계가 있고 가까운 장래에 성립할 고도의 ____이 있으며 실제로 성립하면 피보전채권이 될 수 있다(기·개·실).","a":"개연성"},{"h":"나. 사해행위","q":"사해성은 채무자의 일반재산이 감소하여 ____(무자력)가 초래되거나 악화되는 것을 말한다.","a":"채무초과"},{"h":"나. 사해행위","q":"적극재산을 산정할 때 채권은 ____하게 변제받을 수 있는 확실성이 있는 경우에만 포함한다.","a":"용이"},{"h":"나. 사해행위","q":"위탁자의 신탁계약상 수익권은, 그 처분에 수익권자의 동의가 필요하여 실질적 가치가 없으면 ____에서 제외된다.","a":"적극재산"},{"h":"나. 사해행위","q":"유일한 재산인 부동산을 소비하기 쉬운 금전으로 바꾸는 매각은 원칙적으로 사해행위이고, 채무자의 ____가 추정된다.","a":"사해의사"},{"h":"다. 사해의사(악의)","q":"수익자의 선의를 판단할 때 수익자에게 ____이 있는지는 묻지 않는다.","a":"과실"},{"h":"2. 행사","q":"채권자취소소송은 형성의 소이지만, 취소 판결이 확정되기 전에도 취소를 전제로 한 ____청구를 병합할 수 있다.","a":"원상회복"},{"h":"2. 행사","q":"여러 채권자가 동시에 또는 시기를 달리하여 사해행위취소를 구하여도 ____에 해당하지 않는다.","a":"중복제소"},{"h":"가. 제척기간","q":"채권자취소권은 채권자가 취소원인을 안 날부터 ____년, 법률행위가 있은 날부터 5년 내에 행사하여야 한다(제406조 제2항).","a":"1"},{"h":"가. 제척기간","q":"수익자를 상대로 승소판결이 확정되었더라도 그 효력은 ____에게 미치지 않으므로, 제척기간 내에 별도로 소를 제기하여야 한다.","a":"전득자"},{"h":"나. 상대방","q":"사해행위 후 제3자가 저당권이나 지상권을 취득한 경우, 채권자는 수익자를 상대로 원칙적으로 ____을 청구할 수 있다.","a":"가액배상"},{"h":"라. 원상회복 방법","q":"가액배상의 한도는 피보전채권액, 목적물의 공동담보가액, 수익자·전득자의 ____ 중 가장 적은 금액이다.","a":"취득이익액"},{"h":"라. 원상회복 방법","q":"가액배상의 한도를 정하는 세 금액은 모두 ____ 당시를 기준으로 산정한다.","a":"사실심 변론종결"},{"h":"라. 원상회복 방법","q":"수익자와 전득자의 가액배상의무는 ____ 관계에 있다.","a":"부진정연대"},{"h":"라. 원상회복 방법","q":"전부취소와 원물반환을 구하는 청구에는 일부취소와 가액배상을 구하는 취지가 포함되어 있으므로, 법원은 청구취지의 ____ 없이 가액배상을 명할 수 있다.","a":"변경"},{"h":"라. 원상회복 방법","q":"저당권이 설정된 부동산이 사해행위로 이전된 후 변제로 저당권이 말소된 경우, 부동산 가액에서 ____을 공제한 잔액의 한도에서 일부취소와 가액배상을 명한다.","a":"피담보채권액"},{"h":"라. 원상회복 방법","q":"가압류된 부동산이 사해행위로 이전된 후 가압류가 해제된 경우에는 ____을 명하여야 하고, 가액배상을 하더라도 가압류 청구채권액을 공제하지 않는다.","a":"원물반환"},{"h":"라. 원상회복 방법","q":"원물반환 판결이 확정된 후에는 원물반환이 불능이 되더라도 다시 가액배상을 청구할 수 없다 — ____이 없어 각하된다.","a":"권리보호이익"},{"h":"3. 채권자취소권 행사의 효과","q":"사해행위취소의 효력은 ____ 효력이어서, 회복된 재산은 취소채권자 등과 수익자 사이에서만 책임재산으로 취급되고 채무자가 직접 권리를 취득하지 않는다.","a":"상대적"}],"채총28":[{"h":"2. 양도성과 제한","q":"가압류된 채권을 양수한 자는, 가압류채권자가 본안에서 승소하는 등 ____을 취득하면 가압류의 효력에 대항하지 못한다.","a":"집행권원"},{"h":"2. 양도성과 제한","q":"양도금지특약을 위반한 채권양도는 양수인이 악의이거나 ____이 있으면 무효이다.","a":"중과실"},{"h":"2. 양도성과 제한","q":"양도금지특약에 관한 양수인의 악의·중과실은 ____가 증명하여야 한다.","a":"채무자"},{"h":"2. 양도성과 제한","q":"양도금지특약을 위반한 채권양도의 효력에 관하여 전원합의체는 ____ 효력설을 유지하였다.","a":"물권적"},{"h":"2. 양도성과 제한","q":"양도금지특약이 있는 채권이라도 ____에 의한 이전은 집행채권자의 선의·악의를 불문하고 유효하다.","a":"전부명령"},{"h":"2. 양도성과 제한","q":"악의·중과실 양수인에 대한 양도를 채무자가 사후에 승낙하면, 무효인 양도가 추인되어 ____부터 유효로 되고 소급효는 없다.","a":"승낙시"},{"h":"가. 통지, 승낙(제450조 제1항)","q":"양수인도 양도인의 사자 또는 ____으로서 양도통지를 할 수 있다.","a":"대리인"},{"h":"가. 통지, 승낙(제450조 제1항)","q":"채무자가 ____을 보류하지 않고 승낙하면, 양도인에게 대항할 수 있는 사유로 양수인에게 대항하지 못한다(제451조 제1항).","a":"이의"},{"h":"가. 통지, 승낙(제450조 제1항)","q":"제451조 제1항의 '양도인에게 대항할 수 있는 사유'는 채권의 성립·존속·행사를 저지·배척하는 사유를 말하고, 채권의 ____에 관한 사유는 포함되지 않는다.","a":"귀속"},{"h":"가. 통지, 승낙(제450조 제1항)","q":"임대차보증금반환채권의 양도에 임대인이 이의를 보류하지 않고 승낙하였더라도, 목적물 인도 시까지 생긴 ____ 등 임차인의 채무는 보증금에서 당연히 공제된다.","a":"연체차임"},{"h":"나. 동일성(제451조 제2항)","q":"매매대금채권의 양도통지 후에 채무불이행으로 계약이 깨진 경우에도, 채무자는 양수인에게 ____로 대항할 수 있다.","a":"해제"},{"h":"다. 금반언(제452조 제1항)","q":"채권양도가 해제되어 소급하여 무효가 된 경우에도 제452조 제1항이 ____된다.","a":"유추적용"},{"h":"4. 제3자에 대한 대항요건","q":"채권의 이중양도에서 양수인 상호 간의 우열은 확정일자의 선후가 아니라, 확정일자 있는 통지의 ____ 일시의 선후로 결정한다(전합).","a":"도달"},{"h":"4. 제3자에 대한 대항요건","q":"확정일자 있는 양도통지와 가압류명령이 제3채무자에게 동시에 도달한 경우, 양수인과 가압류채권자는 각자 ____을 청구할 수 있다.","a":"전액"},{"h":"4. 제3자에 대한 대항요건","q":"확정일자 있는 통지로 대항요건을 갖춘 채권양도 후에 양도인의 다른 채권자가 한 압류·가압류는 ____이다.","a":"무효"},{"h":"4. 제3자에 대한 대항요건","q":"임대차계약상 지위의 포괄적 양도가 있는 경우에도, 임대차보증금반환채권의 양도 부분을 제3자에게 대항하려면 ____ 있는 증서에 의한 통지·승낙이 있어야 한다.","a":"확정일자"},{"h":"5. 채권 가압류·압류와 이행청구","q":"채권에 가압류가 있어도 채무자는 제3채무자를 상대로 이행청구소송을 제기할 수 있고, 법원은 가압류를 이유로 배척하지 않고 청구를 ____한다.","a":"인용"},{"h":"5. 채권 가압류·압류와 이행청구","q":"소유권이전등기청구권이 가압류된 경우 법원은 가압류의 해제를 ____으로 하여 청구를 인용한다(전합).","a":"조건"}],"채총29":[{"h":"1. 면책적 채무인수","q":"면책적 채무인수가 있어도 채무의 ____은 유지되므로 소멸시효 기간이 달라지지 않는다.","a":"동일성"},{"h":"1. 면책적 채무인수","q":"채무인수는 ____이 있어, 인수의 원인관계가 무효·취소되어도 채무인수의 효력에는 영향이 없다.","a":"무인성"},{"h":"1. 면책적 채무인수","q":"채무자와 제3자 사이의 계약에 의한 면책적 채무인수에서 채권자의 ____은 효력요건이다(제454조).","a":"승낙"},{"h":"1. 면책적 채무인수","q":"상속인 중 1인이 법정상속분을 초과하여 금전채무를 부담하기로 하는 협의는 ____ 채무인수이므로 채권자의 승낙이 있어야 효력이 생긴다.","a":"면책적"},{"h":"1. 면책적 채무인수","q":"채무인수의 승낙 여부를 최고받은 채권자가 상당한 기간 내에 확답을 발송하지 않으면 ____한 것으로 본다(제455조).","a":"거절"},{"h":"1. 면책적 채무인수","q":"인수인은 전 채무자의 항변사유로 채권자에게 대항할 수 있으나, 계약당사자가 아니므로 ____이나 해제권은 행사할 수 없다.","a":"취소권"},{"h":"1. 면책적 채무인수","q":"면책적 채무인수가 있으면 전 채무자의 채무에 대한 보증이나 제3자가 제공한 담보는 원칙적으로 ____한다(제459조).","a":"소멸"},{"h":"2. 병존적 채무인수","q":"채무인수가 채무자를 면책시키는 것인지 채무자와 함께 채무를 부담하는 것인지 분명하지 않으면 ____ 채무인수로 해석한다.","a":"병존적"},{"h":"2. 병존적 채무인수","q":"병존적 채무인수에서 인수인이 채무자의 부탁을 받았다면 채무자와 인수인은 ____ 관계에 있다.","a":"연대채무"},{"h":"2. 병존적 채무인수","q":"채무자의 부탁 없이 이루어져 주관적 공동관계가 없는 병존적 채무인수에서 채무자와 인수인은 ____ 관계에 있다.","a":"부진정연대"},{"h":"3. 계약인수","q":"계약인수는 양도인, 양수인, 잔류당사자 ____인의 관여가 있어야 효력이 생긴다.","a":"3"},{"h":"4. 이행인수","q":"이행인수인은 채무자에 대하여만 이행의무를 부담하므로, ____는 이행인수인에게 직접 이행을 청구할 수 없다.","a":"채권자"},{"h":"나. 매매계약과 매수인의 이행인수","q":"부동산 매수인이 근저당권의 피담보채무나 임대차보증금반환채무를 인수하고 그만큼 매매대금에서 공제하기로 한 약정은, 특별한 사정이 없는 한 ____로 본다.","a":"이행인수"},{"h":"나. 매매계약과 매수인의 이행인수","q":"이행인수와 병존적 채무인수의 구별기준은, 인수인에 대한 직접의 ____을 제3자에게 취득시킬 의사가 있는지 여부이다.","a":"채권"},{"h":"나. 매매계약과 매수인의 이행인수","q":"채무를 인수하고 대금에서 공제하기로 한 매수인이 인수채무를 현실적으로 변제하지 않았다는 사정만으로는, 매도인이 계약을 ____할 수 없다.","a":"해제"},{"h":"나. 매매계약과 매수인의 이행인수","q":"이행인수 불이행으로 인한 손해배상의 범위는 통상손해를 한도로 하고, 미변제로 늘어난 ____이 통상손해이다.","a":"원리금"}],"채총30":[{"h":"2. 변제제공","q":"채권자가 수령하지 않을 의사가 명백하여 번의 가능성이 없으면 ____조차 필요 없이 채무불이행 책임을 면한다.","a":"구두제공"},{"h":"3. 변제의 당사자","q":"제3자의 변제는 허용되지만 제3자의 ____는 허용되지 않는다(통설·판례).","a":"상계"},{"h":"3. 변제의 당사자","q":"공동저당 부동산 중 물상보증인 소유 부동산의 후순위담보권자는 ____가 가능하므로, 채무자의 의사에 반하여 대위변제할 이해관계가 없다.","a":"물상대위"},{"h":"3. 변제의 당사자","q":"채권의 준점유자에 대한 변제는 변제자가 ____인 때에 한하여 효력이 있다(제470조).","a":"선의·무과실"},{"h":"3. 변제의 당사자","q":"채권의 준점유자에 대한 변제에서 선의·무과실의 증명책임은 ____에게 있다.","a":"변제자"},{"h":"3. 변제의 당사자","q":"압류가 경합된 상태에서 내려진 전부명령은 무효이지만, 제3채무자가 선의·무과실로 전부채권자에게 변제하면 채권의 ____에 대한 변제로서 유효하다.","a":"준점유자"},{"h":"3. 변제의 당사자","q":"수령권한 없는 자에 대한 변제로 채권자가 '이익을 받은 경우'에는, 변제받은 것을 채권자에게 전달한 경우나 채권자가 사후에 ____한 경우가 포함된다.","a":"추인"},{"h":"4. 변제의 충당","q":"변제충당의 순서는 합의충당 → 비용·이자·원본 → ____ → 법정충당이다.","a":"지정충당"},{"h":"4. 변제의 충당","q":"변제 사실의 증명책임은 ____에게 있고, 채권자가 다른 채무에 충당되었다고 주장하려면 그 사유를 증명하여야 한다.","a":"채무자"},{"h":"4. 변제의 충당","q":"담보권 실행을 위한 경매에서는 합의충당이나 지정충당이 허용되지 않고 획일적으로 ____만 적용된다.","a":"법정충당"},{"h":"4. 변제의 충당","q":"법정충당(제477조)의 순서는 이행기 도래 여부 → ____이 많은 채무 → 이행기가 먼저 도래한 채무 → 채무액 비례이다.","a":"변제이익"},{"h":"4. 변제의 충당","q":"부진정연대채무에서 소액채무자가 일부를 변제하면 지연손해금, ____의 순서로 충당된다.","a":"원본"},{"h":"5. 변제자대위","q":"변제자대위로 원채권과 담보권을 행사할 수 있는 범위는 ____의 범위로 한정된다.","a":"구상권"},{"h":"라. 대위자와 채권자 사이","q":"일부 대위변제자는 저당권 일부이전의 부기등기를 받을 수 있지만, 배당에서는 ____가 잔존 채권액 전액에 관하여 우선한다.","a":"채권자"},{"h":"라. 대위자와 채권자 사이","q":"공동저당에서 채권자가 채무자 소유 부동산의 저당권을 말소해 준 뒤 물상보증인 소유 부동산이 경매되면, 물상보증인은 제____조에 따라 면책을 주장할 수 있다.","a":"485"},{"h":"마. 법정대위자 상호간(제482조 제2항)","q":"저당부동산을 채무자로부터 양수한 제3취득자는 물상보증인에 대하여 채권자를 ____할 수 없다(전합).","a":"대위"},{"h":"마. 법정대위자 상호간(제482조 제2항)","q":"법정대위자 상호 간에는 자기의 ____을 넘는 대위변제를 하여야 다른 대위자에 대하여 대위할 수 있다.","a":"부담부분"},{"h":"마. 법정대위자 상호간(제482조 제2항)","q":"변제자대위에서 물상보증을 선 사람으로부터 저당물을 양수한 제3취득자는 ____으로 본다.","a":"물상보증인"}],"채총31":[{"h":"1. 대물변제(제466조)","q":"대물변제는 유상계약이자 ____계약이다 — 본래 급부에 갈음하는 다른 급여를 현실적으로 하여야 성립한다.","a":"요물"},{"h":"1. 대물변제(제466조)","q":"부동산으로 대물변제하는 경우 소유권이전 ____가 완료되어야 대물변제가 성립한다.","a":"등기"},{"h":"1. 대물변제(제466조)","q":"대물변제도 유상계약이므로 목적물에 하자가 있으면 매도인의 ____ 규정이 준용된다.","a":"담보책임"},{"h":"1. 대물변제(제466조)","q":"본래의 채무가 존재하지 않았다면 대물변제는 ____이고 소유권이전의 효과도 생기지 않는다.","a":"무효"},{"h":"1. 대물변제(제466조)","q":"채무 변제와 관련하여 다른 채권을 양도한 경우 ____ 또는 변제의 방법으로 양도한 것으로 추정되어 원채권은 소멸하지 않는다.","a":"담보"},{"h":"1. 대물변제(제466조)","q":"채무자의 부동산에 관하여 채권자 앞으로 소유권이전등기가 마쳐진 경우 ____로 추정되고, 담보 목적이라고 주장하는 자가 이를 증명하여야 한다.","a":"대물변제"},{"h":"1. 대물변제(제466조)","q":"대물변제 예약에서 예약 당시 재산의 가액은 차용액과 ____의 합산액을 넘지 못한다(제607조).","a":"이자"},{"h":"1. 대물변제(제466조)","q":"가등기담보법은 (준)____로 인한 채무를 담보하는 경우에만 적용되고, 매매대금채무를 담보하는 경우에는 적용되지 않는다.","a":"소비대차"},{"h":"2. 공탁(제487조)","q":"채권자 ____란 객관적으로 채권자는 존재하나 채무자가 선량한 관리자의 주의를 다해도 채권자가 누구인지 알 수 없는 경우를 말한다.","a":"불확지"},{"h":"2. 공탁(제487조)","q":"변제공탁은 ____하는 확정채무에 대하여만 할 수 있고, 장래의 채무나 불확정채무에 대하여는 할 수 없다.","a":"현존"},{"h":"2. 공탁(제487조)","q":"변제공탁은 채무 ____을 공탁하여야 하고, 일부만 공탁하면 그 부분의 채무도 소멸하지 않는다.","a":"전액"},{"h":"2. 공탁(제487조)","q":"변제공탁에 조건을 붙일 수 없으나, ____ 관계에 있는 반대급부의 제공을 수령조건으로 하는 것은 허용된다.","a":"동시이행"},{"h":"2. 공탁(제487조)","q":"임대차보증금을 공탁하면서 건물 인도확인서의 첨부를 반대급부 조건으로 붙이면, ____을 조건으로 한 것이어서 변제의 효력이 없다.","a":"선이행"},{"h":"2. 공탁(제487조)","q":"변제공탁이 적법하면 ____에 변제의 효력이 생긴다 — 채권자가 출급하지 않아도 같다.","a":"공탁한 때"},{"h":"2. 공탁(제487조)","q":"공탁물 ____청구권과 회수청구권은 별개의 권리이므로, 전자에 대한 압류는 후자에 영향이 없다.","a":"출급"},{"h":"5. 혼동(제507조)","q":"지명채권의 양수인이 그 채권의 채무자이면 채권은 ____으로 소멸한다(제507조).","a":"혼동"}],"채총32":[{"h":"1. 서설","q":"공제는 상계와 유사하나, 원칙적으로 상계적상·상계금지·____에 관한 규정이 적용되지 않는다.","a":"기판력"},{"h":"2. 요건(제492조) = 상계적상","q":"상속인이 ____을 하면 상속재산과 고유재산이 분리되므로, 상속채권자는 피상속인에 대한 채권으로 상속인에 대한 채무와 상계할 수 없다.","a":"한정승인"},{"h":"2. 요건(제492조) = 상계적상","q":"압류채권자는 ____을 자동채권으로 하여 상계할 수 없다.","a":"피압류채권"},{"h":"2. 요건(제492조) = 상계적상","q":"이행기의 정함이 없는 채권(부당이득반환채권)은 ____과 동시에 이행기가 도래한다.","a":"성립"},{"h":"2. 요건(제492조) = 상계적상","q":"자동채권에 동시이행의 ____이 붙어 있으면 상계할 수 없다.","a":"항변권"},{"h":"가. 고의 불법행위 손해배상채권(제496조)","q":"고의의 불법행위로 인한 손해배상채권을 ____으로 하는 상계는 금지된다(제496조).","a":"수동채권"},{"h":"가. 고의 불법행위 손해배상채권(제496조)","q":"제496조는 ____에 의한 불법행위에는 유추·확장 적용되지 않는다.","a":"중과실"},{"h":"가. 고의 불법행위 손해배상채권(제496조)","q":"피용자의 고의 불법행위로 제756조의 책임을 지는 ____도 제496조에 따라 상계할 수 없다.","a":"사용자"},{"h":"가. 고의 불법행위 손해배상채권(제496조)","q":"기망으로 소비대차를 체결하게 한 차주에 대하여 대주가 ____상 채권인 대여금·이자의 지급만을 구하는 경우에는 제496조가 유추적용되지 않는다.","a":"계약"},{"h":"다. 지급 금지된 채권(제498조)","q":"가압류명령을 받은 제3채무자가 반대채권으로 상계하여 가압류채권자에게 대항하려면, 자동채권의 변제기가 수동채권의 변제기와 동시이거나 그보다 ____ 도래하여야 한다(전합).","a":"먼저"},{"h":"다. 지급 금지된 채권(제498조)","q":"자동채권이 수동채권과 ____ 관계에 있으면, 가압류 이후에 발생한 자동채권이라도 상계로 가압류채권자에게 대항할 수 있다.","a":"동시이행"},{"h":"4. 상계의 방법(제493조 제1항)","q":"채권이 일부양도되면 각 ____채권이 성립하고, 채무자는 양도인에 대한 반대채권으로 양도인과 양수인 누구를 상대로든 상계할 수 있다.","a":"분할"},{"h":"5. 상계의 효과(제493조 제2항)","q":"상계의 ____효는 정산의 기준시기를 앞당기는 것일 뿐, 상계 의사표시 전에 이미 발생한 사실을 없애지 않는다.","a":"소급"},{"h":"5. 상계의 효과(제493조 제2항)","q":"채권양수인이 양수채권을 자동채권으로 상계하는 경우 상계적상일은 채권양도의 ____을 갖춘 시점이다.","a":"대항요건"},{"h":"5. 상계의 효과(제493조 제2항)","q":"상계충당(제499조)에는 ____에 관한 규정이 준용된다.","a":"변제충당"},{"h":"5. 상계의 효과(제493조 제2항)","q":"제492조 제1항의 '이행기 도래'는 채권자가 이행을 ____할 수 있는 시기를 말하고, 이행지체에 빠지는 시기가 아니다.","a":"청구"},{"h":"6. 상계와 소멸시효(제495조)","q":"매도인·수급인의 담보책임에 기한 손해배상채권이 ____을 지났더라도, 그 경과 전에 상계할 수 있었다면 제495조를 유추적용하여 상계할 수 있다.","a":"제척기간"},{"h":"6. 상계와 소멸시효(제495조)","q":"임대차 존속 중 차임채권의 소멸시효가 완성된 경우, 임대인은 상계는 할 수 없으나 제495조를 유추적용하여 보증금에서 ____할 수 있다.","a":"공제"}],"채총33":[{"h":"1. 수인의 채권자·채무자 서론","q":"절대효가 인정되는 채권소멸사유(변·대·공·상·경·면·혼)는 변제, 대물변제, 공탁, 상계, ____, 면제, 혼동이다.","a":"경개"},{"h":"1. 수인의 채권자·채무자 서론","q":"절대효의 범위가 넓을수록 ____에게 유리하다(이행청구는 예외).","a":"채무자"},{"h":"2. 분할채권관계","q":"가분급부에서 채권자나 채무자가 여럿이고 다른 의사표시가 없으면 ____채권관계가 원칙이다(제408조).","a":"분할"},{"h":"가. 불가분채권(제409·410조)","q":"불가분채권에서 채권자 1인에게 생긴 사유 중 절대효가 있는 것은 ____와 이행이다.","a":"청구"},{"h":"나. 불가분채무(제411조)","q":"건물 공유자들이 공동으로 임대하고 받은 보증금의 반환채무는 ____채무이다.","a":"불가분"},{"h":"나. 불가분채무(제411조)","q":"공동상속인들의 건물철거의무는 불가분채무로서, 각자 ____의 한도에서 건물 전체에 대하여 철거의무를 진다.","a":"지분"},{"h":"나. 불가분채무(제411조)","q":"직접점유자와 간접점유자의 부당이득반환채무는 ____ 관계에 있다.","a":"부진정연대"},{"h":"나. 불가분채무(제411조)","q":"불가분채무의 대내관계에는 ____채무에 관한 규정이 준용된다.","a":"연대"},{"h":"나. 불가분채무(제411조)","q":"불가분채무자 사이의 부담부분은 ____한 것으로 추정된다.","a":"균등"},{"h":"나. 불가분채무(제411조)","q":"임대인이 사망하여 공동상속인들이 공동임대인이 된 경우 임대차보증금 반환채무는 불가분채무이고, 내부 부담부분은 ____이다.","a":"법정상속분"}],"채총34":[{"h":"1. 서설, 대외관계","q":"연대채무자 1인에 대한 법률행위의 무효나 취소의 원인은 다른 연대채무자의 채무에 ____을 미치지 않는다(제415조).","a":"영향"},{"h":"1. 서설, 대외관계","q":"수인이 1인 또는 전원에게 상행위가 되는 행위로 채무를 부담한 때에는 ____하여 변제할 책임이 있다(상법 제57조 제1항).","a":"연대"},{"h":"2. 1인에게 생긴 사유 — 절대적 효력","q":"연대채무에서는 변·대·공·상·경·면·혼 외에 ____완성과 이행청구도 절대효가 있다.","a":"소멸시효"},{"h":"2. 1인에게 생긴 사유 — 절대적 효력","q":"연대채무자 1인에 대한 이행청구는 절대효가 있으므로, 그에 따른 시효중단과 ____의 효과도 다른 연대채무자에게 미친다.","a":"이행지체"},{"h":"2. 1인에게 생긴 사유 — 절대적 효력","q":"상계할 채권이 있는 연대채무자가 상계하지 않는 경우, 다른 연대채무자는 그 채무자의 ____에 한하여 상계할 수 있다(제418조 제2항).","a":"부담부분"},{"h":"2. 1인에게 생긴 사유 — 절대적 효력","q":"연대채무에서 그 채무자의 부담부분에 한하여 절대효가 있는 사유는 소멸시효 완성, ____, 혼동이다.","a":"면제"},{"h":"2. 1인에게 생긴 사유 — 절대적 효력","q":"승인·압류·가압류에 의한 시효중단이나 시효이익의 포기는 다른 연대채무자에게 ____ 효력만 있다.","a":"상대적"},{"h":"3. 대내관계","q":"연대채무자의 구상권 범위는 출재액, 면책일 이후의 ____, 피할 수 없는 비용 기타 손해이다(제425조).","a":"법정이자"},{"h":"3. 대내관계","q":"구상권의 요건인 '출재'는 자기 재산의 감소를 요하므로, 면제나 ____으로 공동면책된 경우에는 구상할 수 없다.","a":"시효완성"},{"h":"3. 대내관계","q":"연대채무자는 출재액이 자기의 부담부분을 넘지 않아도 구상할 수 있으나, ____채무자와 공동보증인 사이에서는 부담부분을 넘어야 구상할 수 있다.","a":"부진정연대"},{"h":"3. 대내관계","q":"공동불법행위자 사이의 구상 범위에는 응소에 든 ____도 포함된다.","a":"소송비용"},{"h":"3. 대내관계","q":"사후통지를 게을리한 경우, 다른 연대채무자가 ____로 면책행위를 하였다면 자기의 면책행위가 유효함을 주장할 수 있다(제426조 제2항).","a":"선의"},{"h":"3. 대내관계","q":"연대채무자 중 상환할 자력이 없는 자가 있으면, 그 부담부분은 구상권자와 다른 자력 있는 채무자가 각자의 부담부분에 ____하여 부담한다(제427조).","a":"비례"}],"채총35":[{"h":"1. 의의","q":"부진정연대채무는 서로 별개의 원인으로 발생한 독립된 채무라도 동일한 ____ 목적을 가지는 채무이다.","a":"경제적"},{"h":"1. 의의","q":"법인과 대표자(제35조), 사용자와 피용자(제756조), 공동불법행위자(제760조)의 손해배상채무는 서로 ____채무 관계에 있다.","a":"부진정연대"},{"h":"2. 1인에게 생긴 사유","q":"부진정연대채무에서 절대적 효력이 있는 사유는 변제, 대물변제, 공탁, ____이다(마지막 것은 전합).","a":"상계"},{"h":"2. 1인에게 생긴 사유","q":"부진정연대채무자 1인이 반대채권을 가지고 있어도 다른 채무자는 그 채권으로 상계할 수 없다 — 제____조 제2항이 적용되지 않는다.","a":"418"},{"h":"2. 1인에게 생긴 사유","q":"금액이 다른 부진정연대채무에서 다액채무자가 일부를 변제하면 ____ 부담 부분부터 소멸한다(전합, 외측설).","a":"단독"},{"h":"3. 대내관계","q":"부진정연대채무자는 자기의 ____ 이상을 변제하여야 다른 채무자에게 구상할 수 있다(연대채무와 다름).","a":"부담부분"},{"h":"3. 대내관계","q":"부진정연대채무자 사이의 내부 분담 비율은 형평의 원칙상 각자의 ____의 정도에 따라 정해진다.","a":"고의·과실"},{"h":"3. 대내관계","q":"부진정연대채무자 사이에는 주관적 공동관계가 없으므로 상호 ____의무가 없고 제426조가 유추적용되지 않는다.","a":"통지"},{"h":"3. 대내관계","q":"연대채무 규정 중 제425조와 제____조는 부진정연대채무에도 적용된다.","a":"447"}],"채총36":[{"h":"나. 보증인 보호","q":"보증인의 '서명'은 타인이 대신할 수 없으나, ____은 타인이 대행하는 방법으로도 할 수 있다.","a":"기명날인"},{"h":"나. 보증인 보호","q":"채권자는 주채무자가 원본·이자 등을 ____개월 이상 이행하지 않으면 지체 없이 보증인에게 알려야 한다(제436조의2).","a":"3"},{"h":"다. 범위","q":"일부보증에서 주채무자가 일부를 변제하면 주채무 전부를 대상으로 충당하고, 보증인은 잔존 주채무에 대하여 보증 범위 내에서 책임진다(____설).","a":"외측"},{"h":"다. 범위","q":"보증채무 자체의 이행지체로 인한 지연손해금은 ____과 별도로 부담한다.","a":"보증한도액"},{"h":"2. 보증인의 권리","q":"주채무자가 항변을 포기하더라도 그 포기는 ____에게 효력이 없다(제433조).","a":"보증인"},{"h":"2. 보증인의 권리","q":"보증채무의 시효가 중단되었더라도 주채무의 시효가 완성되면 ____으로 보증채무도 당연히 소멸한다.","a":"부종성"},{"h":"가. 수탁보증인의 구상권","q":"수탁보증인이 미리 대위변제하더라도 주채무의 ____가 도래하기 전에는 사후구상권을 행사할 수 없다.","a":"변제기"},{"h":"가. 수탁보증인의 구상권","q":"수탁보증인이 예외적으로 사전구상할 수 있는 사유에는 과실 없이 변제할 재판을 받은 때, 주채무자의 파산, 채무의 ____ 도래 등이 있다(제442조).","a":"이행기"},{"h":"가. 수탁보증인의 구상권","q":"보증계약 후 채권자가 주채무자에게 허여한 ____으로는 수탁보증인의 사전구상권에 대항하지 못한다(제442조 제2항).","a":"기한"},{"h":"가. 수탁보증인의 구상권","q":"수탁보증인이 주채무자의 담보제공청구(제443조)에 응하여 담보를 특정하여 제공할 의사를 표시하면, 법원은 ____ 판결을 한다.","a":"동시이행"},{"h":"나. 비수탁보증인의 구상권","q":"비수탁보증인의 구상권은 단순 비수탁보증인과 주채무자의 ____에 반하는 비수탁보증인의 두 유형으로 나뉜다.","a":"의사"},{"h":"다. 통지의무(§445·446)","q":"보증인이 사전통지 없이 이중으로 면책행위를 한 경우에는, 주채무자가 사후통지를 게을리하였더라도 제446조를 들어 자기 면책행위가 ____하다고 주장할 수 없다.","a":"유효"},{"h":"라. 주채무자 수인인 경우","q":"연대채무자나 불가분채무자 중 1인을 위하여 보증한 자가 변제하면, 다른 채무자에 대하여 그 ____에 한하여 구상할 수 있다(제447조).","a":"부담부분"},{"h":"5. 연대보증·보증연대·공동보증","q":"연대보증에는 ____이 없어 최고·검색의 항변권이 인정되지 않는다.","a":"보충성"},{"h":"5. 연대보증·보증연대·공동보증","q":"채권자가 연대보증인 1인의 채무를 면제하더라도, 연대보증인들 사이에 ____의 특약이 없으면 다른 연대보증인에게 효력이 없다.","a":"보증연대"},{"h":"5. 연대보증·보증연대·공동보증","q":"연대보증인 사이의 내부 부담부분은 특약이 없으면 ____하고, 자기 부담부분을 초과하여 변제하여야 구상할 수 있다.","a":"평등"},{"h":"6. 계속적 보증","q":"특정된 확정채무를 보증한 이사는 사임하더라도 ____을 이유로 보증계약을 해지할 수 없다.","a":"사정변경"},{"h":"6. 계속적 보증","q":"최고액과 기간만 정해 둔 계속적 보증에서 이사가 사임하면 보증계약을 ____할 수 있으나, 그 전까지 발생한 채무에는 보증책임이 남는다.","a":"해지"}],"채각37":[{"h":"1. 계약의 종류","q":"쌍무계약은 모두 ____계약이다.","a":"유상"},{"h":"1. 계약의 종류","q":"현상광고, 대물변제, 계약금계약은 ____계약이다.","a":"요물"},{"h":"가. 합의","q":"규범적 해석으로도 의사의 합치가 인정되지 않으면 계약은 ____한다(숨은 불합의).","a":"불성립"},{"h":"나. 청약과 승낙","q":"상가·아파트의 분양광고는 통상 ____에 불과하다.","a":"청약의 유인"},{"h":"나. 청약과 승낙","q":"'선시공·후분양' 아파트에서는 ____ 자체가 분양계약의 목적물이므로, 광고와 다르게 시공되었더라도 광고 내용이 계약 내용이 되지 않는다.","a":"완공된 아파트"},{"h":"나. 청약과 승낙","q":"청약은 효력이 발생한 후에는 ____하지 못한다(제527조, 청약의 구속력).","a":"철회"},{"h":"나. 청약과 승낙","q":"승낙기간을 정한 청약은 그 기간 내에 승낙의 통지를 받지 못하면 ____한다(제528조 제1항).","a":"실효"},{"h":"나. 청약과 승낙","q":"승낙의 통지가 기간 후에 도달하였으나 보통 기간 내에 도달할 수 있는 발송인 경우, 청약자는 지체 없이 ____의 통지를 하여야 한다(제528조 제2항).","a":"연착"},{"h":"나. 청약과 승낙","q":"격지자 간의 계약은 승낙의 통지를 ____한 때 성립한다(제531조).","a":"발송"},{"h":"나. 청약과 승낙","q":"청약에 변경을 가한 승낙은 청약의 거절과 동시에 ____을 한 것으로 본다(제534조).","a":"새로운 청약"},{"h":"다. 계약체결상의 과실(제535조)","q":"계약체결상의 과실책임(제535조)은 ____·객관적·전부 불능으로 계약이 무효인 경우에 적용된다.","a":"원시적"},{"h":"다. 계약체결상의 과실(제535조)","q":"제535조의 배상범위는 신뢰이익이고, ____을 한도로 한다.","a":"이행이익"},{"h":"다. 계약체결상의 과실(제535조)","q":"제535조에 따라 배상을 청구하려면 상대방은 불능에 관하여 ____이어야 한다.","a":"선의·무과실"},{"h":"다. 계약체결상의 과실(제535조)","q":"의사의 불합치로 계약이 성립하지 않은 경우에는 제535조가 ____되지 않는다.","a":"유추적용"},{"h":"라. 계약교섭의 부당파기","q":"계약이 확실히 체결되리라는 정당한 신뢰를 준 뒤 상당한 이유 없이 체결을 거부하면, 계약자유 원칙의 한계를 넘는 ____가 된다.","a":"불법행위"},{"h":"라. 계약교섭의 부당파기","q":"계약교섭의 부당파기로 배상할 손해는 ____손해에 한정된다.","a":"신뢰"}],"채각38":[{"h":"1. 서설","q":"동시이행의 항변권은 상대방의 청구를 일시적으로 저지할 뿐인 ____ 항변권이고, 임의규정이다.","a":"연기적"},{"h":"1. 서설","q":"채권증서의 반환(제475조)은 변제와 동시이행관계에 있지 않으나, ____의 교부(제474조)는 변제와 동시이행관계에 있다.","a":"영수증"},{"h":"1. 서설","q":"임대차 종료 시 임차인의 목적물 인도의무와, 연체차임 등을 공제한 나머지 ____을 반환할 임대인의 의무는 동시이행관계에 있다.","a":"보증금"},{"h":"2. 요건(제536조 제1항)","q":"고유의 대가관계에 있지 않더라도 대가적 의미가 있어 이행상의 ____가 인정되면 동시이행의 항변권이 인정된다.","a":"견련관계"},{"h":"2. 요건(제536조 제1항)","q":"매도인의 소유권이전등기의무 및 인도의무는 매수인의 ____ 지급의무와 동시이행관계에 있다.","a":"잔금"},{"h":"2. 요건(제536조 제1항)","q":"선이행의무인 중도금 지급을 지체하던 중 잔대금 지급기일이 도래하면, 그때부터 매수인은 중도금에 대한 ____을 지지 않는다.","a":"지체책임"},{"h":"2. 요건(제536조 제1항)","q":"선이행의무라도 상대방 채무의 이행기가 지나면, 특별한 사정이 없는 한 쌍방의 의무는 ____관계에 놓인다.","a":"동시이행"},{"h":"2. 요건(제536조 제1항)","q":"상대방의 이행이 곤란할 현저한 사유가 있는 때 선이행의무자가 자기 채무의 이행을 거절할 수 있는 권리를 ____의 항변권이라 한다(제536조 제2항).","a":"불안"},{"h":"2. 요건(제536조 제1항)","q":"도급인이 하자보수를 청구하는 경우에는 공사대금 ____의 지급을 거절할 수 있으나, 하자보수에 갈음하는 손해배상을 청구하는 경우에는 그에 상응하는 범위에서만 거절할 수 있다.","a":"전액"},{"h":"2. 요건(제536조 제1항)","q":"한 번 현실의 제공을 하여 상대방을 수령지체에 빠뜨렸더라도, 이행제공이 ____되지 않으면 상대방의 동시이행항변권은 소멸하지 않는다.","a":"계속"},{"h":"3. 효력","q":"동시이행판결에서 반대의무의 이행 또는 이행제공은 ____요건으로서 집행기관이 심사한다.","a":"집행개시"},{"h":"3. 효력","q":"반대의무의 이행·제공이 없었다는 주장은 청구이의 사유가 아니라 ____ 사유이다.","a":"집행에 관한 이의신청"},{"h":"3. 효력","q":"동시이행의 항변권이 존재하면 이를 행사하지 않더라도 ____에 빠지지 않는다(존재효).","a":"이행지체"},{"h":"3. 효력","q":"임대차 종료 후 임차인이 동시이행의 항변권에 기하여 점유하는 것은 불법점유가 아니지만, 사용·수익으로 얻은 실질적 이익은 ____으로 반환하여야 한다.","a":"부당이득"},{"h":"3. 효력","q":"동시이행항변권의 포기는 묵시적으로도 가능하지만, ____ 약정만으로는 묵시적 포기로 볼 수 없다.","a":"연체료"}],"채각39":[{"h":"1. 의의","q":"쌍무계약에서 '위험부담'은 통상 ____의 위험 문제이다.","a":"대가"},{"h":"2. 채무자위험부담주의(제537조)","q":"민법은 대가위험에 관하여 ____위험부담주의를 원칙으로 한다(제537조).","a":"채무자"},{"h":"2. 채무자위험부담주의(제537조)","q":"제537조가 적용되면 상대방의 채무도 소멸하고, 이미 이행한 급부는 ____으로 반환하여야 한다.","a":"부당이득"},{"h":"2. 채무자위험부담주의(제537조)","q":"경매로 매매가 종료된 경우 매도인은 받은 계약금을, 목적물을 점유·사용한 매수인은 ____ 상당의 이익을 반환하여야 한다.","a":"차임"},{"h":"2. 채무자위험부담주의(제537조)","q":"기간을 정한 계속적 계약에서 일정 기간의 급부가 불능이 된 경우, 그 기간의 급부불능은 일시적 불능이 아니라 ____ 불능이다.","a":"종국적"},{"h":"2. 채무자위험부담주의(제537조)","q":"토지수용처럼 위험부담이 문제되는 사안에서 채권자가 ____을 행사하면 제537조의 적용이 배제된다.","a":"대상청구권"},{"h":"3. 채권자 귀책사유로 인한 급부불능(제538조)","q":"____의 책임 있는 사유로 이행할 수 없게 된 때에는 채무자는 상대방의 이행을 청구할 수 있다(제538조 제1항 1문).","a":"채권자"},{"h":"3. 채권자 귀책사유로 인한 급부불능(제538조)","q":"채권자의 ____ 중에 당사자 쌍방의 책임 없는 사유로 이행할 수 없게 된 때에도 채무자는 반대급부를 청구할 수 있다(제538조 제1항 2문).","a":"수령지체"},{"h":"3. 채권자 귀책사유로 인한 급부불능(제538조)","q":"수령지체 중 채무자의 ____로 이행불능이 된 경우에도 제401조와 통일적으로 해석하여 '쌍방 무귀책'으로 본다.","a":"경과실"},{"h":"3. 채권자 귀책사유로 인한 급부불능(제538조)","q":"영구적 불수령의 경우 제461조의 면책에는 필요 없지만, 제538조 제1항 2문에 따라 반대급부를 청구하려면 최소한 ____은 있었어야 한다.","a":"구두제공"},{"h":"3. 채권자 귀책사유로 인한 급부불능(제538조)","q":"제538조에 따라 반대급부를 청구하는 채무자는 자기 채무를 면함으로써 얻은 ____을 채권자에게 상환하여야 한다(제2항).","a":"이익"},{"h":"3. 채권자 귀책사유로 인한 급부불능(제538조)","q":"근저당권의 피담보채무를 이행인수한 자가 변제를 게을리하여 근저당권이 실행되고 매도인이 소유권을 잃은 경우, 이는 ____의 귀책사유로 인한 이행불능이다.","a":"매수인"}],"채각40":[{"h":"1. 서설, 성립요건","q":"제3자를 위한 계약인지의 구별기준은, 제3자에게 직접 ____을 취득하게 할 의사가 있는지 여부이다.","a":"채권"},{"h":"1. 서설, 성립요건","q":"수익자는 계약 체결 당시 ____할 필요가 없다 — 태아나 설립 전의 법인도 수익자가 될 수 있다.","a":"현존"},{"h":"1. 서설, 성립요건","q":"요약자와 낙약자 사이의 관계를 ____관계라 한다.","a":"보상"},{"h":"1. 서설, 성립요건","q":"요약자와 수익자 사이의 관계를 ____관계라 한다.","a":"대가"},{"h":"2. 효력","q":"수익의 의사표시는 ____권이고, 수익자가 채권을 취득하기 위한 요건이다.","a":"형성"},{"h":"2. 효력","q":"낙약자가 상당한 기간을 정하여 수익 여부의 확답을 최고하였는데 그 기간 내에 확답을 받지 못하면, 수익을 ____한 것으로 본다(제540조).","a":"거절"},{"h":"2. 효력","q":"수익의 의사표시 후에는 당사자가 수익자의 권리를 ____ 또는 소멸시키지 못한다(제541조).","a":"변경"},{"h":"2. 효력","q":"수익의 의사표시 후에도 요약자나 낙약자는 상대방의 채무불이행을 이유로 계약을 ____할 수 있다(통설·판례).","a":"해제"},{"h":"2. 효력","q":"기본관계가 해제된 경우 낙약자는 이미 수익자에게 급부한 것의 반환을 ____를 상대로 청구하여야 하고, 수익자를 상대로 청구할 수 없다.","a":"요약자"},{"h":"2. 효력","q":"타인을 위한 생명·상해보험에서 지급한 보험금은 보험자 고유의 채무 이행이므로, 보험자는 ____를 상대로 반환을 청구할 수 있다.","a":"수익자"},{"h":"2. 효력","q":"수익의 의사표시를 한 수익자는 원칙적으로, 계약 해제에서 보호되는 제548조 제1항 단서의 ____가 아니다.","a":"제3자"},{"h":"2. 효력","q":"수익의 의사표시 후 낙약자의 채무불이행으로 인한 손해배상청구권은 수익자에게 귀속하지만, ____은 요약자에게만 있다(통설·판례).","a":"해제권"},{"h":"2. 효력","q":"낙약자는 ____관계에 기한 항변으로 수익자에게 대항할 수 있다(제542조).","a":"기본"},{"h":"2. 효력","q":"낙약자는 요약자에 대한 채권으로 수익자의 급부청구권과 ____할 수 없다.","a":"상계"}],"채각41":[{"h":"가. 이행지체를 이유로 한 해제(제544조)","q":"매매 목적 부동산에 근저당권설정등기나 가압류등기가 있다는 사정만으로 곧바로 ____이 되는 것은 아니다.","a":"이행불능"},{"h":"가. 이행지체를 이유로 한 해제(제544조)","q":"매도인이 매수인을 이행지체에 빠뜨리려면 등기서류를 현실제공하거나, 서류를 준비하여 그 뜻을 통지하고 ____을 최고하여야 한다.","a":"수령"},{"h":"가. 이행지체를 이유로 한 해제(제544조)","q":"급부불이행을 이유로 한 해제 통지나 원상회복을 구하는 소의 제기도, 수령거절의 취지가 없는 한 ____로서의 효력이 있다.","a":"최고"},{"h":"가. 이행지체를 이유로 한 해제(제544조)","q":"잔금 미지급 시 자동해제된다는 약정이 있어도, 매도인이 등기서류를 ____하여 매수인을 지체에 빠뜨려야 비로소 해제의 효력이 생긴다.","a":"이행제공"},{"h":"가. 이행지체를 이유로 한 해제(제544조)","q":"이행기를 '기일'로 정한 경우에는 그 기일의 제공으로 충분하지만, '기간 내'로 정한 경우에는 그 기간 중 제공을 ____하여야 한다.","a":"계속"},{"h":"나. 기타 이유 해제","q":"계속적 계약에서 여러 부분이 이행되고 상당한 기간이 흐른 경우에는 제548조의 해제는 할 수 없고 제550조의 ____만 할 수 있다.","a":"해지"},{"h":"나. 기타 이유 해제","q":"채무불이행을 이유로 계약을 해제하려면 그 채무가 계약 목적 달성에 필요불가결한 ____ 채무여야 한다.","a":"주된"},{"h":"2. 해제권의 행사","q":"매매계약의 당사자 일방이 사망하여 여러 상속인이 공동상속한 경우, 해제의 의사표시는 상속인 ____이 하여야 한다.","a":"전원"},{"h":"2. 해제권의 행사","q":"해제 의사표시 당시 이미 원채권이 ____하였다면, 채권자는 해제권과 원상회복청구권을 행사할 수 없다.","a":"시효소멸"},{"h":"가. 법적 구성","q":"해제의 효과에 관한 통설·판례는 ____ 효과설이다 — 등기나 인도 없이도 물권이 당연히 복귀한다.","a":"물권적"},{"h":"나. 해제와 제3자(제548조 제1항 단서)","q":"제3자가 해제 가능성을 알았거나 알 수 있었더라도, 해제 ____에 새로운 이해관계를 맺었다면 제548조 제1항 단서로 보호된다.","a":"전"},{"h":"나. 해제와 제3자(제548조 제1항 단서)","q":"해제 후 원상회복등기 전에 양립할 수 없는 이해관계를 맺은 제3자는 ____인 경우에 한하여 보호된다.","a":"선의"},{"h":"다. 원상회복의무(제548조)","q":"해제 전에 목적물을 제3자에게 처분하여 원물반환이 불가능하게 된 경우에는 ____을 하여야 한다.","a":"가액배상"},{"h":"다. 원상회복의무(제548조)","q":"제548조 제2항의 이자는 약정이 있으면 약정이율, 없으면 ____이율에 의한다.","a":"법정"},{"h":"4. 합의해제(해제계약)","q":"합의해제의 경우 특약이나 유보가 없는 한 ____을 청구할 수 없다.","a":"손해배상"}],"채각42":[{"h":"2. 의의·성질","q":"증여자는 원칙적으로 ____을 지지 않는다(제559조).","a":"담보책임"},{"h":"가. 非서면해제(제555조)","q":"서면에 의하지 않은 증여의 해제(제555조)는 특수한 철회로서 ____의 적용을 받지 않는다.","a":"제척기간"},{"h":"가. 非서면해제(제555조)","q":"매매계약서나 매도증서의 형식이라도 증여의 의사가 표시되어 있으면 제555조의 ____에 해당한다.","a":"서면"},{"h":"나. 망은행위(제556조)","q":"망은행위를 이유로 한 해제권은 해제원인이 있음을 안 날부터 ____월이 지나거나 증여자가 용서하면 소멸한다(제556조 제2항).","a":"6"},{"h":"나. 망은행위(제556조)","q":"제556조 제1항 제2호의 '부양의무'는 제974조의 ____ 간 부양의무를 말하고, 약정에 의한 부양의무는 포함되지 않는다.","a":"친족"},{"h":"다. 재산상태변경(제557조)","q":"증여자의 재산상태가 현저히 변경되어 이행으로 ____에 중대한 영향을 미칠 경우 증여를 해제할 수 있다(제557조).","a":"생계"},{"h":"라. 이행완료부분 원상회복 X(제558조)","q":"증여의 해제는 이미 ____한 부분에 대하여는 영향을 미치지 않는다(제558조).","a":"이행"},{"h":"라. 이행완료부분 원상회복 X(제558조)","q":"부동산 증여에서 제558조의 '이미 이행'이 되려면 인도만으로는 부족하고 ____까지 마쳐야 한다.","a":"소유권이전등기"},{"h":"4. 부담부증여(제561조, 제559조)","q":"부담부증여에는 부담의 한도에서 ____계약에 관한 규정이 적용된다(제561조).","a":"쌍무"},{"h":"4. 부담부증여(제561조, 제559조)","q":"서면에 의하지 않은 증여라도 수증자가 자신이 지기로 한 ____의 이행을 완료하였다면 제555조로 해제할 수 없다.","a":"부담"},{"h":"4. 부담부증여(제561조, 제559조)","q":"부양을 조건으로 한 증여에서 수증자가 부양의무를 이행하지 않으면, 증여자는 제561조에 따라 계약을 ____하고 등기의 말소를 구할 수 있다.","a":"해제"}],"채각43":[{"h":"1. 매매의 예약","q":"예약완결권은 ____권이고, 가등기할 수 있으며 양도할 수 있는 재산권이다.","a":"형성"},{"h":"1. 매매의 예약","q":"행사기간을 정하지 않은 예약완결권은 예약이 성립한 때부터 ____년의 제척기간에 걸린다.","a":"10"},{"h":"가. 서설","q":"해약금은 계약금의 교부만으로 추정되지만, ____은 별도의 약정이 있어야 인정된다.","a":"위약금"},{"h":"가. 서설","q":"해약금(제565조)은 ____해제권을 유보한 것으로 추정된다.","a":"약정"},{"h":"가. 서설","q":"유동적 무효 상태의 매매계약에서도 ____에 의한 해제는 가능하다.","a":"해약금"},{"h":"나. 요건","q":"계약금계약은 ____계약이므로, 계약금을 지급하기로 합의만 한 단계에서는 제565조에 따라 해제할 수 없다.","a":"요물"},{"h":"나. 요건","q":"계약금의 일부만 지급된 경우 해약금의 기준이 되는 금액은 실제 교부받은 금액이 아니라 ____이다.","a":"약정 계약금"},{"h":"나. 요건","q":"해약금에 의한 해제는 당사자 일방이 ____에 착수하기 전까지만 할 수 있다(제565조).","a":"이행"},{"h":"나. 요건","q":"'이행의 착수'는 객관적으로 인식할 수 있을 정도로 이행행위의 일부를 하거나 이행에 필요한 ____를 하는 것을 말한다.","a":"전제행위"},{"h":"나. 요건","q":"이행의 최고나 이행을 구하는 ____만으로는 이행에 착수하였다고 볼 수 없다.","a":"소의 제기"},{"h":"나. 요건","q":"이행기 전에는 착수하지 않기로 하는 ____이 없는 한, 이행기 전에도 이행에 착수할 수 있다.","a":"특약"},{"h":"나. 요건","q":"해약금 해제를 하려면 교부자는 계약금을 포기하고, 수령자는 그 ____을 제공하여야 한다.","a":"배액"},{"h":"나. 요건","q":"수령자가 해약금 해제를 하려면 배액의 적법한 '제공'이 있어야 하고, ____까지 할 필요는 없다.","a":"공탁"},{"h":"4. 과실의 귀속과 대금의 이자(제587조)","q":"매매 목적물이 인도되지 않고 대금도 완납되지 않은 동안에는 목적물의 과실은 ____에게 속한다(제587조).","a":"매도인"},{"h":"4. 과실의 귀속과 대금의 이자(제587조)","q":"대금을 완납하였다면 목적물을 인도받지 않았더라도 그 후의 과실은 ____에게 속한다.","a":"매수인"},{"h":"4. 과실의 귀속과 대금의 이자(제587조)","q":"매수인은 목적물을 ____받은 날부터 대금의 이자를 지급하여야 한다(제587조 제2문).","a":"인도"},{"h":"4. 과실의 귀속과 대금의 이자(제587조)","q":"매수인이 목적물을 넘겨받았더라도 ____ 등 대금 지급을 거절할 정당한 사유가 있으면 대금의 이자를 지급할 의무가 없다.","a":"동시이행"}],"채각44":[{"h":"1. 서설","q":"담보책임에 기하여 해제한 경우 매도인은 대금과 받은 날부터의 이자를, 매수인은 목적물과 ____을 반환하여야 한다.","a":"사용이익"},{"h":"2. 채무불이행책임과 경합","q":"타인의 권리 매매에서 권리를 이전할 수 없게 된 매도인의 손해배상 범위는 ____이익이다(전합).","a":"이행"},{"h":"2. 채무불이행책임과 경합","q":"토지에 폐기물을 은닉하여 매도한 경우 제580조의 하자담보책임과 ____으로 인한 채무불이행책임이 경합한다.","a":"불완전이행"},{"h":"2. 채무불이행책임과 경합","q":"하자로 인한 확대손해는 담보책임이 아니라 ____책임으로 해결하고, 매도인의 귀책사유가 필요하다.","a":"채무불이행"},{"h":"가. 전부 타인 권리(제570조)","q":"권리의 이전불능이 오직 ____의 귀책사유로 인한 것이면 매도인은 담보책임을 지지 않는다.","a":"매수인"},{"h":"가. 전부 타인 권리(제570조)","q":"선의의 매도인의 해제권(제571조)은 권리의 ____가 타인에게 속한 경우에만 적용된다.","a":"전부"},{"h":"나. 일부 타인 권리(제572조)","q":"제573조의 '안 날'은 단순히 권리 일부가 타인에게 속한 사실을 안 날이 아니라, ____이 확실하게 된 사실을 안 날이다.","a":"이전불능"},{"h":"나. 일부 타인 권리(제572조)","q":"건물이 이웃 토지의 경계를 침범하고 그 침범 부분을 이전받을 수 없는 경우 제____조가 유추적용된다.","a":"572"},{"h":"다. 수량부족·일부멸실(제574조)","q":"제574조가 적용되는 매매는 당사자가 일정한 ____에 주안을 두고 대금도 그것을 기준으로 정한 경우이다.","a":"수량"},{"h":"라. 제한물권 등의 제한(제575조)","q":"제575조의 담보책임 대상에는 지상권·전세권·질권·유치권 외에 대항력을 갖춘 ____도 포함된다.","a":"임차권"},{"h":"마. 저당권·전세권 행사(제576조)","q":"매수인이 근저당권의 피담보채무를 인수하였다면 제576조의 담보책임을 면제 또는 ____한 것으로 본다.","a":"포기"},{"h":"마. 저당권·전세권 행사(제576조)","q":"가등기에 기한 본등기나 가압류에 기한 강제집행으로 매수인이 소유권을 잃은 경우에는 제570조가 아니라 제____조가 준용된다.","a":"576"},{"h":"마. 저당권·전세권 행사(제576조)","q":"매수인이 자기 출재로 소유권을 보존한 경우 ____에게 그 상환을 청구할 수 있다(제576조 제2항).","a":"매도인"},{"h":"사. 경매에서의 담보책임(제578조)","q":"제578조의 '경매'는 국가나 그 대행기관이 권리자의 ____와 무관하게 하는 매도만을 말한다.","a":"의사"},{"h":"사. 경매에서의 담보책임(제578조)","q":"제578조 제1항의 '채무자'에는 ____도 포함된다.","a":"물상보증인"},{"h":"사. 경매에서의 담보책임(제578조)","q":"경매절차 자체가 ____이면 제578조의 담보책임은 문제되지 않는다.","a":"무효"},{"h":"가. 특정물 하자담보책임(제580조)","q":"'하자'는 거래통념상 기대되는 객관적 성질·성능을 결여하거나, 당사자가 예정 또는 ____한 성질을 결여한 것을 말한다.","a":"보증"},{"h":"가. 특정물 하자담보책임(제580조)","q":"경매에서의 담보책임은 권리의 하자에만 인정되고, ____의 하자에 대하여는 인정되지 않는다(제580조 제2항).","a":"물건"}],"채각45":[{"h":"1. 임대차 존속기간","q":"제639조 제1항의 임대인의 '이의'는 묵시적으로나 ____부로도 할 수 있다.","a":"조건"},{"h":"2. 임대인의 의무","q":"임대인에게 목적물의 소유권이나 임대권한이 없더라도 임대차계약은 ____하다.","a":"유효"},{"h":"2. 임대인의 의무","q":"임대인의 수선의무를 면제하는 특약은 통상의 ____ 수선에 한정되고, 대규모 수선은 여전히 임대인이 부담한다.","a":"소규모"},{"h":"나. 비용상환청구권(§626)","q":"임대인의 필요비상환의무는 임차인의 ____지급의무와 대응관계에 있으므로, 임차인은 지출한 필요비의 한도에서 그 지급을 거절할 수 있다.","a":"차임"},{"h":"나. 비용상환청구권(§626)","q":"'증축 부분은 임대인 소유로 귀속한다'는 약정은 비용상환청구권의 ____로서 유효하다.","a":"포기"},{"h":"다. 부속물매수청구권(§646)","q":"임차인의 부속물매수청구권을 배제하는 약정은 ____규정에 반하여 무효이다.","a":"강행"},{"h":"다. 부속물매수청구권(§646)","q":"임차인의 채무불이행으로 임대차가 해지된 경우에는 ____매수청구권을 행사할 수 없다.","a":"부속물"},{"h":"라. 지상물매수청구권(§643·283)","q":"지상물매수청구권은 임대차 기간이 만료되고 지상시설이 현존하며 임대인이 ____청구를 거절한 때에 행사할 수 있다.","a":"갱신"},{"h":"라. 지상물매수청구권(§643·283)","q":"지상물매수청구권은 지상물의 ____에 한하여 행사할 수 있다.","a":"소유자"},{"h":"라. 지상물매수청구권(§643·283)","q":"토지 임대인의 건물철거 청구가 인용되어 확정된 후에도, 그 ____ 전이라면 임차인은 지상물매수청구권을 행사할 수 있다.","a":"집행"},{"h":"라. 지상물매수청구권(§643·283)","q":"지상물매수청구권은 ____권이므로, 행사하면 지상물에 관하여 매매 유사의 법률관계가 성립한다.","a":"형성"},{"h":"4. 임차인의 의무","q":"임대인 지위가 승계된 경우, 이미 발생한 연체차임채권은 따로 ____의 요건을 갖추지 않는 한 양수인에게 승계되지 않는다.","a":"채권양도"},{"h":"4. 임차인의 의무","q":"차임연체를 이유로 임대차를 해지하려면 연체액이 ____기의 차임액에 달하여야 한다(제640조).","a":"2"},{"h":"가. 양도·전대 제한(§629)","q":"토지임차인이 지상 건물에 관하여 담보 목적의 소유권이전등기를 해 주더라도 임차권의 ____나 전대에 해당하지 않는다.","a":"양도"},{"h":"가. 양도·전대 제한(§629)","q":"무단 양도·전대가 임대인에 대한 ____ 행위라고 인정할 수 없는 특별한 사정이 있으면 임대인은 제629조로 해지할 수 없다.","a":"배신적"},{"h":"6. 보증금","q":"임차인의 목적물반환의무와 임대인의 보증금반환의무는 ____관계에 있다(전합).","a":"동시이행"},{"h":"6. 보증금","q":"임대차 존속 중에는 임대인이 보증금에서 연체차임을 충당할지 자유로이 선택할 수 있고, 차임이 보증금에서 ____ 공제되는 것은 아니다.","a":"당연"},{"h":"6. 보증금","q":"보증금반환채권에 대한 전부명령이 있더라도, 임대차 종료 후 목적물 인도 시까지 발생한 임대인의 채권은 보증금에서 당연히 ____된다.","a":"공제"},{"h":"6. 보증금","q":"임대차 종료 후 임차인이 보증금을 반환받기 위하여 목적물을 ____하고 있는 동안에는 보증금반환채권의 소멸시효가 진행하지 않는다.","a":"점유"}],"채각46":[{"h":"가. 대항력 취득(§3①)","q":"배우자나 가족 명의의 ____도 주임법상 대항력의 요건을 충족한다.","a":"전입신고"},{"h":"가. 대항력 취득(§3①)","q":"다세대주택의 임차인은 주민등록에 ____까지 정확히 기재하여야 대항력을 취득한다.","a":"동·호수"},{"h":"가. 대항력 취득(§3①)","q":"임대인의 동의를 받은 전차인이 주택을 인도받고 주민등록을 마치면 ____이 대항력을 취득한다.","a":"임차인"},{"h":"나. 임대인 지위 승계(§3④)","q":"임차주택의 양수인이 임대인 지위를 승계하면 보증금반환채무도 양수인에게 이전하고, ____의 보증금반환채무는 소멸한다.","a":"양도인"},{"h":"나. 임대인 지위 승계(§3④)","q":"주임법 제3조 제4항의 '양수인'에 증여·경매·상속으로 취득한 자는 포함되지만 ____는 포함되지 않는다.","a":"양도담보권자"},{"h":"나. 임대인 지위 승계(§3④)","q":"임대인 지위의 승계는 임차인이 ____을 갖추고 있음을 요건으로 한다.","a":"대항력"},{"h":"나. 임대인 지위 승계(§3④)","q":"계약명의신탁의 수탁자로부터 주택을 임차하여 인도와 주민등록을 마친 임차인은 부동산실명법 제4조 제3항의 ____에 해당한다.","a":"제3자"},{"h":"나. 임대인 지위 승계(§3④)","q":"보증금반환채권이 가압류된 상태에서 주택이 양도되면 가압류의 ____ 지위도 양수인에게 이전된다(전합).","a":"제3채무자"},{"h":"나. 임대인 지위 승계(§3④)","q":"임차인이 임대인 지위의 승계를 원하지 않으면 상당한 기간 내에 ____를 제기하여 승계되는 임대차관계에서 벗어날 수 있다.","a":"이의"},{"h":"나. 우선변제권(§3의2②)","q":"확정일자를 갖춘 임차인은 선순위 가압류채권자와 ____배당을 받는다.","a":"평등"},{"h":"나. 우선변제권(§3의2②)","q":"우선변제권을 선택하여 배당요구를 하였으나 보증금 전액을 배당받지 못한 대항력 있는 임차인은, 잔액을 받을 때까지 ____에게 임대차관계의 존속을 주장할 수 있다.","a":"경락인"},{"h":"나. 우선변제권(§3의2②)","q":"임차권등기가 마쳐진 주택을 그 후에 임차한 자는 소액보증금 ____변제권은 없지만 대항력과 우선변제권은 취득할 수 있다.","a":"최우선"},{"h":"다. 소액보증금 최우선변제(§8)","q":"소액임차인이 최우선변제를 받으려면 ____ 등기 전에 대항요건을 갖추어야 한다(제8조).","a":"경매신청"},{"h":"다. 소액보증금 최우선변제(§8)","q":"소액임차인의 대항요건은 ____ 종기까지 존속하여야 한다.","a":"배당요구"},{"h":"4. 존속기간·묵시적 갱신·갱신요구권","q":"실제 거주(제8호)를 이유로 한 갱신거절에서 실제 거주 의사의 증명책임은 ____에게 있다.","a":"임대인"},{"h":"4. 존속기간·묵시적 갱신·갱신요구권","q":"임차인의 갱신요구권 행사에 따른 갱신의 효력은 갱신요구가 상대방에게 ____한 때 발생한다.","a":"도달"},{"h":"4. 존속기간·묵시적 갱신·갱신요구권","q":"갱신요구 후 임차인이 해지를 통지하면, 통지를 받은 날부터 ____개월이 지나면 해지의 효력이 생긴다.","a":"3"},{"h":"대항력의 존속요건과 임차권등기","q":"대항력을 취득한 임차인이 ____를 상실하면 대항력은 소멸하고, 그 후 임차권등기가 마쳐져도 종전 대항력이 부활하지 않는다.","a":"점유"}],"채각47":[{"h":"1. 적용범위","q":"환산보증금이 기준을 초과하는 상가임대차에도 대항력, 권리금, 차임연체 해지, ____에 관한 규정은 적용된다.","a":"갱신요구권"},{"h":"1. 적용범위","q":"상임법이 적용되는 상가건물은 ____ 대상이 되는 건물이어야 한다.","a":"사업자등록"},{"h":"1. 적용범위","q":"사업자등록에 공시된 보증금을 환산한 금액이 한도를 초과하면, 실제 계약 내용이 기준을 충족하더라도 ____이 인정되지 않는다(구법).","a":"대항력"},{"h":"2. 대항력·우선변제권·존속기간","q":"임대차 종료 후 존속이 의제되는 동안 임차인은 ____ 차임을 지급할 의무만 부담하고, 시가에 따른 부당이득을 반환할 의무는 없다.","a":"종전"},{"h":"3. 갱신요구권·묵시의 갱신","q":"상가임차인의 갱신요구권은 임대차기간 만료 ____개월 전부터 1개월 전까지 사이에 행사하여야 한다.","a":"6"},{"h":"3. 갱신요구권·묵시의 갱신","q":"상가임차인의 갱신요구권은 최초 기간을 포함한 전체 임대차기간이 ____년을 초과하지 않는 범위에서만 행사할 수 있다.","a":"10"},{"h":"3. 갱신요구권·묵시의 갱신","q":"임대차기간 중 어느 때라도 ____기의 차임액에 달하도록 연체한 사실이 있으면 임대인은 갱신요구를 거절할 수 있다.","a":"3"},{"h":"3. 갱신요구권·묵시의 갱신","q":"환산보증금을 초과하고 기간의 정함이 없는 상가임대차에는 민법 제635조의 ____가 적용되고, 갱신요구권은 인정될 여지가 없다.","a":"해지통고"},{"h":"3. 갱신요구권·묵시의 갱신","q":"상임법 제10조 제4항은 ____의 갱신거절 통지기간만 제한하므로, 임차인은 만료 1개월 전부터 만료일 사이에 갱신거절을 통지하여도 묵시의 갱신을 막을 수 있다.","a":"임대인"},{"h":"5. 권리금","q":"임대인은 임대차 종료 6개월 전부터 종료 시까지, 임차인이 주선한 신규임차인으로부터 ____을 지급받는 것을 방해하여서는 안 된다.","a":"권리금"},{"h":"5. 권리금","q":"전체 임대차기간이 10년을 넘어 갱신요구권을 행사할 수 없는 경우에도 임대인은 권리금 ____ 보호의무를 부담한다.","a":"회수기회"},{"h":"5. 권리금","q":"'1년 6개월 이상 ____ 목적으로 사용하지 않는 경우'(제3호)를 이유로 신규임차인과의 계약을 거절하려면, 그 사유를 들어 거절하고 실제로도 그 기간 동안 사용하지 않아야 한다.","a":"영리"},{"h":"5. 권리금","q":"임대인이 스스로 영업할 계획이라는 사정만으로는 신규임차인과의 계약을 거절할 ____가 되지 않는다.","a":"정당한 사유"},{"h":"5. 권리금","q":"임대인이 신규임차인과 계약을 체결하지 않겠다는 ____ 의사를 표시하였다면, 임차인은 실제로 신규임차인을 주선하지 않았더라도 손해배상을 청구할 수 있다.","a":"확정적"},{"h":"5. 권리금","q":"임차인의 목적물반환의무와 임대인의 권리금 회수 방해로 인한 손해배상의무는 ____관계에 있지 않다.","a":"동시이행"},{"h":"5. 권리금","q":"권리금 회수기회 방해로 인한 손해배상채무는 임대차가 ____한 날 이행기가 도래한다.","a":"종료"}],"채각48":[{"h":"라. 수급인의 담보책임(§667·668)","q":"완성물의 하자가 중요하지 않은데 그 보수에 ____한 비용이 드는 경우에는 하자보수를 청구할 수 없다(제667조 제1항 단서).","a":"과다"},{"h":"라. 수급인의 담보책임(§667·668)","q":"수급인의 하자담보책임에 따른 의무는 도급인의 ____ 지급의무와 동시이행관계에 있다.","a":"보수"},{"h":"라. 수급인의 담보책임(§667·668)","q":"계약이행보증금은 손해배상액의 예정으로 추정되고, ____이라고 하려면 특별한 사정이 증명되어야 한다.","a":"위약벌"},{"h":"라. 수급인의 담보책임(§667·668)","q":"액젓 저장탱크의 균열로 액젓이 변질된 손해는 하자담보책임을 넘는 ____손해로서, 수급인의 귀책사유가 있어야 배상받을 수 있다.","a":"확대"},{"h":"라. 수급인의 담보책임(§667·668)","q":"완성된 목적물이 건물 기타 토지의 공작물인 경우에는 하자가 아무리 중대하여도 계약을 ____할 수 없다(제668조 단서).","a":"해제"},{"h":"라. 수급인의 담보책임(§667·668)","q":"제669조(도급인이 제공한 재료나 지시로 인한 하자의 면책)는 담보책임에만 적용되고 ____책임에는 적용되지 않는다.","a":"채무불이행"},{"h":"마. 도급인의 의무·종료","q":"수급인의 저당권설정청구권(제666조)에 따른 저당권 설정은 ____에 해당하지 않는다.","a":"사해행위"},{"h":"3. 사용대차","q":"매도인이 선의인 계약명의신탁에서 신탁자가 수탁자의 용인 아래 부동산을 점유·사용해 왔다면 묵시적 ____가 인정된다.","a":"사용대차"},{"h":"6. 위임","q":"위임은 ____이 원칙이지만, 변호사처럼 영업·업무에 속하는 사무를 위임한 경우에는 보수 지급의 묵시적 약정이 인정된다.","a":"무상"},{"h":"6. 위임","q":"수임인이 위임사무의 처리를 위하여 ____ 없이 손해를 받은 때에는 위임인에게 그 배상을 청구할 수 있다(제688조 제3항).","a":"과실"},{"h":"6. 위임","q":"임치에는 제688조 제1항·제2항만 준용되므로, 수치인에게는 제688조 제3항의 ____청구권이 없다.","a":"손해배상"},{"h":"6. 위임","q":"위임계약은 각 당사자가 언제든지 해지할 수 있으나, 부득이한 사유 없이 상대방의 ____한 시기에 해지한 때에는 손해를 배상하여야 한다(제689조).","a":"불리"},{"h":"7. 임치","q":"기간의 약정이 있는 임치에서 ____은 부득이한 사유 없이 기간 만료 전에 계약을 해지하지 못한다(제698조).","a":"수치인"},{"h":"7. 임치","q":"공동명의 예금이 동업자금이면 준합유이고, 단지 ____ 목적이면 분량적으로 분할되어 각자에게 귀속한다.","a":"감시"},{"h":"7. 임치","q":"금융실명제 아래에서는 원칙적으로 실명확인을 거친 ____만이 예금주이다(전합).","a":"예금명의자"},{"h":"8. 조합","q":"조합의 채권은 조합원 전원에게 ____적으로 귀속하므로, 조합원 1인이 임의로 자기 지분비율만큼 청구할 수 없다(전합).","a":"합유"},{"h":"8. 조합","q":"2인 조합에서 1인이 탈퇴하면 조합관계는 종료하지만 조합이 ____되지는 않고, 조합재산은 남은 조합원의 단독소유가 된다.","a":"해산"},{"h":"8. 조합","q":"조합에서 나간 조합원에 대한 지분 계산은 ____ 당시의 조합재산 상태를 기준으로 한다.","a":"탈퇴"},{"h":"8. 조합","q":"조합계약에는 일반적인 해제·해지가 인정되지 않고, 해산청구·탈퇴·____만 가능하다.","a":"제명"}],"채각49":[{"h":"② 타인을 위하여 관리(관리의사)","q":"타인의 사무를 자기의 사무로 잘못 알고 처리한 경우를 ____사무관리라 하고, 사무관리가 성립하지 않는다.","a":"오신"},{"h":"② 타인을 위하여 관리(관리의사)","q":"타인을 위하여 사무를 처리한다는 ____의사는 자기의 이익을 위한 의사와 병존할 수 있고, 외부에 표시될 필요가 없다.","a":"관리"},{"h":"① 타인의 사무일 것","q":"국가의 사무도 ____ 등 사인의 개입이 정당화되는 범위에서는 사무관리가 성립하고, 그 범위에서 국가에 비용상환을 청구할 수 있다.","a":"긴급성"},{"h":"② 타인을 위하여 관리(관리의사)","q":"보험회사가 면책사유가 있음을 모르고 피해자에게 보험금을 지급한 경우, 가해자에 대한 ____는 성립하지 않는다.","a":"사무관리"},{"h":"③ 관리할 의무가 없을 것","q":"제3자와의 약정에 따라 타인의 사무를 처리한 경우에는 '____ 없이' 처리한 것이 아니어서 사무관리가 성립하지 않는다.","a":"의무"},{"h":"③ 관리할 의무가 없을 것","q":"채무자와 계약관계가 없는 제3자가 채무를 유효하게 변제하면 사무관리가 성립하고, 제____조의 비용상환청구권으로 구상할 수 있다.","a":"739"},{"h":"④ 본인 의사에 반하지 않을 것","q":"사무관리는 ____가 아니므로 이를 종료하는 의사표시가 필요하지 않다.","a":"법률행위"},{"h":"2. 전용물소권의 사무관리에의 확장","q":"의무 없이 타인을 위하여 사무를 관리한 자는 그 타인에게 비용상환을 청구할 수 있을 뿐, 사실상 이익을 얻은 ____에게 직접 부당이득반환을 청구할 수 없다.","a":"제3자"},{"h":"3. 효과","q":"사무관리에는 위임의 규정 중 보고의무, 취득물 ____의무, 금전소비책임이 준용된다(제738조).","a":"인도"}],"채각50":[{"h":"① 법률상 원인 결여","q":"급부부당이득에서 법률상 원인이 없다는 점의 증명책임은 ____에게 있다.","a":"반환청구자"},{"h":"① 법률상 원인 결여","q":"침해부당이득에서는 ____이 이익을 보유할 정당한 권원이 있음을 증명하여야 한다.","a":"상대방"},{"h":"① 법률상 원인 결여","q":"확정판결에 기한 이행으로 받은 급부는, 그 판결이 ____ 등으로 취소되지 않는 한 부당이득이 되지 않는다.","a":"재심"},{"h":"② 타인의 재산·노무로 이익","q":"타인의 토지 위에 권원 없이 건물을 소유하는 자는 그 건물에서 영업을 하지 않더라도 토지의 ____ 상당의 이익을 얻은 것이다.","a":"차임"},{"h":"④ 인과관계","q":"무권리자가 타인 소유 부동산을 제3자에게 처분한 경우, 원소유자는 소유권 상실의 손해에 대하여 ____를 이유로 한 손해배상은 청구할 수 있으나 매매대금을 부당이득으로 청구할 수는 없다.","a":"불법행위"},{"h":"가. 급부부당이득","q":"비채변제의 반환은 변제의 주체가 청구한다 — 이행보조자를 통하여 변제하였다면 ____가 반환청구권자이다.","a":"채무자"},{"h":"나. 침해부당이득","q":"가압류된 토지가 수용되어 소유자가 보상금 전액을 받았더라도 ____이 되지 않는다 — 가압류는 교환가치를 지배하지 않는다.","a":"부당이득"},{"h":"나. 침해부당이득","q":"저당물의 수용보상금을 소유자가 저당권자의 ____ 행사 전에 수령하면 부당이득이 된다.","a":"물상대위"},{"h":"나. 침해부당이득","q":"배당받을 권리자가 배당받지 못하고 무권리자가 배당받은 경우, ____ 여부나 배당표 확정 여부와 관계없이 부당이득반환을 청구할 수 있다(전합).","a":"배당이의"},{"h":"가. 반환방법","q":"부당이득은 ____반환이 원칙이고, 그것이 불능이면 가액을 반환한다(제747조 제1항).","a":"원물"},{"h":"가. 반환방법","q":"이득의 내용이 채권의 취득인 경우, 추심 전이면 채권 자체를 반환하고 추심 후이면 ____을 반환한다.","a":"금전"},{"h":"나. 반환범위","q":"선의의 수익자가 패소한 때에는 그 ____ 때부터 악의의 수익자로 본다(제749조 제2항).","a":"소를 제기한"},{"h":"나. 반환범위","q":"금전상의 이득은 소비 여부를 불문하고 ____하는 것으로 추정된다.","a":"현존"},{"h":"마. 불법원인급여(§746)","q":"강제집행을 면할 목적의 명의신탁이나 부동산실명법을 위반한 명의신탁은 ____에 해당하지 않는다(전합).","a":"불법원인급여"},{"h":"마. 불법원인급여(§746)","q":"제746조의 '급여'는 ____인 것이어야 하므로, 도박채무의 담보로 설정한 근저당권은 이에 해당하지 않아 말소를 청구할 수 있다.","a":"종국적"},{"h":"마. 불법원인급여(§746)","q":"제746조는 제103조와 함께 사법의 기본이념을 이루므로, 불법의 원인으로 급여한 자는 부당이득반환뿐 아니라 ____에 기한 반환청구도 할 수 없다(전합).","a":"소유권"},{"h":"나. 전용물소권의 부정","q":"계약상 급부가 제3자의 이익으로 된 경우 급부자가 그 제3자에게 직접 부당이득반환을 청구하는 ____은 인정되지 않는다.","a":"전용물소권"},{"h":"라. 횡령·편취한 금전에 의한 변제","q":"채무자가 횡령한 금전으로 자신의 채권자에게 변제한 경우, 채권자가 변제를 받을 때 ____ 또는 중대한 과실이 없으면 법률상 원인이 있다.","a":"악의"},{"h":"최신판례","q":"미등기건물의 사실상 처분권을 보유한 양수인은 건물의 ____도 아울러 점유하므로 그 사용에 따른 부당이득반환의무를 진다.","a":"부지"}],"채각51":[{"h":"② 책임능력","q":"책임무능력자란 자기 행위의 책임을 ____할 지능이 없는 미성년자나 심신상실자를 말한다.","a":"변식"},{"h":"③ 위법성","q":"의사의 설명의무는 발생 가능성이 희소한 위험이라도, 그 치료행위에 ____으로 발생하는 위험이거나 회복할 수 없는 중대한 위험이면 미친다.","a":"전형적"},{"h":"③ 위법성","q":"의료과오 소송에서 인과관계는 다른 원인이 있다고 보기 어려운 ____을 증명함으로써 추정할 수 있다.","a":"간접사실"},{"h":"④ 손해","q":"토양을 오염시키거나 폐기물을 매립한 채 토지를 유통시킨 자는, 전전 취득한 ____ 소유자에 대하여도 불법행위책임을 진다(전합).","a":"현재"},{"h":"⑤ 인과관계","q":"무권리자의 위법한 등기 후 제3자의 등기부취득시효가 완성되어 원소유자가 소유권을 잃은 경우, 위법한 등기와 소유권 상실 사이에 ____가 인정된다.","a":"인과관계"},{"h":"가. 손해·손해산정","q":"재산상 손해액은 원칙적으로 ____ 시를 기준으로 산정한다.","a":"불법행위"},{"h":"가. 손해·손해산정","q":"호의동승이라는 사실만으로는 배상액을 ____할 수 없다.","a":"감경"},{"h":"가. 손해·손해산정","q":"위자료(정신상 손해)는 ____ 시를 기준으로 산정한다.","a":"사실심 변론종결"},{"h":"가. 손해·손해산정","q":"육체노동의 가동연한은 만 ____세이다(전합).","a":"65"},{"h":"가. 손해·손해산정","q":"제752조에 열거된 직계존속·직계비속·배우자는 정신적 고통에 대한 ____ 없이도 위자료를 청구할 수 있다.","a":"증명"},{"h":"가. 손해·손해산정","q":"위자료청구권은 귀속상 일신전속권이 아니어서 상속·양도되지만, ____상 일신전속권이어서 채권자가 대위할 수 없다.","a":"행사"},{"h":"가. 손해·손해산정","q":"재산상 손해의 발생은 인정되나 증명 곤란으로 손해액을 확정할 수 없는 사정은 위자료의 ____사유로 참작할 수 있다.","a":"증액"},{"h":"나. 소멸시효(§766)","q":"제766조 제1항의 '손해 및 가해자를 안 날'은 손해의 발생, 위법한 가해행위, 인과관계 등을 ____으로 인식한 날을 의미한다.","a":"현실적·구체적"},{"h":"나. 소멸시효(§766)","q":"제766조 제2항의 '불법행위를 한 날'은 가해행위가 있었던 날이 아니라 손해의 결과가 ____된 날이다(전합).","a":"현실화"},{"h":"나. 소멸시효(§766)","q":"불법점유와 같은 계속적 불법행위에서는 ____ 발생한 새로운 각 손해를 안 날부터 각각 별개로 소멸시효가 진행한다.","a":"나날이"},{"h":"나. 소멸시효(§766)","q":"피해자가 법인인 경우 단기소멸시효의 기산점은 통상 ____가 손해 및 가해자를 안 날이다.","a":"대표자"},{"h":"나. 소멸시효(§766)","q":"이혼을 원인으로 한 위자료청구권의 단기소멸시효는 ____ 시부터 진행한다.","a":"혼인 해소"},{"h":"나. 소멸시효(§766)","q":"위법한 건축으로 인한 일조방해의 손해배상청구권은 건물이 준공되거나 ____공사가 완료된 때부터 소멸시효가 진행한다(전합).","a":"외부골조"}],"채각52":[{"h":"1. 책임무능력자의 감독자 책임(제755조)","q":"비양육친은 ____만으로는 제755조의 감독의무를 부담하지 않는다.","a":"면접교섭권"},{"h":"1. 책임무능력자의 감독자 책임(제755조)","q":"책임능력 있는 미성년자의 불법행위라도 감독의무 위반과 손해 사이에 인과관계가 있으면, 감독의무자는 제____조에 따라 책임을 진다(전합).","a":"750"},{"h":"1. 책임무능력자의 감독자 책임(제755조)","q":"정신질환자가 심신상실 중에 가해행위를 하여 배상책임이 없는 경우, 법정감독의무자는 제____조 제1항의 책임을 진다.","a":"755"},{"h":"2. 사용자책임 — 서설","q":"사용자의 피용자에 대한 구상권은 ____상 상당한 한도로 제한된다.","a":"신의칙"},{"h":"2. 사용자책임 — 서설","q":"교통사고의 인적 손해에는 ____이 민법에 우선하여 적용되고, 물적 손해에는 제756조가 적용된다.","a":"자배법"},{"h":"2. 사용자책임 — 서설","q":"피용자가 피해자의 부주의를 이용하여 고의의 불법행위를 한 경우에도 사용자는 ____를 주장할 수 있다.","a":"과실상계"},{"h":"나. 요건","q":"제756조의 '사무'는 법률적·계속적인 것에 한하지 않고 사실적·____인 것이어도 무방하다.","a":"일시적"},{"h":"나. 요건","q":"명의대여자는 명의차용자의 업무수행상 불법행위에 대하여 ____책임을 질 수 있다.","a":"사용자"},{"h":"나. 요건","q":"파견근로에서 원칙적으로 사용관계에 있는 자는 ____이다.","a":"파견사업주"},{"h":"나. 요건","q":"사무집행 관련성은 행위자의 주관적 사정과 관계없이, 행위의 ____상 객관적으로 사무집행과 관련된 것으로 보이면 인정된다.","a":"외형"},{"h":"3. 공작물책임(제758조)","q":"제758조의 공작물은 ____ 작업으로 제작된 물건을 말한다.","a":"인공적"},{"h":"3. 공작물책임(제758조)","q":"공작물의 설치·보존상 하자란 공작물이 통상 갖추어야 할 ____을 갖추지 못한 상태를 말한다.","a":"안전성"},{"h":"3. 공작물책임(제758조)","q":"소유자 겸 임대인이 목적물의 유지·관리의무를 위반한 경우, 임차인에 대하여 공작물책임과 ____책임이 경합한다.","a":"채무불이행"},{"h":"4. 공동불법행위(제760조)","q":"제760조 제1항의 '공동'은 ____ 관련공동성으로 충분하고, 공모나 공동의 인식은 필요하지 않다.","a":"객관적"},{"h":"4. 공동불법행위(제760조)","q":"제760조 제2항은 가해자가 불명인 경우 각 행위와 손해 사이의 인과관계를 법률상 ____한다.","a":"추정"},{"h":"4. 공동불법행위(제760조)","q":"교통사고와 의료과실이 각각 독립하여 불법행위의 요건을 갖추면 ____가 성립한다.","a":"공동불법행위"},{"h":"4. 공동불법행위(제760조)","q":"피용자와 제3자가 함께 손해를 가한 경우, 사용자의 배상책임은 피용자의 배상책임에 대한 ____ 책임이다(전합).","a":"대체적"}],"민총1":[{"h":"1. 관습법","q":"관습법이란 사회의 거듭된 관행으로 생성된 사회생활규범이 ____에 의하여 법적 규범으로 승인·강행되기에 이른 것을 말한다(전합).","a":"법적 확신"},{"h":"1. 관습법","q":"관습법의 효력에 관한 통설·판례는 ____ 효력설이다 — 민법에 규정이 없는 사항에 한하여 적용된다.","a":"보충적"},{"h":"1. 관습법","q":"관습법은 당사자의 주장·증명을 기다릴 필요 없이 법원이 ____으로 확정하여야 한다.","a":"직권"},{"h":"1. 관습법","q":"사실인 관습은 원칙적으로 그 존재를 ____가 주장·증명하여야 한다.","a":"당사자"},{"h":"1. 관습법","q":"공동선조와 성·본을 같이하는 후손은 성별의 구별 없이 ____이 되면 당연히 종중의 구성원이 된다.","a":"성년"},{"h":"1. 관습법","q":"성년 여성도 종중의 구성원이 된다는 결론은 ____에 근거한 것이다.","a":"조리"},{"h":"2. 사적 자치의 원칙","q":"헌법상 기본권 규정은 민법 제2조·제103조 등의 내용을 형성하고 해석기준이 되는 ____ 효력을 가진다.","a":"간접적"}],"민총2":[{"h":"가. 모순행위금지 원칙(금반언)","q":"선행행위와 모순되는 후행행위로 상대방의 정당한 신뢰를 해치는 것을 금지하는 원칙을 ____ 원칙이라 한다.","a":"모순행위금지"},{"h":"가. 모순행위금지 원칙(금반언)","q":"강행법규를 위반한 자가 스스로 무효를 주장하는 것은 원칙적으로 허용된다 — 강행법규가 ____보다 우선하기 때문이다.","a":"신의칙"},{"h":"가. 모순행위금지 원칙(금반언)","q":"주주총회 ____ 없는 영업양도 약정은 강행법규 위반으로 무효이고, 회사가 스스로 그 무효를 주장할 수 있다.","a":"특별결의"},{"h":"나. 사정변경의 원칙","q":"사정변경을 이유로 한 계약 해지는 ____과 임대차계약 등에서 인정된다.","a":"계속적 보증"},{"h":"나. 사정변경의 원칙","q":"계약의 기초가 된 사정이 현저히 변경되어 계약 목적을 달성할 수 없게 된 경우, '____ 원칙'의 예외로서 사정변경을 이유로 계약을 해제·해지할 수 있다.","a":"계약준수"},{"h":"나. 사정변경의 원칙","q":"금전소비대차 성립 후 차주의 신용불안으로 대여금반환청구권의 행사가 위태롭게 되면, 대주는 공평과 신의칙상 대여의무의 이행을 ____할 수 있다.","a":"거절"},{"h":"다. 실효의 원칙","q":"권리자가 상당한 기간 권리를 행사하지 않아 상대방에게 더 이상 행사하지 않으리라는 정당한 신뢰를 준 경우 권리행사를 불허하는 원칙을 ____의 원칙이라 한다.","a":"실효"},{"h":"3. 권리남용금지의 원칙","q":"권리남용이 되려면 가해의사라는 ____ 요건이 필요하다는 것이 통설·판례이다.","a":"주관적"},{"h":"나. 유치권 남용","q":"경매가 곧 개시될 것을 알면서 임대차계약을 체결하고 점유를 이전받은 2순위 근저당권자가 경매절차에서 ____을 주장하는 것은 신의칙상 허용되지 않는다.","a":"유치권"},{"h":"라. 상계권 남용","q":"착오송금의 경우 송금의뢰인이 반환을 요청하고 ____도 이를 승낙하였다면, 수취은행의 상계는 권리남용이 된다.","a":"수취인"},{"h":"라. 상계권 남용","q":"송금의뢰인이 착오송금을 주장하더라도, 수취은행은 입금된 돈이 착오송금인지 ____할 의무가 없으므로 원칙적으로 상계할 수 있다.","a":"조사·확인"},{"h":"라. 상계권 남용","q":"착오송금된 예금채권이 제3자에 의해 압류된 특별한 사정으로 상계가 허용되더라도, 상계는 ____의 범위 내에서만 가능하다.","a":"피압류채권액"}],"민총3":[{"h":"1. 논의의 전제","q":"태아가 권리능력을 인정받으려면 사건 당시 태아이고, ____ 출생하여야 하며, 개별 보호 규정이 있어야 한다.","a":"살아서"},{"h":"1. 논의의 전제","q":"태아의 권리능력에 관하여 우리 민법은 ____주의를 취한다.","a":"개별"},{"h":"1. 논의의 전제","q":"불법행위로 태아가 모체와 함께 ____한 경우에는 태아의 손해배상청구권을 논할 여지가 없다.","a":"사망"},{"h":"1. 논의의 전제","q":"판례는 태아의 증여 ____능력을 부정한다.","a":"수증"},{"h":"2. 개별 사안","q":"태아 보호 규정(불·상·대·피·유·유)은 불법행위 손해배상, 상속, 대습상속, 피인지, 유증, ____이다.","a":"유류분"},{"h":"2. 개별 사안","q":"태아는 불법행위로 인한 손해배상의 청구권에 관하여는 이미 ____한 것으로 본다(제762조).","a":"출생"},{"h":"2. 개별 사안","q":"父가 불법행위로 사망할 당시 태아였던 子도 父의 사망에 대한 ____청구권을 가진다(제762조·제752조).","a":"위자료"},{"h":"2. 개별 사안","q":"父가 즉사한 경우에도 태아가 父의 손해배상청구권을 상속한다고 보는 근거는 ____설이다.","a":"시간적 간격"},{"h":"3. 정지조건설 v. 해제조건설","q":"'이미 출생한 것으로 본다'의 의미에 관하여 판례는 ____설을 취한다.","a":"정지조건"},{"h":"3. 정지조건설 v. 해제조건설","q":"해제조건설에 따르면 태아인 동안에도 ____이 태아의 권리를 행사할 수 있다.","a":"법정대리인"}],"민총4":[{"h":"1. 동시사망의 추정(30조)","q":"2인 이상이 ____한 위난으로 사망한 경우에는 동시에 사망한 것으로 추정한다(제30조).","a":"동일"},{"h":"1. 동시사망의 추정(30조)","q":"동시사망의 추정은 ____상 추정이므로, 번복하려면 충분하고도 명백한 증명이 필요하다.","a":"법률"},{"h":"1. 동시사망의 추정(30조)","q":"동시사망 추정을 번복하려면 전제사실에 대한 반증을 제출하거나, 각자 다른 시각에 사망하였다는 점에 대한 ____을 제출하여야 한다.","a":"본증"},{"h":"2. 상속·대습상속","q":"동시에 사망한 것으로 추정되는 자들 사이에는 ____이 일어나지 않는다.","a":"상속"},{"h":"2. 상속·대습상속","q":"피상속인과 그 직계비속이 동시에 사망한 것으로 추정되는 경우에도, 그 직계비속의 자녀나 배우자는 ____상속을 할 수 있다.","a":"대습"}],"민총5":[{"h":"1. 의사능력","q":"의사능력이란 자신의 행위의 의미와 결과를 정상적인 인식력과 예기력을 바탕으로 ____으로 판단할 수 있는 정신적 능력을 말한다.","a":"합리적"},{"h":"1. 의사능력","q":"의사능력이 없었다는 점은 그 ____를 주장하는 측이 증명하여야 한다.","a":"무효"},{"h":"1. 의사능력","q":"의사무능력자의 법률행위는 ____적 무효이다.","a":"절대"},{"h":"2. 제한능력자제도","q":"제한능력자의 법률행위는 취소할 수 있는 ____적 유효 상태이다.","a":"유동"},{"h":"가. 미성년자","q":"미성년자가 ____하면 성년으로 의제된다(제826조의2).","a":"혼인"},{"h":"가. 미성년자","q":"미성년자의 법률행위에 법정대리인의 동의가 있었다는 사실은 ____이 증명하여야 한다.","a":"상대방"},{"h":"가. 미성년자","q":"법정대리인이 영업을 허락하면 미성년자는 그 영업에 관하여 성년자와 동일한 ____을 가진다(제8조).","a":"행위능력"},{"h":"가. 미성년자","q":"대리인은 ____임을 요하지 않는다(제117조).","a":"행위능력자"},{"h":"가. 미성년자","q":"신용카드이용계약을 취소한 미성년자가 반환할 이익에는 제141조의 ____이익 반환 특칙이 적용된다.","a":"현존"},{"h":"나. 피성년후견인(9·10조)","q":"성년후견인은 법정대리인이지만 ____권은 없다.","a":"동의"},{"h":"나. 피성년후견인(9·10조)","q":"피성년후견인의 법률행위는 취소할 수 있으나, 일용품의 구입 등 ____에 필요하고 대가가 과도하지 않은 법률행위는 취소할 수 없다.","a":"일상생활"},{"h":"다. 피한정후견인(12·13조)","q":"한정후견인은 동의권과 취소권을 가지지만, ____권은 가정법원의 수여 심판이 있어야 가진다(제959조의4).","a":"대리"},{"h":"마. 상대방 보호","q":"제한능력자의 상대방은 ____개월 이상의 기간을 정하여 추인 여부의 확답을 촉구할 수 있다(제15조).","a":"1"},{"h":"마. 상대방 보호","q":"능력자로 된 본인이나 법정대리인이 촉구를 받고도 기간 내에 확답을 발송하지 않으면 ____한 것으로 본다.","a":"추인"},{"h":"마. 상대방 보호","q":"판례는 제17조의 속임수가 되려면 ____ 기망이 있어야 한다고 본다.","a":"적극적"}],"민총6":[{"h":"1. 부재자 재산관리","q":"부재자란 종래의 주소나 거소를 떠나 당분간 돌아올 가망이 없는 자를 말하고, ____일 필요는 없다.","a":"생사불명"},{"h":"1. 부재자 재산관리","q":"법원이 선임한 부재자 재산관리인은 ____대리인이다.","a":"법정"},{"h":"1. 부재자 재산관리","q":"법원이 선임한 재산관리인이 제118조의 권한을 넘는 처분행위를 하려면 법원의 ____를 받아야 한다(제25조).","a":"허가"},{"h":"1. 부재자 재산관리","q":"법원의 처분허가 결정이 취소되더라도 그 취소에는 ____효가 없으므로, 이미 한 처분행위는 유효하다.","a":"소급"},{"h":"1. 부재자 재산관리","q":"재산관리인이 허가를 받았더라도 부재자의 ____과 무관한 처분행위(타인 채무의 담보 제공 등)는 무효이다.","a":"이익"},{"h":"2. 실종선고","q":"보통실종의 실종기간은 ____년이다.","a":"5"},{"h":"2. 실종선고","q":"특별실종의 실종기간은 위난이 종료한 후 ____년이다.","a":"1"},{"h":"2. 실종선고","q":"실종선고를 받은 자는 실종기간이 ____한 때에 사망한 것으로 본다(제28조).","a":"만료"},{"h":"2. 실종선고","q":"실종선고의 청구권자인 이해관계인은 실종자의 사망으로 직접 ____상·경제상 권리를 취득하거나 의무를 면하는 자를 말한다.","a":"신분"},{"h":"2. 실종선고","q":"가족관계등록부에 이미 사망한 것으로 기재된 자에 대하여는 원칙적으로 ____를 할 수 없다.","a":"실종선고"},{"h":"2. 실종선고","q":"잠수장비를 착용하고 입수한 후 부상하지 않은 경우는 위난실종이 아니라 ____실종에 해당한다.","a":"보통"},{"h":"실종선고의 취소(29조)","q":"실종선고가 취소된 경우, 선고를 직접 원인으로 재산을 취득한 자가 선의이면 ____이익만 반환하면 된다(제29조 제2항).","a":"현존"},{"h":"실종선고의 취소(29조)","q":"실종선고 후 취소 전에 ____로 한 행위의 효력은 실종선고의 취소로 영향을 받지 않는다(제29조 제1항 단서).","a":"선의"}],"민총7":[{"h":"1. 법인격부인론","q":"법인격부인론은 법인격이 ____되었거나 남용된 경우 법인격을 부인하고 배후자에게 책임을 묻는 이론이다.","a":"형해화"},{"h":"1. 법인격부인론","q":"회사가 이름뿐이고 실질적으로 개인기업에 불과한지는 문제된 ____ 시점을 기준으로 판단한다.","a":"법률행위"},{"h":"1. 법인격부인론","q":"법인격 남용이 인정되더라도 기존회사에 대한 판결의 ____과 집행력을 신설회사에 확장할 수는 없다.","a":"기판력"},{"h":"1. 법인격부인론","q":"기존 회사의 채무를 면탈하기 위해 설립된 신설회사가 자신에 대한 채권의 소멸시효 완성을 주장하는 것은 ____상 허용되지 않는다.","a":"신의칙"},{"h":"나. 재단법인 출연재산의 귀속시기(48조)","q":"생전처분으로 재단법인을 설립하는 때에는 ____에 관한 규정을 준용한다(제47조 제1항).","a":"증여"},{"h":"나. 재단법인 출연재산의 귀속시기(48조)","q":"유언으로 재단법인을 설립하는 때에는 ____에 관한 규정을 준용한다(제47조 제2항).","a":"유증"},{"h":"나. 재단법인 출연재산의 귀속시기(48조)","q":"재단법인의 출연재산은 출연자와 법인 사이에서는 등기 없이도 제48조의 시기에 귀속하지만, ____에게 대항하려면 등기가 필요하다(전합).","a":"제3자"},{"h":"3. 기타 법인 관련 규정","q":"법인의 ____는 필수기관이고, 감사는 임의기관이다.","a":"이사"},{"h":"3. 기타 법인 관련 규정","q":"직무대행자는 법인의 ____에 속하는 행위만 할 수 있다(제60조의2).","a":"통상사무"},{"h":"3. 기타 법인 관련 규정","q":"결원으로 손해가 생길 염려가 있으면 법원은 이해관계인이나 검사의 청구로 ____를 선임한다(제63조).","a":"임시이사"},{"h":"3. 기타 법인 관련 규정","q":"법인과 이사의 이익이 상반하는 사항에 관하여는 ____을 선임하여야 한다(제64조).","a":"특별대리인"},{"h":"3. 기타 법인 관련 규정","q":"재단법인의 기본재산을 처분하거나 새로 편입하는 것은 정관변경을 초래하므로 ____의 허가가 필요하다.","a":"주무관청"},{"h":"3. 기타 법인 관련 규정","q":"재단법인 기본재산에 대한 강제경매에서 주무관청의 허가는 경매개시의 요건이 아니라 경락인의 ____ 요건이다.","a":"소유권취득"},{"h":"3. 기타 법인 관련 규정","q":"청산종결의 등기가 되었더라도 청산사무가 종결되지 않았다면 그 한도에서 ____으로 존속한다.","a":"청산법인"}],"민총8":[{"h":"1. 계약책임","q":"법인의 권리능력은 법률과 ____으로 정한 목적의 범위 내에서 인정된다(제34조).","a":"정관"},{"h":"1. 계약책임","q":"'목적의 범위'에 관하여 통설·판례는 목적 수행에 ____한 행위까지 포함한다고 본다.","a":"필요"},{"h":"1. 계약책임","q":"대표권 제한은 정관에 기재하여야 효력이 있고, ____하지 않으면 제3자에게 대항하지 못한다(제41조·제60조).","a":"등기"},{"h":"1. 계약책임","q":"대표권 제한이 등기되지 않은 경우 ____의 제3자에게도 대항할 수 없다는 것이 통설·판례이다.","a":"악의"},{"h":"1. 계약책임","q":"사립학교법상 기본재산 처분에 관할청의 허가를 요하는 규정처럼 ____상 대표권 제한을 위반한 행위는 무효이다.","a":"법률"},{"h":"1. 계약책임","q":"대표권남용의 경우 상대방이 이를 알았거나 알 수 있었다면 법인은 그 행위의 ____을 부인할 수 있다.","a":"효력"},{"h":"가. 요건","q":"제35조의 '이사 기타 대표자'에는 명칭·직위·등기 여부를 불문하고 법인을 실질적으로 운영하는 ____의 대표자도 포함된다.","a":"사실상"},{"h":"가. 요건","q":"대표권이 없는 이사의 행위에 대하여는 제____조의 법인 불법행위책임이 성립하지 않는다.","a":"35"},{"h":"가. 요건","q":"피용자의 불법행위에 대하여 법인은 제35조가 아니라 제____조의 사용자책임을 진다.","a":"756"},{"h":"가. 요건","q":"대표기관의 행위가 ____상 법인의 직무행위로 인정되면, 사리를 도모하거나 법령에 위배된 것이라도 직무관련성이 인정된다.","a":"외형"},{"h":"가. 요건","q":"대표자의 행위가 직무에 관한 것이 아님을 상대방이 알았거나 ____로 알지 못한 경우에는 법인에게 제35조의 책임을 물을 수 없다.","a":"중대한 과실"},{"h":"3. 기타 대표행위 관련 규정","q":"이사는 정관이나 총회의 결의로 금지하지 않은 사항에 한하여 타인에게 ____한 행위를 대리하게 할 수 있다(제62조).","a":"특정"},{"h":"3. 기타 대표행위 관련 규정","q":"이사가 대표권을 타인에게 ____적으로 위임하는 것은 제62조에 위반되어 무효이다.","a":"포괄"},{"h":"3. 기타 대표행위 관련 규정","q":"임기가 만료된 이사는 후임 이사가 없으면 제____조를 유추적용하여 업무수행권을 가진다.","a":"691"},{"h":"3. 기타 대표행위 관련 규정","q":"법인과 이사는 위임 유사의 관계이므로, 법인은 임기 만료 전에도 언제든지 이사를 ____할 수 있다.","a":"해임"}],"민총9":[{"h":"1. 의의","q":"조합과 비법인사단의 구별기준은 ____의 강약이다.","a":"단체성"},{"h":"1. 의의","q":"종중은 공동선조의 분묘수호와 제사 및 종원 상호 간의 친목을 목적으로 하는 ____ 종족집단이다(전합).","a":"자연발생적"},{"h":"2. 법인 규정의 유추적용","q":"비법인사단에는 법인에 관한 규정 중 ____을 전제로 한 규정을 제외한 나머지가 유추적용된다.","a":"법인격"},{"h":"3. 비법인사단의 대표권제한","q":"법인 아닌 사단의 사원이 집합체로서 물건을 소유하는 형태는 ____이다(제275조).","a":"총유"},{"h":"3. 비법인사단의 대표권제한","q":"비법인사단에는 대표권 제한을 등기할 방법이 없으므로 제____조가 준용되지 않는다.","a":"60"},{"h":"3. 비법인사단의 대표권제한","q":"비법인사단의 대표권 제한을 위반한 거래행위는, 상대방이 그 제한을 알았거나 알 수 있었을 경우에 ____이다.","a":"무효"},{"h":"3. 비법인사단의 대표권제한","q":"대표권 제한 위반에 관한 거래 상대방의 악의·과실은 ____ 측이 주장·증명하여야 한다.","a":"비법인사단"},{"h":"3. 비법인사단의 대표권제한","q":"대표자가 사원총회의 결의 없이 총유물을 처분한 행위에는 제126조의 ____가 준용되지 않는다.","a":"표현대리"},{"h":"4. 기타 (종중·교회)","q":"종중토지의 매각대금 분배는 정관이나 규약에 정함이 없는 한 ____의 결의에 의하여만 할 수 있다.","a":"종중총회"},{"h":"4. 기타 (종중·교회)","q":"교회에서 구성원의 탈퇴는 인정되지만, 2개의 단체로 나뉘어 각각 독립하여 존속하는 ____은 인정되지 않는다(전합).","a":"분열"}],"민총10":[{"h":"1. 물건의 정의·요건","q":"민법상 물건은 유체물 및 전기 기타 ____할 수 있는 자연력이다(제98조).","a":"관리"},{"h":"2. 부동산과 동산","q":"부동산은 토지 및 그 ____이다(제99조 제1항).","a":"정착물"},{"h":"2. 부동산과 동산","q":"건물은 언제나 토지와 ____한 부동산이다.","a":"독립"},{"h":"2. 부동산과 동산","q":"수목은 입목등기나 ____을 갖추면 토지와 별개의 물건이 된다.","a":"명인방법"},{"h":"2. 부동산과 동산","q":"타인의 토지에 권원 없이 경작하였더라도 농작물이 성숙하면 ____의 소유가 된다.","a":"경작자"},{"h":"2. 부동산과 동산","q":"금전은 가치 그 자체여서 ____이 없으므로, 타인의 수중에 들어가면 물권적 청구권을 행사할 수 없다.","a":"개성"},{"h":"3. 주물과 종물","q":"종물이 되려면 주물의 ____에 이바지하여야 한다(제100조 제1항).","a":"상용"},{"h":"3. 주물과 종물","q":"종물은 주물의 ____에 따른다(제100조 제2항).","a":"처분"},{"h":"3. 주물과 종물","q":"제358조는 저당부동산의 종된 ____에도 유추적용되므로, 건물 저당권의 효력은 건물 소유를 위한 지상권에도 미친다.","a":"권리"},{"h":"4. 원물과 과실","q":"천연과실은 원물로부터 ____하는 때에 이를 수취할 권리자에게 속한다(제102조 제1항).","a":"분리"},{"h":"4. 원물과 과실","q":"법정과실은 수취할 권리의 존속기간 ____의 비율로 취득한다(제102조 제2항).","a":"일수"},{"h":"4. 원물과 과실","q":"토지에 지상권이 설정되어 있어도 토지소유자는 불법점유자에게 ____청구권을 행사할 수 있다.","a":"물권적"}],"민총11":[{"h":"1. 법률행위 일반","q":"법률행위는 ____를 필수적 요소로 하는 법률요건이다.","a":"의사표시"},{"h":"1. 법률행위 일반","q":"채권양도나 채무인수처럼 물권 외의 권리를 직접 변동시키는 법률행위를 ____행위라 한다.","a":"준물권"},{"h":"1. 법률행위 일반","q":"처분행위는 물권행위와 준물권행위를 합한 개념으로, ____의 문제를 남기지 않는 행위이다.","a":"이행"},{"h":"가. 의의","q":"규범적 해석으로도 의사의 합치를 인정할 수 없으면 숨은 불합의로 계약이 불성립하고, ____를 이유로 한 취소의 여지가 없다.","a":"착오"},{"h":"가. 의의","q":"여러 계약서를 순차로 작성하면서 우열을 정하지 않았고 내용이 양립할 수 없으면, ____ 계약서의 내용대로 변경되었다고 해석한다.","a":"나중"},{"h":"나. 자연적 해석","q":"표시가 잘못되었더라도 그 의미에 관하여 당사자의 의사가 합치하면 그에 따른 효과가 발생한다 — 이를 ____ 원칙이라 한다.","a":"오표시무해"},{"h":"나. 자연적 해석","q":"지번의 착오로 계약서에 다른 토지가 표시된 경우, 매매계약은 계약서에 표시된 토지가 아니라 당사자의 ____가 합치된 토지에 관하여 성립한다.","a":"의사"},{"h":"다. 규범적 해석","q":"____ 해석은 표시행위의 객관적 의미를 합리적인 상대방의 입장에서 탐구하는 것이다.","a":"규범적"},{"h":"라. 보충적 해석","q":"____ 해석은 당사자가 약정하지 않은 사항을, 임의규정도 없을 때 가정적 의사로 채우는 것이다.","a":"보충적"},{"h":"라. 보충적 해석","q":"쌍방 공통의 착오가 있는 경우, 착오가 없었더라면 약정하였을 내용 즉 당사자의 ____ 의사를 기준으로 계약 내용을 보충한다.","a":"가정적"}],"민총12":[{"h":"2. 내용의 적법성","q":"단순한 단속규정을 위반한 약정은 유효하지만, 당사자가 ____하여 단속규정을 위반하였다면 제103조 위반으로 무효가 될 수 있다.","a":"통정"},{"h":"2. 내용의 적법성","q":"강행법규 위반의 무효는 ____적 무효이므로 추인하여도 유효로 되지 않는다.","a":"확정"},{"h":"2. 내용의 적법성","q":"강행법규 위반의 무효는 ____적 무효이므로 선의의 제3자도 보호되지 않는다.","a":"절대"},{"h":"2. 내용의 적법성","q":"농지법을 위반하여 무효인 농지 임대차에서 임차인이 반환할 이득은 약정차임이 아니라 ____ 상당액이다.","a":"임료"},{"h":"2. 내용의 적법성","q":"변호사법 제109조 제1호를 위반한 약정은 그 자체로 제____조 위반이다.","a":"103"},{"h":"2. 내용의 적법성","q":"법정 한도를 넘는 부동산 중개수수료 약정은 그 ____ 부분에 한하여 무효이다.","a":"초과"},{"h":"2. 내용의 적법성","q":"중간생략등기를 금지한 부동산등기 특별조치법 규정은 ____규정이어서, 위반하여도 사법상 효력은 유효하다.","a":"단속"},{"h":"가. 반사회적 법률행위(103조)","q":"동기의 불법에 관한 통설·판례는 ____설이다.","a":"동기표시"},{"h":"가. 반사회적 법률행위(103조)","q":"반사회성의 판단시점은 그 행위가 ____ 때이다(전합).","a":"이루어진"},{"h":"가. 반사회적 법률행위(103조)","q":"부동산 이중매매가 반사회적 법률행위로 무효가 되려면 제2매수인이 매도인의 배임행위에 ____하여야 한다.","a":"적극가담"},{"h":"가. 반사회적 법률행위(103조)","q":"형사사건에 관한 ____약정은 제103조 위반으로 무효이다(전합).","a":"성공보수"},{"h":"가. 반사회적 법률행위(103조)","q":"증언의 대가로 ____ 수준을 넘는 급부를 약정하는 것은 제103조 위반으로 무효이다.","a":"통상"},{"h":"가. 반사회적 법률행위(103조)","q":"도박채무의 변제를 위하여 부동산의 처분을 위임한 경우, 무효인 것은 변제에 충당하는 부분에 한정되고 ____ 수여 부분은 유효하다.","a":"대리권"},{"h":"나. 불공정한 법률행위(104조)","q":"제104조는 제103조의 ____이라는 것이 통설·판례이다.","a":"예시"},{"h":"나. 불공정한 법률행위(104조)","q":"불공정한 법률행위의 요건은 모두 ____를 주장하는 자가 증명하여야 한다.","a":"무효"},{"h":"나. 불공정한 법률행위(104조)","q":"____에는 제104조가 적용되지 않는다.","a":"경매"},{"h":"나. 불공정한 법률행위(104조)","q":"급부와 반대급부 사이의 현저한 불균형은 계약 ____ 당시를 기준으로 판단한다(키코 전합).","a":"체결"}],"민총13":[{"h":"2. 비진의표시(107조)","q":"비진의표시는 원칙적으로 ____하지만, 상대방이 진의 아님을 알았거나 알 수 있었을 경우에는 무효이다(제107조).","a":"유효"},{"h":"다. 선의의 제3자 보호(108조 2항)","q":"통정허위표시의 무효는 ____의 제3자에게 대항하지 못한다(제108조 제2항).","a":"선의"},{"h":"다. 선의의 제3자 보호(108조 2항)","q":"제108조 제2항의 제3자는 허위표시로 형성된 법률관계를 토대로 실질적으로 ____ 법률상 이해관계를 맺은 자를 말한다.","a":"새로운"},{"h":"다. 선의의 제3자 보호(108조 2항)","q":"허위표시로 인한 채권을 가압류한 자는 제108조 제2항의 제3자에 해당하지만, 가장양수인으로부터 ____을 위하여 채권을 양수한 자는 해당하지 않는다.","a":"추심"},{"h":"다. 선의의 제3자 보호(108조 2항)","q":"제108조 제2항의 제3자는 선의로 ____되므로, 무효를 주장하는 자가 제3자의 악의를 증명하여야 한다.","a":"추정"},{"h":"다. 선의의 제3자 보호(108조 2항)","q":"제108조 제2항의 제3자는 선의이면 족하고 ____까지 요하지 않는다.","a":"무과실"},{"h":"4. 착오 — 요건","q":"착오가 법률행위 내용의 ____에 관한 것이어야 취소할 수 있다(제109조).","a":"중요부분"},{"h":"4. 착오 — 요건","q":"착오가 표의자의 ____로 인한 때에는 취소하지 못한다(제109조 제1항 단서).","a":"중대한 과실"},{"h":"4. 착오 — 요건","q":"상대방이 표의자의 착오를 알고 이를 ____한 경우에는 표의자에게 중대한 과실이 있어도 취소할 수 있다.","a":"이용"},{"h":"4. 착오 — 요건","q":"보증계약에서 주채무자의 ____에 관한 착오는 중요부분의 착오가 아니다.","a":"자력"},{"h":"4. 착오 — 요건","q":"근저당권설정계약에서 ____의 동일성에 관한 착오는 중요부분의 착오이다.","a":"채무자"},{"h":"나. 동기의 착오","q":"동기의 착오는 그 동기를 법률행위의 내용으로 삼을 것을 상대방에게 ____한 경우에 취소할 수 있다.","a":"표시"},{"h":"나. 동기의 착오","q":"상대방에 의하여 ____된 동기의 착오는 동기의 표시 여부를 불문하고 취소할 수 있다.","a":"유발"},{"h":"다. 기타 사항","q":"매도인의 하자담보책임이 성립하는 경우에도 ____를 이유로 한 취소가 가능하다(판례).","a":"착오"},{"h":"다. 기타 사항","q":"제109조의 착오는 현재 또는 과거의 사실에 관한 것이어야 하고, ____의 사항에 대한 예측이 빗나간 것은 착오가 아니다.","a":"장래"},{"h":"다. 기타 사항","q":"경과실로 착오에 빠진 표의자가 의사표시를 취소하더라도, 상대방에 대하여 ____책임을 지지 않는다(판례).","a":"불법행위"},{"h":"5. 사기·강박","q":"사기의 요건(고·기·위·인)은 2단의 고의, 기망행위, ____, 인과관계이다.","a":"위법성"},{"h":"다. 제3자 사기·강박(110조 2항)","q":"제3자의 사기·강박에 의한 의사표시는 상대방이 그 사실을 ____ 경우에 한하여 취소할 수 있다(제110조 제2항).","a":"알았거나 알 수 있었을"},{"h":"다. 제3자 사기·강박(110조 2항)","q":"상대방의 대리인처럼 상대방과 ____할 수 있는 자는 제110조 제2항의 제3자가 아니다.","a":"동일시"}],"민총14":[{"h":"가. 서론","q":"수권행위는 ____행위이고 불요식행위이다(통설).","a":"단독"},{"h":"나. 대리권의 범위와 제한","q":"매매계약 체결의 대리권에는 대금 수령 권한과 지급기일을 ____해 줄 권한이 포함된다.","a":"연기"},{"h":"나. 대리권의 범위와 제한","q":"매매계약 체결의 대리권에는 계약을 ____할 권한이 포함되지 않는다.","a":"해제"},{"h":"나. 대리권의 범위와 제한","q":"대리인은 본인의 허락이 없으면 자기계약이나 ____를 하지 못한다(제124조).","a":"쌍방대리"},{"h":"나. 대리권의 범위와 제한","q":"친권자와 子 사이의 이해상반행위 여부는 행위의 ____ 성질에 따라 형식적으로 판단한다(통설·판례).","a":"객관적"},{"h":"다. 대리권남용","q":"대리권남용에 관하여 통설·판례는 제107조 제1항 ____ 유추적용설을 취한다.","a":"단서"},{"h":"라. 대리권의 소멸","q":"대리권은 본인의 사망, 대리인의 사망·성년후견의 개시·____으로 소멸한다(제127조).","a":"파산"},{"h":"4. 대리행위","q":"대리인이 본인을 위한 것임을 표시하지 않은 의사표시는 ____을 위한 것으로 본다(제115조).","a":"자기"},{"h":"4. 대리행위","q":"대리행위에서 의사표시의 하자나 어떤 사정을 알았는지 여부는 ____을 표준으로 결정한다(제116조 제1항).","a":"대리인"},{"h":"4. 대리행위","q":"이중매매에서 대리인이 매도인의 배임행위에 적극가담하였다면, 본인이 이를 몰랐더라도 매매계약은 제____조 위반으로 무효이다.","a":"103"},{"h":"6. 복대리","q":"임의대리인은 본인의 승낙이 있거나 ____한 사유가 있는 때에만 복대리인을 선임할 수 있다(제120조).","a":"부득이"},{"h":"7. 표현대리 — 서설·성질","q":"유권대리의 주장 속에 ____의 주장이 포함되어 있다고 볼 수 없다(전합).","a":"표현대리"},{"h":"다. 제126조 (요건)","q":"복대리인 선임권이 없는 대리인이 선임한 복대리인의 권한도 제126조의 ____이 될 수 있다.","a":"기본대리권"},{"h":"다. 제126조 (요건)","q":"제126조의 '정당한 이유'는 ____ 당시를 기준으로 판단하고, 그 후의 사정은 고려하지 않는다.","a":"대리행위"},{"h":"다. 제126조 (요건)","q":"제126조의 정당한 이유는 ____이 증명하여야 한다.","a":"상대방"},{"h":"다. 제126조 (요건)","q":"제126조의 제3자는 대리행위의 ____ 상대방만을 의미하고, 전득자는 포함되지 않는다.","a":"직접"},{"h":"나. 무권대리와 상속","q":"무권대리인이 본인을 상속한 경우 본인의 지위에서 ____을 거절하는 것은 신의칙상 허용되지 않는다.","a":"추인"},{"h":"다. 상대방 보호","q":"상대방이 제134조의 ____권을 유효하게 행사하면 무권대리행위는 확정적으로 무효가 되어, 본인이 더 이상 추인할 수 없다.","a":"철회"},{"h":"라. 무권대리인의 책임(135조)","q":"무권대리인의 책임(제135조)은 거래안전을 위한 법정의 ____책임이다.","a":"무과실"},{"h":"라. 무권대리인의 책임(135조)","q":"제135조에 따른 상대방의 권리의 소멸시효는 ____을 행사할 수 있는 때부터 진행한다.","a":"선택권"}],"민총15":[{"h":"3. 일부무효(137조)","q":"법률행위의 일부가 무효인 때에는 ____를 무효로 하는 것이 원칙이다(제137조 본문).","a":"전부"},{"h":"3. 일부무효(137조)","q":"일부무효의 예외가 인정되려면 법률행위의 일체성, 분할가능성, 당사자의 ____ 의사가 있어야 한다.","a":"가정적"},{"h":"4. 무효행위의 전환(138조)","q":"무효인 법률행위가 다른 법률행위의 요건을 구비하고, 당사자가 무효를 알았더라면 그 다른 법률행위를 의욕하였으리라고 인정되면 그 효력을 인정하는 것을 무효행위의 ____이라 한다(제138조).","a":"전환"},{"h":"5. 무효행위의 추인(139조)","q":"무효인 법률행위는 추인하여도 효력이 생기지 않지만, 당사자가 무효임을 ____ 추인한 때에는 새로운 법률행위로 본다(제139조).","a":"알고"},{"h":"5. 무효행위의 추인(139조)","q":"____법규 위반으로 무효인 법률행위는 추인하여도 유효로 되지 않는다.","a":"강행"},{"h":"5. 무효행위의 추인(139조)","q":"무효인 법률행위를 유효한 것으로 전제하고 후속행위를 하였다는 사정만으로는 ____ 추인이 있었다고 볼 수 없다.","a":"묵시적"},{"h":"5. 무효행위의 추인(139조)","q":"타인의 子를 친생자로 출생신고한 뒤 입양의 요건을 갖추게 되면 그 신고의 효력은 ____하여 인정된다 — 제139조는 신분행위에 적용되지 않는다.","a":"소급"},{"h":"6. 유동적 무효","q":"토지거래허가를 받기 전의 매매계약은 ____ 무효 상태에 있다.","a":"유동적"},{"h":"6. 유동적 무효","q":"유동적 무효 상태에서는 계약금을 ____으로 반환청구할 수 없다 — 확정적으로 무효가 된 후에야 가능하다.","a":"부당이득"},{"h":"6. 유동적 무효","q":"유동적 무효 상태에서도 제565조에 따른 ____해제는 가능하다.","a":"해약금"},{"h":"6. 유동적 무효","q":"쌍방이 허가신청을 하지 않기로 하는 의사를 명백히 표시하면 유동적 무효인 계약은 ____ 무효가 된다.","a":"확정적"},{"h":"6. 유동적 무효","q":"유동적 무효 상태의 계약에서 매수인 지위의 승계는 관할관청의 ____가 필요하다.","a":"허가"},{"h":"6. 유동적 무효","q":"토지거래허가구역에서 허가를 배제하거나 ____할 목적으로 체결한 계약은 처음부터 무효이고, 유동적 무효가 아니다.","a":"잠탈"},{"h":"7. 무권리자의 처분행위","q":"무권리자의 처분행위를 권리자가 추인하면 원칙적으로 ____ 시로 소급하여 효력이 생긴다.","a":"계약체결"},{"h":"7. 무권리자의 처분행위","q":"무권리자 처분에 대한 권리자의 추인은 사적 자치의 원칙과 제130조·제133조의 ____에 근거한다.","a":"유추적용"}],"민총16":[{"h":"1. 법률행위의 취소","q":"취소권자는 제한능력자, 착오·사기·강박으로 의사표시를 한 자, 그 대리인 또는 ____이다(제140조).","a":"승계인"},{"h":"2. 일부취소","q":"하나의 계약이라도 ____이 있고 목적물의 일부가 특정될 수 있으면 그 일부만 취소할 수 있다.","a":"가분성"},{"h":"3. 취소의 효과(141조)","q":"취소된 법률행위는 처음부터 ____인 것으로 본다(제141조).","a":"무효"},{"h":"3. 취소의 효과(141조)","q":"제한능력자는 취소된 행위로 받은 이익이 ____하는 한도에서 상환할 책임이 있다(제141조 단서).","a":"현존"},{"h":"3. 취소의 효과(141조)","q":"제141조 단서는 ____자에게도 유추적용된다.","a":"의사무능력"},{"h":"3. 취소의 효과(141조)","q":"근로계약은 취소하더라도 이미 제공한 노무의 효과는 소급하여 부정되지 않고 ____에 관하여만 효력이 소멸한다.","a":"장래"},{"h":"가. 취소할 수 있는 법률행위의 추인","q":"취소할 수 있는 법률행위의 추인은 취소권의 ____이다.","a":"포기"},{"h":"가. 취소할 수 있는 법률행위의 추인","q":"취소할 수 있는 법률행위의 추인은 취소의 원인이 ____된 후에 하여야 효력이 있다(제144조).","a":"소멸"},{"h":"나. 법정추인(145조)","q":"추인할 수 있은 후에 전부나 일부의 이행, 이행의 청구, 경개, 담보의 제공 등이 있으면 추인한 것으로 보는 것을 ____이라 한다(제145조).","a":"법정추인"},{"h":"다. 제척기간(146조)","q":"취소권은 추인할 수 있는 날부터 ____년 내에 행사하여야 한다(제146조).","a":"3"},{"h":"다. 제척기간(146조)","q":"취소권은 법률행위를 한 날부터 ____년 내에 행사하여야 한다(제146조).","a":"10"},{"h":"다. 제척기간(146조)","q":"제146조의 취소권 행사기간은 ____기간이다.","a":"제척"}],"민총17":[{"h":"1. 조건","q":"조건의 성취나 기한의 도래에는 원칙적으로 ____효가 없다.","a":"소급"},{"h":"1. 조건","q":"조건을 붙이려는 의사는 법률행위의 내용으로 ____되어야 하고, 내심에 머물면 동기에 불과하다.","a":"표시"},{"h":"1. 조건","q":"법률행위가 정지조건부라는 사실은 그 법률효과의 발생을 ____하려는 자가 증명하여야 한다.","a":"저지"},{"h":"1. 조건","q":"정지조건이 성취되었다는 사실은 법률효과의 발생을 ____하는 자가 증명하여야 한다.","a":"주장"},{"h":"1. 조건","q":"약혼예물의 수수는 혼인의 불성립을 ____조건으로 하는 증여와 유사하다.","a":"해제"},{"h":"1. 조건","q":"조건이 이루어지면 불이익을 받을 당사자가 신의성실에 반하여 이를 방해한 때에는, 상대방은 그 조건이 ____한 것으로 주장할 수 있다(제150조 제1항).","a":"성취"},{"h":"1. 조건","q":"조건 성취가 의제되는 시점은 ____가 없었더라면 조건이 성취되었으리라고 추정되는 때이다.","a":"방해행위"},{"h":"1. 조건","q":"조건이 선량한 풍속 기타 사회질서에 위반한 것인 때에는 그 법률행위는 ____로 한다(제151조 제1항).","a":"무효"},{"h":"1. 조건","q":"조건부 권리도 일반 규정에 따라 처분, 상속, 보존 또는 ____로 할 수 있다(제149조).","a":"담보"},{"h":"2. 기한","q":"부관으로 정한 사실이 발생하지 않는 것이 확정되더라도 채무를 이행하여야 한다면 그 부관은 ____이다.","a":"불확정기한"},{"h":"2. 기한","q":"부관으로 정한 사실이 발생하지 않으면 채무를 이행하지 않아도 된다면 그 부관은 ____이다.","a":"조건"},{"h":"2. 기한","q":"기한의 이익은 포기할 수 있으나 ____의 이익을 해하지 못한다(제153조 제2항).","a":"상대방"},{"h":"2. 기한","q":"채무자가 기한의 이익을 포기하고 변제기 전에 변제하는 경우, 변제기까지의 ____ 등 채권자의 손해를 배상하여야 한다.","a":"약정이자"}],"민총18":[{"h":"1. 계산 방법","q":"기간 계산에 관한 민법 규정은 법령이나 법률행위에 다른 정함이 없는 경우에 적용되는 ____규정이다.","a":"보충"},{"h":"1. 계산 방법","q":"기간을 일, 주, 월 또는 연으로 정한 때에는 기간의 ____은 산입하지 않는다(제157조 본문).","a":"초일"},{"h":"1. 계산 방법","q":"기간의 말일이 토요일 또는 공휴일에 해당한 때에는 기간은 그 ____로 만료한다(제161조).","a":"익일"},{"h":"2. 예외적 초일산입","q":"기간이 오전 ____시부터 시작하는 때에는 초일을 산입한다(제157조 단서).","a":"0"},{"h":"2. 예외적 초일산입","q":"연령 계산에는 ____을 산입한다(제158조).","a":"출생일"}],"민총19":[{"h":"1. 제척기간","q":"아직 발생하지 않은 권리에는 ____이 적용되지 않는다.","a":"제척기간"},{"h":"1. 제척기간","q":"점유보호청구권의 1년 기간은 반드시 그 기간 내에 소를 제기하여야 하는 ____기간이다.","a":"출소"},{"h":"1. 제척기간","q":"채권양도의 통지는 그것만으로 제척기간 준수에 필요한 ____의 권리행사에 해당하지 않는다(전합).","a":"재판 외"},{"h":"가. 대상인 권리","q":"채권의 소멸시효기간은 ____년이다(제162조 제1항).","a":"10"},{"h":"가. 대상인 권리","q":"채권 및 소유권 이외의 재산권의 소멸시효기간은 ____년이다(제162조 제2항).","a":"20"},{"h":"나. 기산점","q":"소멸시효는 권리를 행사할 수 있는 때부터 진행하고, 이는 ____상 장애가 없는 상태를 말한다.","a":"법률"},{"h":"나. 기산점","q":"계속적 거래관계에서 생긴 외상대금채권의 소멸시효는 각 채권이 ____한 때부터 개별적으로 진행한다.","a":"발생"},{"h":"나. 기산점","q":"본래의 채무가 이행되지 않아 생긴 손해배상청구권의 소멸시효 기산점은 ____시이다.","a":"채무불이행"},{"h":"가. 청구","q":"채권양수인은 대항요건을 갖추지 못한 상태에서도 ____를 하여 시효를 중단시킬 수 있다.","a":"재판상 청구"},{"h":"가. 청구","q":"물상보증인이 제기한 저당권설정등기 말소청구 소송에서 채권자가 ____하여 피담보채권의 존재를 주장한 것은 재판상 청구에 해당하지 않는다.","a":"응소"},{"h":"가. 청구","q":"확정판결을 받은 채권자는 시효중단을 위하여, 재판상 청구가 있었다는 점만을 대상으로 하는 '새로운 방식의 ____소송'을 제기할 수 있다(전합).","a":"확인"},{"h":"가. 청구","q":"채권자대위소송을 제기하면 ____의 소멸시효가 중단된다.","a":"피대위권리"},{"h":"가. 청구","q":"소가 각하·기각·취하된 경우에는 ____월 내에 다시 재판상 청구 등을 하지 않으면 시효중단의 효력이 없다.","a":"6"},{"h":"나. 압류·가압류·가처분","q":"채권에 대한 가압류·압류를 신청하면 ____채권의 소멸시효가 중단된다(제168조 제2호).","a":"피보전"},{"h":"나. 압류·가압류·가처분","q":"가압류에 의한 시효중단의 효력은 가압류를 ____한 때로 소급한다.","a":"신청"},{"h":"나. 압류·가압류·가처분","q":"유체동산에 대한 가압류의 시효중단 효력은 가압류의 ____ 효력이 존속하는 동안 계속된다.","a":"집행보전"},{"h":"나. 압류·가압류·가처분","q":"채권 압류·가압류 당시 피압류채권이 존재하지 않았더라도 ____채권의 소멸시효는 중단된다.","a":"집행"},{"h":"나. 압류·가압류·가처분","q":"이미 시효로 소멸한 어음채권을 청구채권으로 하여 압류하더라도 ____채권의 소멸시효는 중단되지 않는다.","a":"원인"},{"h":"다. 승인","q":"채무의 일부변제, 이자의 지급, 기한유예의 요청은 ____ 승인에 해당한다.","a":"묵시적"},{"h":"시효완성 후의 승인","q":"시효완성 후 채무를 승인하였다는 사정만으로 시효완성 사실을 알고 시효이익을 ____한 것으로 추정할 수 없다(전합, 판례 변경).","a":"포기"}],"물권53":[{"h":"1. 소유권의 사용·수익권능","q":"소유자가 토지를 일반 공중의 용도로 제공하여 ____적 사용·수익권을 포기한 것으로 볼 수 있으면, 인도청구나 부당이득반환청구를 할 수 없다(전합).","a":"배타"},{"h":"1. 소유권의 사용·수익권능","q":"소유자의 사용·수익권 행사의 제한은 상속인뿐 아니라, 그 사정을 알고 취득한 ____에게도 승계될 수 있다.","a":"특정승계인"},{"h":"1. 소유권의 사용·수익권능","q":"토지가 '공로'가 된 경우 부지 소유자가 통행금지나 시설 철거를 청구하는 것은 ____에 해당할 수 있다.","a":"권리남용"},{"h":"1. 소유권의 사용·수익권능","q":"공로에서 통행의 자유를 침해하는 것은 ____가 되고, 방해의 배제나 예방을 구할 수 있다.","a":"불법행위"},{"h":"1. 소유권의 사용·수익권능","q":"배타적 점유가 아닌 단순한 통행에 그치는 경우 반환할 이익은 임료 전부가 아니라 ____된다.","a":"감경"},{"h":"1. 소유권의 사용·수익권능","q":"소유자의 사용·수익권 행사가 제한된다는 사정의 증명책임은 이를 ____하는 자에게 있다.","a":"주장"},{"h":"2. 집합건물법","q":"집합건물의 체납관리비 중 ____부분에 관한 관리비는 특별승계인에게 승계된다(전합).","a":"공용"},{"h":"2. 집합건물법","q":"구분소유관계가 성립하면 ____은 당연히 설립된다(집합건물법 제23조).","a":"관리단"},{"h":"2. 집합건물법","q":"집합건물의 공용부분과 대지에 대한 ____행위는 구분소유자가 단독으로 할 수 있다.","a":"보존"},{"h":"2. 집합건물법","q":"구분건물 사이의 격벽이 제거되어 구조상 ____을 상실하면, 복원이 용이하지 않은 한 그 등기는 공유지분 등기의 효력만 가진다.","a":"독립성"},{"h":"2. 집합건물법","q":"적정한 대지지분을 가진 구분소유자는 대지 전부를 용도에 따라 사용할 수 있으므로, 다른 대지 공유자에게 ____반환의무를 지지 않는다(전합).","a":"부당이득"},{"h":"2. 집합건물법","q":"대지사용권 없이 전유부분을 소유하는 자에 대하여 대지 소유자는 전유부분의 ____를 청구할 수 있다.","a":"철거"},{"h":"4. 물권의 소멸 — 혼동(제191조)","q":"가등기권자가 별도의 원인으로 소유권이전등기를 받더라도, 가등기에 기한 본등기청구권은 ____으로 소멸하지 않는다.","a":"혼동"}],"물권54":[{"h":"1. 등기신청·중복등기","q":"중복등기의 효력에 관한 ____설은 언제나 후등기가 무효라고 본다.","a":"절차법"},{"h":"1. 등기신청·중복등기","q":"명의인이 다른 중복 보존등기는, 선등기가 원인무효가 아닌 한 ____가 무효이다(전합).","a":"후등기"},{"h":"1. 등기신청·중복등기","q":"무효인 중복등기에 터 잡아서는 ____취득시효를 완성할 수 없다(전합).","a":"등기부"},{"h":"2. 중간생략등기","q":"소유권이전등기청구권이 시효로 소멸한 후에 마쳐진 등기는, 상대방이 시효를 주장하면 ____로서 말소 대상이 된다.","a":"원인무효"},{"h":"2. 중간생략등기","q":"토지거래허가구역에서 최초 매도인과 최종 매수인을 당사자로 하여 허가를 받아 마친 중간생략등기는 ____이다.","a":"무효"},{"h":"4. 등기상 이해관계 있는 제3자","q":"'등기상 이해관계 있는 제3자'는 등기부 기재에 의하여 ____으로 손해를 입을 우려가 인정되는 자를 말한다.","a":"형식적"},{"h":"4. 등기상 이해관계 있는 제3자","q":"허위표시에 기한 등기에 터 잡아 가압류한 자가 선의이면 말소등기에 대한 ____의무가 없다.","a":"승낙"},{"h":"5. 가등기","q":"가등기는 ____보전의 효력만 있고, 가등기만으로는 아무런 실체법상 효력이 없다.","a":"순위"},{"h":"5. 가등기","q":"가등기에 기한 본등기가 마쳐지면 순위는 가등기 시로 소급하지만 ____의 효력은 소급하지 않는다.","a":"물권변동"},{"h":"6. 부기등기 후 말소청구소송","q":"근저당권 이전의 부기등기가 마쳐진 후 근저당권설정등기의 말소를 구하는 소는 ____만을 피고로 하여야 한다.","a":"양수인"},{"h":"6. 부기등기 후 말소청구소송","q":"근저당권의 주등기가 말소되면 부기등기는 ____으로 말소된다.","a":"직권"},{"h":"가. 소이등청구권 소멸시효","q":"부동산을 인도받아 사용·수익하고 있는 매수인의 소유권이전등기청구권은 ____에 걸리지 않는다(전합).","a":"소멸시효"},{"h":"가. 소이등청구권 소멸시효","q":"매수인이 점유를 ____당한 경우에는 점유를 상실한 때부터 소유권이전등기청구권의 소멸시효가 진행한다.","a":"침탈"},{"h":"가. 소이등청구권 소멸시효","q":"매매계약의 이행으로 토지를 인도받은 매수인은 등기가 없더라도 점유·사용할 권리가 있으므로, 매도인은 매수인에게 ____반환을 청구할 수 없다.","a":"부당이득"},{"h":"다. 진정명의회복 원인 소이등","q":"진정명의회복을 원인으로 한 소유권이전등기청구는, 이미 자기 앞으로 등기가 되어 있었거나 ____에 의하여 소유권을 취득한 자에게만 인정된다(전합).","a":"법률"},{"h":"다. 진정명의회복 원인 소이등","q":"진정명의회복을 위한 소유권이전등기청구권과 말소등기청구권은 ____이 실질상 동일하다(전합).","a":"소송물"},{"h":"8. 등기의 추정력","q":"등기명의자가 대리인을 통하여 매수하였다고 주장하는 경우 그 ____의 존재도 추정된다.","a":"대리권"},{"h":"8. 등기의 추정력","q":"등기명의자는 제3자뿐 아니라 ____에 대하여도 적법한 등기원인에 의하여 소유권을 취득한 것으로 추정된다.","a":"전 소유자"},{"h":"8. 등기의 추정력","q":"등기가 원인 없이 말소되었더라도 회복등기 전까지 그 명의인은 적법한 권리자로 추정된다 — 등기는 물권의 효력발생요건이지 ____요건이 아니기 때문이다.","a":"존속"},{"h":"8. 등기의 추정력","q":"등기의무자가 ____한 후에 신청된 소유권이전등기는 추정력이 번복된다.","a":"사망"}],"물권55":[{"h":"1. 등기 불요 물권변동(제187조)","q":"상속, 공용징수, 판결, 경매 기타 법률의 규정에 의한 부동산 물권의 취득은 ____를 요하지 않는다(제187조).","a":"등기"},{"h":"1. 등기 불요 물권변동(제187조)","q":"제187조에 따라 취득한 부동산 물권도 등기를 하지 않으면 이를 ____하지 못한다(단서).","a":"처분"},{"h":"1. 등기 불요 물권변동(제187조)","q":"제187조의 '판결'은 ____판결에 한한다.","a":"형성"},{"h":"1. 등기 불요 물권변동(제187조)","q":"경매에 의한 소유권 취득 시기는 ____을 완납한 때이다.","a":"매각대금"},{"h":"1. 등기 불요 물권변동(제187조)","q":"등기는 등기관이 ____한 때부터 효력이 발생한다(부동산등기법 제6조 제2항).","a":"접수"},{"h":"2. 건물신축과 원시취득","q":"자기의 재료와 노력으로 건물을 지은 건축업자와 도급인 사이에 특별한 의사표시가 없다면, 건물의 소유권은 ____에게 원시적으로 귀속한다.","a":"수급인"},{"h":"2. 건물신축과 원시취득","q":"건물이 수급인 소유인 경우 수급인은 그 기성부분에 대하여 ____을 행사할 수 없다 — 타물권이기 때문이다.","a":"유치권"},{"h":"2. 건물신축과 원시취득","q":"건물이 물리적으로 완성되기 전이라도 건축허가신청이나 분양계약 등으로 ____가 객관적으로 표시되면 구분행위가 인정된다(전합).","a":"구분의사"}],"물권56":[{"h":"가. 요건(제249조)","q":"____은 선의취득의 대상이 되지 않는다 — 가치 그 자체이기 때문이다.","a":"금전"},{"h":"가. 요건(제249조)","q":"등기·등록에 의하여 공시되는 ____는 선의취득의 대상이 아니다.","a":"자동차"},{"h":"가. 요건(제249조)","q":"선의취득이 성립하려면 양도인이 ____여야 한다.","a":"무권리자"},{"h":"가. 요건(제249조)","q":"선의취득의 요건인 거래행위는 ____하여야 한다 — 무권리라는 점 외에는 흠이 없어야 한다.","a":"유효"},{"h":"가. 요건(제249조)","q":"경매도 선의취득의 요건인 ____에 해당한다.","a":"거래행위"},{"h":"가. 요건(제249조)","q":"____에 의한 점유 취득으로는 선의취득이 인정되지 않는다.","a":"점유개정"},{"h":"가. 요건(제249조)","q":"선의취득에서 양수인의 ____은 추정되지 않는다.","a":"무과실"},{"h":"가. 요건(제249조)","q":"선의·무과실의 기준시점은 ____가 완성된 때이다.","a":"물권행위"},{"h":"나. 효과","q":"선의취득은 ____취득이다 — 종전의 제한은 소멸하고 진정한 소유자에게 부당이득반환의무도 없다.","a":"원시"},{"h":"나. 효과","q":"선의취득의 효과는 ____이므로, 선의취득자가 임의로 이를 거부하고 종전 소유자에게 반환을 요구할 수 없다.","a":"확정적"},{"h":"다. 도품·유실물 특례","q":"도품이나 유실물은 피해자 또는 유실자가 도난·유실한 날부터 ____년 내에 반환을 청구할 수 있다(제250조).","a":"2"},{"h":"다. 도품·유실물 특례","q":"제250조의 '피해자'는 ____에 한정되지 않는다(절취당한 임차인 포함).","a":"소유자"},{"h":"다. 도품·유실물 특례","q":"사기·공갈·____으로 점유를 잃은 물건은 도품·유실물에 해당하지 않는다.","a":"횡령"}],"물권57":[{"h":"1. 의의·성질","q":"소유자가 소유권을 상실하면 물권적 청구권도 그 기반을 잃으므로, 그 이행불능을 이유로 제390조의 ____을 청구할 수 없다(전합).","a":"손해배상"},{"h":"가. 소유물반환청구권(제213조)","q":"반사회적 법률행위로 등기를 마친 자가 물권적 청구권을 행사하는 경우, 상대방은 그 등기의 ____를 항변할 수 있다.","a":"무효"},{"h":"가. 소유물반환청구권(제213조)","q":"소유물반환청구에 대하여 상대방은 ____할 권리가 있음을 항변할 수 있다(제213조 단서).","a":"점유"},{"h":"가. 소유물반환청구권(제213조)","q":"제213조 단서의 점유할 권리에는 임차권처럼 점유를 수반하는 ____도 포함된다.","a":"채권"},{"h":"가. 소유물반환청구권(제213조)","q":"미등기 매수인이 토지를 인도받았다면 점유·사용할 권리가 있으므로, 매도인은 그에게 ____ 청구권을 행사할 수 없다.","a":"물권적"},{"h":"나. 소유물방해제거청구권(제214조)","q":"등기말소를 청구하려면 원고에게 말소를 청구할 ____이 있음을 적극적으로 주장·증명하여야 한다.","a":"권원"},{"h":"나. 소유물방해제거청구권(제214조)","q":"제3자의 취득시효 완성으로 원고가 소유권을 상실하면, 피고 명의 등기가 원인무효라도 ____를 청구할 수 없다.","a":"등기말소"},{"h":"나. 소유물방해제거청구권(제214조)","q":"방해제거청구권의 '방해'는 현재 지속되는 침해를 말하고, 이미 종결된 침해의 결과인 ____와 구별된다.","a":"손해"},{"h":"나. 소유물방해제거청구권(제214조)","q":"건물철거청구의 상대방은 건물의 소유자 또는 미등기 건물의 사실상 ____이다.","a":"처분권자"},{"h":"라. 토지소유자의 물권적 청구 사례","q":"토지소유자는 자기 건물을 점유하고 있는 건물소유자에 대하여 철거와 인도를 청구할 수 있을 뿐, 건물에서의 ____를 청구할 수 없다.","a":"퇴거"},{"h":"라. 토지소유자의 물권적 청구 사례","q":"건물에 관한 유치권으로는 ____소유자에게 대항할 수 없다.","a":"토지"},{"h":"다. 비용상환청구권(제203조)","q":"점유자의 비용상환청구권(제203조)은 점유의 선의·악의를 ____하고 인정된다.","a":"불문"},{"h":"다. 비용상환청구권(제203조)","q":"점유자가 ____을 취득한 경우에는 통상의 필요비를 청구하지 못한다(제203조 제1항 단서).","a":"과실"},{"h":"다. 비용상환청구권(제203조)","q":"유익비상환청구(제203조 제2항)는 가액의 증가가 ____하는 경우에 한하여 인정된다.","a":"현존"},{"h":"다. 비용상환청구권(제203조)","q":"적법한 점유권원을 가진 임차인 등은 소유자에게 제203조에 따라 비용상환을 청구할 수 없고, 자기의 ____ 상대방에게 청구하여야 한다.","a":"계약"}],"물권58":[{"h":"1. 서설·각종 개념","q":"점유는 물건에 대한 ____상 지배를 말하고, 사회통념에 따라 합목적적으로 판단한다.","a":"사실"},{"h":"1. 서설·각종 개념","q":"가사상·영업상 기타 유사한 관계에 의하여 타인의 지시를 받아 물건을 지배하는 자를 ____라 한다(제195조).","a":"점유보조자"},{"h":"1. 서설·각종 개념","q":"간접점유가 인정되려면 직접점유자와 간접점유자 사이에 ____관계가 있어야 한다.","a":"점유매개"},{"h":"1. 서설·각종 개념","q":"취득시효의 요건인 점유에는 ____점유도 포함된다.","a":"간접"},{"h":"1. 서설·각종 개념","q":"임대차가 종료된 후에도 직접점유자가 목적물을 반환하지 않고 있으면 점유매개관계는 ____한다.","a":"존속"},{"h":"2. 공동점유","q":"건물 공유자 중 일부만 건물을 점유하더라도 그 부지는 공유명의자 ____이 공동으로 점유하는 것이다.","a":"전원"},{"h":"가. 점유의 태양(§197)","q":"선의의 점유자가 본권에 관한 소에서 패소한 때에는 그 ____ 때부터 악의의 점유자로 본다(제197조 제2항).","a":"소가 제기된"},{"h":"다. 점유의 상속·승계","q":"피상속인이 소유의 의사 없이 점유하였다면 상속인의 점유도 ____점유이다.","a":"타주"},{"h":"라. 권리 적법 추정(§200)","q":"점유자의 권리 적법 추정(제200조)은 ____에만 적용된다.","a":"동산"},{"h":"마. 점유권 소멸·회복","q":"점유를 침탈당하여 점유권이 소멸한 경우에도 제204조에 따라 점유를 ____하면 처음부터 점유를 상실하지 않은 것으로 본다.","a":"회수"},{"h":"바. 점유의 소와 본권의 소(§208)","q":"점유의 소는 ____에 관한 이유로 재판하지 못한다(제208조 제2항).","a":"본권"},{"h":"가. 점유물반환청구권(§204)","q":"점유물반환청구권은 침탈을 당한 날부터 ____년 내에 행사하여야 한다(제204조 제3항).","a":"1"},{"h":"가. 점유물반환청구권(§204)","q":"점유물반환청구권은 침탈자의 ____의 특별승계인에 대하여는 행사하지 못한다.","a":"선의"},{"h":"가. 점유물반환청구권(§204)","q":"제204조 제3항의 기간은 그 안에 소를 제기하여야 하는 ____기간이다.","a":"출소"},{"h":"가. 점유물반환청구권(§204)","q":"위법하게 점유를 침탈당한 자가 점유를 탈환한 경우, 상대방은 제204조의 ____청구를 할 수 없다.","a":"점유회수"}],"물권59":[{"h":"가. 대상","q":"자기 소유 부동산을 점유하던 중 타인 명의로 이전등기가 된 경우, 취득시효의 기산점은 소유권의 ____이 있은 날(이전등기일)이다.","a":"변동"},{"h":"나. 자주점유","q":"자주점유 여부는 점유권원의 ____에 따라 외형적·객관적으로 결정한다(통설·판례).","a":"성질"},{"h":"나. 자주점유","q":"매수인의 점유도 매매계약이 ____된 날부터는 타주점유로 된다.","a":"해제"},{"h":"나. 자주점유","q":"공유자 1인이 공유토지 전부를 점유하더라도 다른 공유자의 ____ 범위에서는 타주점유이다.","a":"지분비율"},{"h":"나. 자주점유","q":"점유자가 스스로 매매나 증여 같은 자주점유의 권원을 주장하였다가 인정되지 않더라도 자주점유의 ____이 번복되지 않는다(전합).","a":"추정"},{"h":"나. 자주점유","q":"타인 소유임을 알면서 권원 없이 점유를 개시한 악의의 ____점유자는 자주점유의 추정이 깨진다(전합).","a":"무단"},{"h":"나. 자주점유","q":"계약명의신탁의 신탁자는 매도인의 선의·악의를 불문하고 ____점유자이다.","a":"타주"},{"h":"가. 20년 점유","q":"점유취득시효의 기산점은 점유의 시초이고, 임의로 기산점을 선택하거나 ____할 수 없다.","a":"역산"},{"h":"가. 20년 점유","q":"취득시효의 효과는 점유를 ____한 때에 소급한다(제247조 제1항).","a":"개시"},{"h":"나. 등기","q":"전 점유자의 점유를 승계한 현 점유자는 직접 자기에게 소유권이전등기를 청구할 수 없고, 전 점유자의 청구권을 ____하여 행사할 수 있을 뿐이다(전합).","a":"대위"},{"h":"다. 완성자의 지위","q":"취득시효 완성 후 등기 전에 제3자가 소유권이전등기를 마치면 시효완성자는 그 제3자에게 ____할 수 없다.","a":"대항"},{"h":"다. 완성자의 지위","q":"취득시효 완성 후 제3자 명의로 등기가 된 경우에도 점유자가 계속 점유하면, 소유자가 변동된 시점을 새로운 기산점으로 삼아 ____ 취득시효를 주장할 수 있다(전합).","a":"2차"},{"h":"다. 완성자의 지위","q":"취득시효 완성 사실을 알고 있는 소유자가 부동산을 제3자에게 처분하면 시효완성자에 대하여 ____가 성립한다.","a":"불법행위"},{"h":"다. 완성자의 지위","q":"시효완성자가 대상청구권을 행사하려면 이행불능 ____에 소유자에게 시효취득을 주장하거나 등기청구권을 행사하였어야 한다.","a":"전"},{"h":"3. 등기부취득시효","q":"등기부취득시효의 요건인 등기는 ____ 등기라도 무방하다(전합).","a":"원인무효"},{"h":"3. 등기부취득시효","q":"등기부취득시효에서 10년간 반드시 자신의 명의로 등기되어 있을 필요는 없고, ____의 등기기간을 합산할 수 있다(전합).","a":"전 점유자"},{"h":"3. 등기부취득시효","q":"등기부취득시효에서 선의·무과실은 등기가 아니라 ____에 관한 것이어야 한다.","a":"점유"},{"h":"4. 취득시효의 중단·포기","q":"점유취득시효에는 소멸시효의 중단에 관한 규정이 ____된다(제247조 제2항).","a":"준용"},{"h":"4. 취득시효의 중단·포기","q":"취득시효의 중단사유인 재판상 청구에는 인도청구뿐 아니라 ____의 존부에 관한 확인청구도 포함된다.","a":"소유권"},{"h":"4. 취득시효의 중단·포기","q":"권리자가 시효를 주장하는 자의 소에 ____하여 적극적으로 권리를 주장하고 그것이 받아들여진 경우에도 취득시효가 중단된다.","a":"응소"}],"물권60":[{"h":"1. 첨부 서설","q":"첨부에는 부합, 혼화, ____이 있다.","a":"가공"},{"h":"2. 부합의 유형","q":"부동산의 소유자는 그 부동산에 부합한 물건의 소유권을 취득하지만, 타인의 ____에 의하여 부속된 것은 그러하지 아니하다(제256조).","a":"권원"},{"h":"2. 부합의 유형","q":"동산과 동산이 부합하여 훼손하지 않으면 분리할 수 없는 경우, 합성물의 소유권은 ____ 동산의 소유자에게 속한다(제257조).","a":"주된"},{"h":"2. 부합의 유형","q":"주종을 구별할 수 없는 동산 간 부합에서 공유 지분은 부합 당시의 ____ 비율에 따른다.","a":"가액"},{"h":"2. 부합의 유형","q":"부합된 물건이 부동산의 ____이 되어 독립성이 없으면, 타인의 권원에 의한 것이라도 부동산 소유자에게 귀속한다.","a":"구성부분"},{"h":"2. 부합의 유형","q":"임차인이 부속시킨 물건이 독립성을 잃고 건물의 구성부분이 된 경우에는 ____청구권이 문제된다.","a":"비용상환"},{"h":"2. 부합의 유형","q":"임차인이 부속시킨 물건이 독립성을 유지하는 경우에는 ____청구권이 문제된다.","a":"부속물매수"},{"h":"3. 부합의 예외","q":"토지 위에 식재된 입목은 원칙적으로 토지의 일부로서 토지에 ____한다.","a":"부합"},{"h":"4. 보상청구권(제261조)","q":"첨부로 손해를 받은 자는 ____에 관한 규정에 의하여 보상을 청구할 수 있다(제261조).","a":"부당이득"},{"h":"4. 보상청구권(제261조)","q":"제256조의 법리는 건물의 증축뿐 아니라 ____의 경우에도 적용된다.","a":"신축"}],"물권61":[{"h":"가. 공유 지분","q":"공유자는 공유물 전부를 ____의 비율로 사용·수익할 수 있다(제263조).","a":"지분"},{"h":"가. 공유 지분","q":"공유지분의 포기는 상대방 있는 단독행위로서, ____를 하여야 물권변동의 효력이 생긴다.","a":"등기"},{"h":"나. 공유물의 관리(§265본문)","q":"공유물의 관리에 관한 사항은 공유자 지분의 ____로 결정한다(제265조 본문).","a":"과반수"},{"h":"나. 공유물의 관리(§265본문)","q":"과반수 지분권자로부터 공유물을 임차한 자의 점유는 ____하므로, 소수지분권자는 그에게 인도나 부당이득반환을 청구할 수 없다.","a":"적법"},{"h":"나. 공유물의 관리(§265본문)","q":"공유물의 사용·관리에 관한 특약은 지분의 ____에게도 당연히 승계된다.","a":"특정승계인"},{"h":"다. 공유물의 보존(§265단서)","q":"공유물의 ____행위는 각 공유자가 단독으로 할 수 있다(제265조 단서).","a":"보존"},{"h":"다. 공유물의 보존(§265단서)","q":"제3자 명의의 원인무효 등기에 대하여 공유자 1인은 보존행위로서 그 등기 ____의 말소를 청구할 수 있다.","a":"전부"},{"h":"다. 공유물의 보존(§265단서)","q":"소수지분권자가 공유물을 독점적으로 점유하는 경우, 다른 소수지분권자는 ____를 청구할 수 없고 방해배제만 청구할 수 있다(전합).","a":"인도"},{"h":"라. 공유물의 처분·변경(§264)","q":"공유물의 처분이나 변경에는 공유자 ____의 동의가 필요하다(제264조).","a":"전원"},{"h":"라. 공유물의 처분·변경(§264)","q":"공유인 나대지에 건물을 신축하는 것은 관리행위를 넘는 ____행위이다.","a":"처분·변경"},{"h":"사. 공유물분할(§268·269)","q":"공유물분할의 소는 ____의 소이다.","a":"형성"},{"h":"사. 공유물분할(§268·269)","q":"재판에 의한 공유물분할은 판결이 ____된 때 물권변동의 효력이 생긴다(제187조).","a":"확정"},{"h":"사. 공유물분할(§268·269)","q":"현물로 분할할 수 없거나 분할로 가액이 현저히 감손될 염려가 있는 때에는 ____를 명할 수 있다(제269조 제2항).","a":"경매"},{"h":"사. 공유물분할(§268·269)","q":"공유물분할을 위한 경매에도 원칙적으로 ____주의가 적용된다.","a":"소멸"},{"h":"다. 합유물 처분·변경·보존(§272)","q":"합유물인 조합재산의 처분·변경에는 제272조보다 제____조 제2항이 우선 적용된다.","a":"706"},{"h":"나. 총유물 관리·처분(§276①)","q":"총유물의 관리 및 처분은 ____의 결의에 의한다(제276조 제1항).","a":"사원총회"},{"h":"나. 총유물 관리·처분(§276①)","q":"비법인사단의 금전차용이나 채무보증은 총유물의 ____가 아니라 단순한 채무부담행위이다(전합).","a":"처분"},{"h":"다. 권리·의무 득상(§277)","q":"교인들이 집단으로 탈퇴한 경우 종전 교회의 재산은 ____ 교인들의 총유에 속한다(전합).","a":"잔존"}],"물권62":[{"h":"가. 유효 명의신탁 법리","q":"유효한 명의신탁에서 대외적 소유자는 ____이므로, 신탁자는 제3자에게 직접 방해배제를 청구할 수 없다(전합).","a":"수탁자"},{"h":"가. 유효 명의신탁 법리","q":"유효한 명의신탁에서 신탁자는 명의신탁을 ____하고 소유권이전등기를 청구할 수 있다.","a":"해지"},{"h":"나. 상호명의신탁(구분소유적 공유)","q":"상호명의신탁에서 내부적으로는 각자 특정 부분을 단독 소유하고, 외부적으로는 1필지 전체의 일반 ____관계가 된다.","a":"공유"},{"h":"Ⅱ. 부동산실명법(제4조)","q":"명의신탁약정과 그에 따른 물권변동의 무효는 제3자에게 대항하지 못하고, 이때 제3자의 선의·악의는 ____한다.","a":"불문"},{"h":"Ⅱ. 부동산실명법(제4조)","q":"제3취득자가 소유권을 취득하면 명의신탁관계는 당사자의 의사표시를 기다릴 필요 없이 당연히 ____한다.","a":"종료"},{"h":"Ⅲ. 양자간 등기명의신탁","q":"양자간 등기명의신탁에서 신탁자는 수탁자에게 등기말소 또는 ____회복을 원인으로 한 소유권이전등기를 청구할 수 있다.","a":"진정명의"},{"h":"Ⅳ. 3자간 등기명의신탁(중간생략등기형)","q":"3자간 등기명의신탁에서 신탁자는 수탁자에게 직접 부당이득을 원인으로 한 소유권이전등기를 청구할 수 없고, 매도인을 ____하여 수탁자 명의 등기의 말소를 구하여야 한다.","a":"대위"},{"h":"Ⅳ. 3자간 등기명의신탁(중간생략등기형)","q":"3자간 등기명의신탁에서 수탁자가 부동산을 임의로 처분하여 제3자가 소유권을 취득하면, 수탁자는 ____에게 그 이익을 부당이득으로 반환하여야 한다(전합).","a":"신탁자"},{"h":"Ⅴ. 계약명의신탁 — 선의 매도인","q":"매도인이 선의인 계약명의신탁에서 수탁자는 부동산의 소유권을 ____하게 취득한다.","a":"유효"},{"h":"Ⅴ. 계약명의신탁 — 선의 매도인","q":"매도인이 선의인 계약명의신탁(실명법 시행 후)에서 신탁자는 수탁자에게 ____ 상당의 부당이득반환만 청구할 수 있다.","a":"매수자금"},{"h":"Ⅴ. 계약명의신탁 — 선의 매도인","q":"무자력인 수탁자가 신탁자에게 부동산을 양도하는 것은 ____에 해당한다.","a":"사해행위"},{"h":"Ⅴ. 계약명의신탁 — 선의 매도인","q":"경매절차에서 타인의 이름으로 매각허가결정을 받고 자기가 대금을 부담한 경우에도 소유권은 ____이 취득한다.","a":"명의인"},{"h":"Ⅵ. 계약명의신탁 — 악의 매도인","q":"계약 상대방이 명의신탁약정을 안 계약명의신탁에서는 수탁자 명의 등기가 무효이고 소유권은 ____에게 남는다.","a":"매도인"},{"h":"Ⅵ. 계약명의신탁 — 악의 매도인","q":"계약명의신탁에서 매도인의 선의·악의는 ____ 당시를 기준으로 판단한다.","a":"계약 체결"},{"h":"Ⅶ. 실명법 시행 前 계약명의신탁 — 선의 매도인","q":"실명법 시행 전의 계약명의신탁에서 유예기간이 지나면 수탁자는 신탁자에게 ____ 자체를 부당이득으로 반환하여야 한다.","a":"부동산"},{"h":"Ⅶ. 실명법 시행 前 계약명의신탁 — 선의 매도인","q":"실명법 유예기간 경과로 신탁자가 갖는 소유권이전등기청구권은 ____년의 소멸시효에 걸린다.","a":"10"},{"h":"Ⅷ. 적용 제외(제8조)","q":"종중·배우자·종교단체의 명의신탁은 조세 포탈, 강제집행 면탈 또는 법령상 제한의 ____를 목적으로 하지 않으면 유효하다(실명법 제8조).","a":"회피"},{"h":"Ⅷ. 적용 제외(제8조)","q":"실명법 제8조의 '배우자'에 ____ 배우자는 포함되지 않는다.","a":"사실혼"},{"h":"Ⅷ. 적용 제외(제8조)","q":"실명법 제8조의 종중은 ____ 의미의 종중만을 말하고, 종중 유사 단체는 포함되지 않는다.","a":"고유한"},{"h":"CASE","q":"실명법의 적용 기준은 명의신탁 약정 시가 아니라 ____ 시이다.","a":"등기"}],"물권63":[{"h":"1. 지상권 일반론","q":"견고한 건물이나 수목의 소유를 목적으로 하는 지상권의 최단 존속기간은 ____년이다(제280조).","a":"30"},{"h":"1. 지상권 일반론","q":"견고하지 않은 그 밖의 건물의 소유를 목적으로 하는 지상권의 최단 존속기간은 ____년이다(제280조).","a":"15"},{"h":"1. 지상권 일반론","q":"지상권자는 토지소유자의 동의 없이 지상권을 양도하거나 토지를 임대할 수 있고, 이를 금지하는 특약은 ____이다(제282조·제289조).","a":"무효"},{"h":"1. 지상권 일반론","q":"담보지상권자는 제3자의 건물 축조에 대하여 중지를 청구할 수 있으나, 무단점유자에게 ____ 상당의 손해배상이나 부당이득반환을 청구할 수 없다.","a":"임료"},{"h":"1. 지상권 일반론","q":"담보지상권에서 피담보채무 전액의 변제를 주장하며 말소를 청구한 경우, 잔존채무가 밝혀지면 그 변제를 조건으로 말소를 구하는 ____의 소로 본다.","a":"장래이행"},{"h":"1. 지상권 일반론","q":"지상권이 설정된 토지의 소유자로부터 이용권을 취득하더라도 제256조 단서의 ____에 해당하지 않는다.","a":"권원"},{"h":"1. 지상권 일반론","q":"지상권자가 갱신청구권을 지체 없이 행사하지 않아 그 권리가 소멸하면 ____청구권도 발생하지 않는다.","a":"지상물매수"},{"h":"1. 지상권 일반론","q":"지료액이나 지급시기에 관한 약정은 등기하여야 토지소유권이나 지상권의 양수인 등 ____에게 대항할 수 있다.","a":"제3자"},{"h":"1. 지상권 일반론","q":"지상권자가 ____년 이상의 지료를 지급하지 않으면 지상권설정자는 지상권의 소멸을 청구할 수 있다(제287조).","a":"2"},{"h":"1. 지상권 일반론","q":"토지 양도 전후에 걸쳐 지료가 연체된 경우, ____에 대한 연체기간이 2년 미만이면 소멸청구를 할 수 없다.","a":"양수인"},{"h":"1. 지상권 일반론","q":"법정지상권에서 지료가 협의나 ____로 결정되지 않았다면 지료 지급을 지체한 것이 아니므로 소멸청구를 할 수 없다.","a":"판결"},{"h":"가. 건물 매매","q":"법정지상권자가 건물을 양도하면 건물 매수인은 양도인을 ____하여 지상권설정등기를 청구하고, 이어 이전등기를 청구할 수 있다.","a":"대위"},{"h":"가. 건물 매매","q":"법정지상권을 취득할 지위에 있는 건물 매수인에 대한 대지소유자의 철거청구는 ____에 반하여 허용되지 않는다(전합).","a":"신의칙"},{"h":"가. 건물 매매","q":"건물 매수인이 철거를 거부할 수 있더라도 대지를 점유·사용한 이익은 대지소유자에게 ____으로 반환하여야 한다.","a":"부당이득"},{"h":"나. 건물 경매","q":"법정지상권이 붙은 건물이 경매되면 경락인은 ____ 없이도 지상권을 함께 취득한다(제187조).","a":"등기"}],"물권64":[{"h":"가. 요건","q":"관습상 법정지상권을 인정하는 관습법은 현재에도 법적 규범으로서 ____을 유지한다(전합).","a":"효력"},{"h":"가. 요건","q":"미등기 무허가건물을 대지와 함께 양수하고 대지에만 등기를 마친 자는 건물의 ____을 취득하지 못하므로 관습상 법정지상권을 주장할 수 없다.","a":"소유권"},{"h":"가. 요건","q":"토지 공유자 1인이 건물을 신축한 뒤 토지가 경매로 분할된 경우, 다른 공유자의 ____에까지 지상권을 설정하는 셈이 되므로 관습상 법정지상권은 성립하지 않는다.","a":"지분"},{"h":"가. 요건","q":"구분소유적 공유에서 ____ 몫의 대지에 건물을 신축한 뒤 소유자가 달라지면 관습상 법정지상권이 성립한다.","a":"자기"},{"h":"가. 요건","q":"강제경매로 토지와 건물의 소유자가 달라진 경우, 동일인 소유 여부는 매각대금 완납 시가 아니라 ____의 효력 발생 시를 기준으로 판단한다(전합).","a":"압류"},{"h":"가. 요건","q":"강제경매 전에 보전처분이 있었고 그것이 본집행으로 이행되었다면 ____의 효력 발생 시를 기준으로 동일인 소유 여부를 판단한다.","a":"가압류"},{"h":"가. 요건","q":"건물을 철거하기로 하는 특약이 있다는 사실은 관습상 법정지상권의 성립을 다투는 자가 ____하여야 한다.","a":"증명"},{"h":"가. 요건","q":"건물만 양도하면서 그 부지에 관하여 ____계약을 체결하였다면 관습상 법정지상권을 포기한 것으로 본다.","a":"임대차"},{"h":"나. 효과","q":"법정지상권의 지료는 당사자의 청구에 의하여 ____이 정한다(제366조 단서).","a":"법원"},{"h":"가. 요건","q":"저당권 설정 당시 건물이 건축 중이었더라도 규모·종류를 외형상 예상할 수 있었고, 매각대금 ____ 시까지 독립된 건물의 요건을 갖추면 제366조의 법정지상권이 성립한다.","a":"완납"},{"h":"가. 요건","q":"토지와 건물에 공동저당이 설정된 후 건물이 철거·신축된 경우 법정지상권을 부정하는 것은, 공동저당권자가 토지를 ____로 평가한 교환가치의 기대를 보호하기 위함이다(전합).","a":"나대지"},{"h":"가. 요건","q":"제366조의 법정지상권에서 토지와 건물의 소유자 동일성은 ____ 설정 당시를 기준으로 판단하므로, 그 후 건물이 양도되어도 법정지상권이 인정된다.","a":"저당권"},{"h":"가. 요건","q":"건물을 명의신탁하고 대지에 저당권을 설정한 경우, ____관계에서는 토지와 건물의 소유자가 같지 않으므로 법정지상권이 성립하지 않는다.","a":"대외"},{"h":"가. 요건","q":"판례는 제366조의 법정지상권을 ____경매로 소유자가 달라진 경우에만 적용한다.","a":"임의"},{"h":"가. 미등기 건물+대지 함께 매수","q":"미등기 건물을 대지와 함께 매수한 사람이 대지에만 등기를 마치고 저당권을 설정한 경우, 설정 당시 토지와 건물의 소유자가 ____하지 않으므로 제366조의 법정지상권이 성립하지 않는다(전합).","a":"동일"},{"h":"나. 사해행위취소와 법정지상권","q":"건물 양도만 사해행위로 취소되어 등기가 말소되더라도, 취소의 효력은 ____적이므로 채무자는 관습상 법정지상권을 취득하지 못한다.","a":"상대"},{"h":"Ⅳ. 제305조 법정지상권 (건물전세권)","q":"제305조의 법정지상권을 취득하는 자는 전세권자가 아니라 ____이다.","a":"전세권설정자"},{"h":"Ⅴ. 분묘기지권","q":"취득시효형 분묘기지권자는 토지소유자가 지료를 ____한 날부터 지료를 지급할 의무가 있다(전합).","a":"청구"},{"h":"Ⅴ. 분묘기지권","q":"양도형 분묘기지권자는 분묘기지권이 ____한 때부터 지료를 지급할 의무가 있다.","a":"성립"}],"물권65":[{"h":"1. 의의","q":"지역권은 ____의 편익을 위하여 타인의 토지를 이용하는 용익물권이다.","a":"요역지"},{"h":"2. 성질","q":"지역권은 요역지 소유권에 ____하여 이전하고, 요역지와 분리하여 양도하지 못한다(제292조).","a":"부종"},{"h":"2. 성질","q":"토지 공유자 1인은 자기 지분에 관하여 그 토지를 위한 지역권을 ____하게 하지 못한다(제293조 제1항).","a":"소멸"},{"h":"2. 성질","q":"계약으로 승역지 소유자가 공작물의 설치·수선 의무를 부담한 때에는 승역지 소유자의 ____도 그 의무를 부담한다(제298조).","a":"특별승계인"},{"h":"가. 요건","q":"지역권은 ____되고 표현된 것에 한하여 시효취득할 수 있다(제294조).","a":"계속"},{"h":"나. 통행지역권","q":"통행지역권을 시효취득하려면 요역지 소유자가 승역지 위에 ____를 설치하여 늘 사용하는 객관적 상태가 제245조의 기간 동안 이어져야 한다.","a":"도로"},{"h":"나. 통행지역권","q":"통행지역권의 취득시효에서도 점유기간 중 소유자가 변동되면 기산점의 ____이 금지된다.","a":"역산"},{"h":"다. 불가분성","q":"점유로 인한 지역권 취득기간의 중단은 지역권을 행사하는 ____ 공유자에 대한 사유가 아니면 효력이 없다(제295조 제2항).","a":"모든"},{"h":"다. 불가분성","q":"요역지가 공유인 경우 지역권의 소멸시효는 공유자 ____에 대하여 완성되어야 효력이 있다(제296조).","a":"전원"}],"물권66":[{"h":"가. 용익물권성·담보물권성의 겸비","q":"전세권은 ____물권적 성격과 담보물권적 성격을 겸비한다.","a":"용익"},{"h":"가. 용익물권성·담보물권성의 겸비","q":"전세권의 존속기간이 만료되면 용익물권적 권능은 말소등기 없이도 당연히 소멸하고, 전세금반환채권을 담보하는 ____적 권능만 남는다.","a":"담보물권"},{"h":"나. 채권담보 목적의 전세권","q":"임대차보증금반환채권을 담보할 목적으로 임대인과 임차인의 합의로 마친 임차인 명의의 전세권설정등기는 ____하다.","a":"유효"},{"h":"나. 채권담보 목적의 전세권","q":"임대차보증금 담보 목적의 전세권설정계약은 연체차임을 공제하지 않는 것처럼 꾸민 범위에서 ____로서 무효이다.","a":"통정허위표시"},{"h":"나. 채권담보 목적의 전세권","q":"목적물의 인도는 전세권의 ____요건이 아니다.","a":"성립"},{"h":"나. 채권담보 목적의 전세권","q":"전세금은 반드시 현실로 수수되어야 하는 것은 아니고, 기존의 ____으로 지급에 갈음할 수 있다.","a":"채권"},{"h":"나. 채권담보 목적의 전세권","q":"전세권자의 사용·수익을 완전히 배제하고 채권담보만을 위하여 설정한 전세권은 ____주의에 반하여 무효이다.","a":"물권법정"},{"h":"2. 존속기간(312조)","q":"건물 전세권설정자가 존속기간 만료 전 6월부터 1월까지 사이에 갱신거절 통지를 하지 않으면 전세권은 ____된다(제312조 제4항).","a":"법정갱신"},{"h":"2. 존속기간(312조)","q":"건물 전세권의 법정갱신은 법률의 규정에 의한 물권변동이므로 ____ 없이도 제3자에게 대항할 수 있다.","a":"등기"},{"h":"가. 사용·수익권","q":"전세권자는 목적물의 현상 유지와 통상의 관리에 속한 수선을 하여야 하므로 ____의 상환을 청구할 수 없다(제309조).","a":"필요비"},{"h":"나. 건물전세권의 지상권·차지권에 대한 효력(304조)","q":"전세권설정자는 전세권자의 ____ 없이 지상권이나 임차권을 소멸하게 하는 행위를 하지 못한다(제304조 제2항).","a":"동의"},{"h":"나. 건물전세권의 지상권·차지권에 대한 효력(304조)","q":"건물소유자가 ____ 연체로 지상권 소멸청구를 당하는 것은 제304조 제2항의 '소멸하게 하는 행위'에 해당하지 않는다.","a":"지료"},{"h":"가. 동시이행(317조)","q":"전세권이 소멸하면 목적물 인도 및 말소등기서류 교부와 전세금 반환은 ____관계에 있다(제317조).","a":"동시이행"},{"h":"나. 기간약정 없는 전세권의 소멸통고(313조)","q":"존속기간을 정하지 않은 전세권은 각 당사자가 언제든지 소멸을 통고할 수 있고, 통고를 받은 날부터 ____월이 지나면 소멸한다(제313조).","a":"6"},{"h":"다. 목적물 소유권의 이전","q":"전세권 성립 후 목적물의 소유권이 이전되면 전세금반환의무는 ____가 부담하고, 종전 소유자는 그 의무를 면한다.","a":"신 소유자"},{"h":"라. 전세금","q":"전세권자의 귀책사유로 목적물이 멸실된 경우 설정자는 전세권이 소멸한 뒤 ____으로 손해배상에 충당할 수 있다(제315조).","a":"전세금"},{"h":"라. 전세금","q":"전세권의 존속기간이 만료되면 전세권저당권자는 전세권 자체에 저당권을 실행할 수 없고, 전세금반환채권에 ____권을 행사하여야 한다.","a":"물상대위"},{"h":"마. 우선변제권·경매청구권(318조)","q":"건물의 일부에 대한 전세권자는 건물 ____에 대한 경매를 청구할 수 없다.","a":"전부"},{"h":"마. 우선변제권·경매청구권(318조)","q":"최선순위 전세권은 존속기간과 상관없이 전세권자가 ____를 하여야만 매각으로 소멸한다.","a":"배당요구"}],"물권67":[{"h":"1. 담보물권의 공통 성질","q":"채권이 존재하여야 성립하고 채권이 소멸하면 담보물권도 당연히 소멸하는 성질을 ____이라 한다.","a":"부종성"},{"h":"1. 담보물권의 공통 성질","q":"피담보채권이 양도되면 담보물권도 함께 이전하는 성질을 ____이라 한다.","a":"수반성"},{"h":"1. 담보물권의 공통 성질","q":"____은 교환가치로 우선변제를 받는 권리가 아니므로 물상대위성이 없다.","a":"유치권"},{"h":"1. 담보물권의 공통 성질","q":"피담보채권 전부를 변제받을 때까지 목적물 전부에 권리를 행사할 수 있는 성질을 ____이라 한다.","a":"불가분성"},{"h":"1. 담보물권의 공통 성질","q":"다세대주택 공사를 마친 하수급인이 1세대만 점유하여 유치권을 행사하는 경우, 피담보채권은 그 세대의 공사대금이 아니라 공사대금채권 잔액 ____이다.","a":"전부"},{"h":"가. 강제경매와 임의경매의 공신력","q":"강제경매에는 ____이 있어, 실체상 청구권이 없더라도 절차가 완결되면 매수인이 소유권을 취득한다.","a":"공신력"},{"h":"가. 강제경매와 임의경매의 공신력","q":"____경매는 담보권의 환가권 실행을 국가가 대행하는 것이어서, 담보권이 처음부터 없었다면 매수인이 소유권을 취득하지 못한다.","a":"임의"},{"h":"가. 강제경매와 임의경매의 공신력","q":"민사집행법 제267조는 경매개시결정 ____에 담보권이 소멸하였는데도 경매가 진행된 경우에만 적용된다(전합).","a":"후"},{"h":"나. 경매가 무효인 경우","q":"경매가 무효이면 경락인은 소유권을 취득하지 못하고, 경매의 ____책임(제578조)도 인정되지 않는다.","a":"담보"},{"h":"나. 경매가 무효인 경우","q":"위조된 약속어음 공정증서를 ____으로 한 강제경매는 무효이다.","a":"집행권원"},{"h":"나. 경매가 무효인 경우","q":"경매에서 매수인은 ____을 완납한 때 소유권을 취득한다.","a":"매각대금"}],"물권68":[{"h":"나. ② 견련성","q":"유치권은 채권이 목적물 자체로부터 또는 목적물 ____청구권과 동일한 법률관계·사실관계로부터 발생한 경우에 성립한다.","a":"반환"},{"h":"다. ③ 변제기 도래","q":"도급인이 하자보수에 갈음한 손해배상채권으로 공사잔대금 전부에 ____항변을 할 수 있으면, 수급인은 유치권을 행사할 수 없다.","a":"동시이행"},{"h":"라. ④ 적법한 점유","q":"적법한 점유는 유치권의 성립요건이자 ____요건이다(제328조).","a":"존속"},{"h":"마. ⑤ 특약의 부존재","q":"유치권은 법정담보물권이지만 이를 배제하는 ____은 유효하다.","a":"특약"},{"h":"마. ⑤ 특약의 부존재","q":"유치권 배제 특약의 효력은 특약의 상대방뿐 아니라 그 밖의 사람도 ____할 수 있다.","a":"주장"},{"h":"3. 유치권과 경매절차","q":"경매개시결정의 기입등기로 ____의 효력이 생긴 뒤에 취득한 유치권으로는 매수인에게 대항할 수 없다.","a":"압류"},{"h":"3. 유치권과 경매절차","q":"부동산에 ____등기만 된 상태에서 점유를 이전받아 유치권을 취득한 것은 처분행위가 아니므로 매수인에게 대항할 수 있다.","a":"가압류"},{"h":"3. 유치권과 경매절차","q":"체납처분압류가 된 부동산이라도 ____등기 전에 유치권을 취득하였다면 매수인에게 대항할 수 있다(전합).","a":"경매개시결정"},{"h":"4. 유치권과 동시이행항변권","q":"물건 인도 청구소송에서 유치권 항변이 인용되면 법원은 채권의 변제와 ____으로 물건의 인도를 명하여야 한다.","a":"상환"},{"h":"가. 유치할 권리","q":"유치권자가 유치물인 주택에 거주하는 것은 ____에 필요한 사용으로서 허용된다.","a":"보존"},{"h":"가. 유치할 권리","q":"유치권자가 유치물에 거주하며 얻은 차임 상당의 이익은 ____으로 반환하여야 한다.","a":"부당이득"},{"h":"나. 경매·간이변제충당(322조)","q":"유치권에 의한 경매는 목적물을 환가하기 위한 ____적 경매이다.","a":"형식"},{"h":"나. 경매·간이변제충당(322조)","q":"유치권에 의한 경매도 소멸주의로 실시되고, 유치권자는 ____와 같은 순위로 배당을 받는다.","a":"일반채권자"},{"h":"라. 유치권자의 의무(324조)","q":"유치권자는 ____의 승낙 없이 유치물을 사용·대여하거나 담보로 제공하지 못한다(제324조 제2항).","a":"채무자"},{"h":"라. 유치권자의 의무(324조)","q":"유치권자가 승낙 없이 유치물을 임대하면 채무자는 유치권의 ____를 청구할 수 있다(제324조 제3항).","a":"소멸"},{"h":"라. 유치권자의 의무(324조)","q":"제324조 제2항을 위반한 임대행위가 있은 후 유치물의 ____을 취득한 제3자도 유치권소멸청구를 할 수 있다.","a":"소유권"},{"h":"마. 타담보제공과 유치권소멸청구(327조)","q":"채무자뿐 아니라 유치물의 ____도 상당한 담보를 제공하고 유치권의 소멸을 청구할 수 있다(제327조).","a":"소유자"},{"h":"6. 유치권의 소멸","q":"유치권은 ____의 상실로 소멸한다(제328조).","a":"점유"},{"h":"6. 유치권의 소멸","q":"유치권의 행사는 피담보채권의 ____의 진행에 영향을 미치지 않는다(제326조).","a":"소멸시효"},{"h":"CASE","q":"유치권의 ____성은 목적물이 분할 가능하거나 수 개의 물건인 경우에도 적용된다(제321조).","a":"불가분"}],"물권69":[{"h":"가. 성립·존속","q":"질권의 선의취득에서는 취득자가 자신의 선의와 ____을 모두 증명하여야 한다.","a":"무과실"},{"h":"가. 성립·존속","q":"질권설정에서 ____에 의한 인도는 금지된다(제332조).","a":"점유개정"},{"h":"나. 근질권의 확정시기","q":"근질권이 설정된 금전채권에 제3자의 압류로 강제집행절차가 개시된 경우, 근질권의 피담보채권은 근질권자가 그 사실을 ____ 때에 확정된다.","a":"알게 된"},{"h":"나. 근질권의 확정시기","q":"근저당권에 근질권의 부기등기가 된 후 제3자가 경매를 신청한 경우, 근질권의 피담보채권은 ____ 시에 확정된다.","a":"매각대금 완납"},{"h":"다. 효력·피담보채권 범위·전질","q":"변제기 전의 약정으로 질권자가 변제에 갈음하여 질물의 소유권을 취득하기로 하는 ____계약은 금지된다(제339조).","a":"유질"},{"h":"다. 효력·피담보채권 범위·전질","q":"질권의 피담보채권에는 원본, 이자, 위약금, 실행비용, 보존비용, 채무불이행 또는 질물의 ____로 인한 손해배상이 포함된다(제334조).","a":"하자"},{"h":"다. 효력·피담보채권 범위·전질","q":"질권자가 자기 채무의 담보로 질물 위에 다시 질권을 설정하는 것을 ____이라 한다.","a":"전질"},{"h":"나. 설정방법(346조) — 그 권리의 양도방법에 의함","q":"권리질권의 설정은 그 권리의 ____에 관한 방법에 의한다(제346조).","a":"양도"},{"h":"나. 설정방법(346조) — 그 권리의 양도방법에 의함","q":"채권질권의 설정으로 제3채무자에게 대항하려면 설정자의 ____ 또는 제3채무자의 승낙이 있어야 한다(제349조 제1항).","a":"통지"},{"h":"나. 설정방법(346조) — 그 권리의 양도방법에 의함","q":"제349조의 대항요건을 갖춘 후에는 제3채무자가 질권자의 ____ 없이 질권의 목적인 채무를 변제하여도 질권자에게 대항할 수 없다.","a":"동의"},{"h":"나. 설정방법(346조) — 그 권리의 양도방법에 의함","q":"질권설정계약이 합의해지된 경우 ____가 제3채무자에게 해지 사실을 통지하여야 설정자가 제3채무자에게 대항할 수 있다.","a":"질권자"},{"h":"나. 설정방법(346조) — 그 권리의 양도방법에 의함","q":"저당권으로 담보한 채권을 질권의 목적으로 한 때에는 저당권등기에 질권의 ____를 하여야 질권의 효력이 저당권에 미친다(제348조).","a":"부기등기"},{"h":"나. 설정방법(346조) — 그 권리의 양도방법에 의함","q":"제361조는 저당권만을 분리하여 양도하는 것을 금지할 뿐, 저당권으로 담보된 ____만을 분리하여 양도하거나 입질하는 것까지 금지하지 않는다.","a":"채권"},{"h":"나. 설정방법(346조) — 그 권리의 양도방법에 의함","q":"임대차보증금반환채권에 질권을 설정하면서 임대차계약서를 교부하지 않았더라도 질권은 유효하다 — 임대차계약서는 제347조의 ____가 아니기 때문이다.","a":"채권증서"},{"h":"다. 설정자의 처분제한(352조)","q":"질권설정자는 질권자의 동의 없이 질권의 목적인 권리를 ____하게 하거나 질권자의 이익을 해하는 변경을 할 수 없다(제352조).","a":"소멸"},{"h":"다. 설정자의 처분제한(352조)","q":"임대인이 갱신거절을 하지 않아 임대차가 ____된 것은 제352조 위반이 아니다.","a":"묵시적 갱신"},{"h":"라. 채권질권의 실행방법(353조)","q":"채권질권자는 질권의 목적이 된 채권을 ____ 청구할 수 있다(제353조 제1항).","a":"직접"},{"h":"라. 채권질권의 실행방법(353조)","q":"입질채권이 존재하지 않는데도 제3채무자가 질권자에게 지급한 경우, 제3채무자는 질권자가 아니라 ____에게 부당이득반환을 청구하여야 한다.","a":"질권설정자"}],"물권70":[{"h":"가. 저당권자 = 채권자 (제3자 명의 저당권)","q":"제3자 명의의 근저당권설정등기도 채권자·채무자·제3자의 합의가 있고 채권이 그 제3자에게 ____으로 귀속되었다고 볼 사정이 있으면 유효하다(전합).","a":"실질적"},{"h":"다. 물상보증인","q":"물상보증인의 구상권 범위는 매각대금이 아니라 소유권을 잃은 때 부동산의 ____를 기준으로 정한다.","a":"시가"},{"h":"가. 부합물·종물(358조)","q":"저당권의 효력은 저당부동산에 부합된 물건과 ____에 미친다(제358조).","a":"종물"},{"h":"가. 부합물·종물(358조)","q":"건물에 대한 저당권의 효력은 그 건물의 소유를 목적으로 하는 ____에도 미친다(제358조 유추적용).","a":"지상권"},{"h":"가. 부합물·종물(358조)","q":"건물 저당권의 효력이 토지임차권에 미치더라도, 경락인은 토지임대인의 ____가 없으면 임차권의 취득으로 임대인에게 대항할 수 없다(제629조).","a":"동의"},{"h":"다. 물상대위(370·342조)","q":"물상대위권을 행사하려면 금전이나 물건의 지급 또는 인도 전에 ____하여야 한다(제342조).","a":"압류"},{"h":"다. 물상대위(370·342조)","q":"협의취득은 사법상 ____에 해당하므로 그 보상금에는 물상대위를 할 수 없다.","a":"매매"},{"h":"다. 물상대위(370·342조)","q":"물상대위권은 늦어도 ____ 종기까지 행사하여야 한다.","a":"배당요구"},{"h":"다. 물상대위(370·342조)","q":"기한 내에 물상대위권을 행사하지 않아 우선변제권을 상실한 저당권자는, 보상금을 수령한 다른 채권자에게 ____반환을 청구할 수 없다.","a":"부당이득"},{"h":"다. 제3취득자","q":"저당부동산의 ____는 그 부동산에 지출한 필요비·유익비를 경매대가에서 우선상환받을 수 있다(제367조).","a":"제3취득자"},{"h":"6. 근저당권","q":"근저당권의 설정자와 근저당권자는 합의로 채무자를 변경할 수 있고, 이때 후순위권리자 등 이해관계인의 ____은 필요하지 않다.","a":"승낙"},{"h":"6. 근저당권","q":"근저당권자가 스스로 경매를 신청한 경우 피담보채권은 ____ 시에 확정된다.","a":"경매신청"},{"h":"6. 근저당권","q":"제3자가 경매를 신청한 경우 근저당권의 피담보채권은 ____ 시에 확정된다.","a":"매각대금 완납"},{"h":"6. 근저당권","q":"근저당권에는 제360조 ____가 적용되지 않으므로, 지연손해금도 1년분에 한정되지 않고 최고액 한도에서 전액 담보된다.","a":"단서"},{"h":"6. 근저당권","q":"물상보증인이나 제3취득자는 ____만 변제하고 근저당권의 소멸을 청구할 수 있다.","a":"채권최고액"},{"h":"가. 제368조 — 동일인 소유","q":"공동저당에서 동시배당을 할 때에는 각 부동산의 ____에 비례하여 채권의 분담을 정한다(제368조 제1항).","a":"경매대가"},{"h":"나. 채무자 소유와 물상보증인 소유","q":"물상보증인 소유 부동산이 먼저 경매된 경우, 그 부동산의 후순위저당권자는 물상보증인이 대위취득한 채무자 소유 부동산의 선순위 저당권에 ____를 할 수 있다.","a":"물상대위"},{"h":"마. 공동근저당권","q":"제368조는 공동____에도 적용된다(전합).","a":"근저당권"},{"h":"마. 공동근저당권","q":"동일한 채권을 담보하기 위하여 여러 부동산에 개별 근저당권의 형식을 취하면 ____적 근저당권이 되고 제368조가 적용되지 않는다.","a":"누적"},{"h":"저당권 — 저당권 및 피담보채권 양수인의 실행","q":"저당권과 피담보채권의 양수인이 저당권 이전의 부기등기를 마쳤다면, 채권양도의 ____을 갖추지 않았더라도 경매를 신청할 수 있다.","a":"대항요건"}],"물권71":[{"h":"1. 취지·기본개념","q":"가등기담보법상 사적 실행으로는 ____청산만 인정되고 처분청산은 허용되지 않는다.","a":"귀속"},{"h":"1. 취지·기본개념","q":"가등기담보법은 양도담보의 법적 성질에 관하여 ____설을 입법화하였다.","a":"담보물권"},{"h":"1. 취지·기본개념","q":"가등기담보법이 적용되면 채권자 앞으로 소유권이전등기가 마쳐져 있더라도 ____절차를 마쳐야 비로소 소유권을 취득한다.","a":"청산"},{"h":"1. 취지·기본개념","q":"가등기담보권자는 권리취득에 의한 실행 외에 ____를 청구하여 실행할 수도 있다(제12조).","a":"경매"},{"h":"2. 적용요건(가담법 1조)","q":"가등기담보법은 ____에 기한 차용금반환채무를 담보하는 경우에 적용된다.","a":"소비대차"},{"h":"2. 적용요건(가담법 1조)","q":"매매대금채무나 ____채무를 담보하기 위한 가등기에는 가등기담보법이 적용되지 않는다.","a":"공사대금"},{"h":"2. 적용요건(가담법 1조)","q":"가등기담보법은 예약 당시 부동산의 가액이 차용액과 ____의 합산액을 초과하는 경우에 적용된다.","a":"이자"},{"h":"2. 적용요건(가담법 1조)","q":"담보부동산에 선순위 저당권이 있으면, 그 ____액을 공제한 나머지 가액이 차용액과 이자의 합산액을 넘어야 가등기담보법이 적용된다.","a":"피담보채권"},{"h":"2. 적용요건(가담법 1조)","q":"담보계약만 체결하고 가등기나 ____를 마치지 않았다면 가담법상 담보권을 취득한 것이 아니다.","a":"소유권이전등기"},{"h":"나. 권리취득 실행(가담법 3·4조)","q":"채권자가 소유권을 취득하려면 변제기 후에 청산금의 ____을 채무자등에게 알려야 한다(제3조).","a":"평가액"},{"h":"나. 권리취득 실행(가담법 3·4조)","q":"청산기간은 실행의 뜻이 채무자등에게 도달한 날부터 ____개월이다.","a":"2"},{"h":"나. 권리취득 실행(가담법 3·4조)","q":"청산금은 ____ 당시의 부동산 가액에서 채권액을 뺀 금액이다.","a":"통지"},{"h":"나. 권리취득 실행(가담법 3·4조)","q":"가담법상 '채무자등'은 채무자, 물상보증인, ____를 말한다(제2조 제2호).","a":"제3취득자"},{"h":"나. 권리취득 실행(가담법 3·4조)","q":"채무자등 ____에게 실행의 뜻을 알리지 않으면 청산기간이 진행하지 않는다.","a":"모두"},{"h":"나. 권리취득 실행(가담법 3·4조)","q":"청산금 지급채무와 소유권이전등기 및 인도 채무는 ____관계에 있다(제4조 제3항).","a":"동시이행"},{"h":"나. 권리취득 실행(가담법 3·4조)","q":"청산금을 지급하지 않고 마친 본등기는 ____이고, 약한 의미의 양도담보로서 효력이 있다고 볼 수도 없다.","a":"무효"},{"h":"나. 권리취득 실행(가담법 3·4조)","q":"청산금 없이 마친 본등기도 그 후 정당한 청산절차를 마치면 ____에 부합하는 등기로서 유효하게 된다.","a":"실체관계"},{"h":"다. 채무자등의 지위 — 지키느냐","q":"채무자등은 청산금을 변제받을 때까지 채무액을 지급하고 소유권이전등기의 ____를 청구할 수 있다(제11조 본문).","a":"말소"},{"h":"다. 채무자등의 지위 — 지키느냐","q":"제11조의 권리는 변제기가 지난 때부터 ____년이 지나거나 선의의 제3자가 소유권을 취득한 경우에는 행사할 수 없다.","a":"10"}],"물권72":[{"h":"가. 서론","q":"동산 양도담보의 법적 성질에 관하여 판례는 ____적 소유권이전설을 취한다.","a":"신탁"},{"h":"가. 서론","q":"동산을 양도담보로 제공하면 대외적으로는 채권자가 소유자이지만, 대내적으로는 ____가 소유권을 보유한다.","a":"채무자"},{"h":"가. 서론","q":"양도담보를 설정하려면 설정자에게 목적물의 소유권이나 ____ 등 설정 권한이 있어야 한다.","a":"처분권"},{"h":"나. 유동집합물 양도담보","q":"유동집합물 양도담보는 목적물을 장소·종류·____의 지정 등으로 특정하여 설정할 수 있다.","a":"수량"},{"h":"다. 점유개정에 의한 동산 이중양도담보","q":"점유개정으로 동산을 이중으로 양도담보에 제공한 경우, 뒤의 채권자는 ____을 할 수 없어 양도담보권을 취득하지 못한다.","a":"선의취득"},{"h":"라. 양도담보의 판례 법리","q":"부동산 양도담보의 피담보채무가 변제된 경우 설정자의 말소등기청구권은 ____에 걸리지 않는다.","a":"소멸시효"},{"h":"라. 양도담보의 판례 법리","q":"양도담보의 효력은 부합물과 ____에 미친다(제358조 유추적용).","a":"종물"},{"h":"라. 양도담보의 판례 법리","q":"양도담보 목적물인 돼지가 낳은 새끼돼지는 ____이므로 양도담보의 효력이 미치지 않는다.","a":"천연과실"},{"h":"라. 양도담보의 판례 법리","q":"동산 양도담보권자는 목적물이 소실되어 설정자가 취득한 화재보험금청구권에 ____를 할 수 있다.","a":"물상대위"},{"h":"라. 양도담보의 판례 법리","q":"부동산을 양도담보로 받은 채권자는 채무자가 이행지체에 빠지면 ____의 실행으로서 목적물의 인도를 청구할 수 있다.","a":"담보권"},{"h":"라. 양도담보의 판례 법리","q":"임차 대지 위의 건물에 담보 목적의 소유권이전등기를 하더라도 대지 임대인에게 제629조의 ____권이 발생하지 않는다.","a":"해지"},{"h":"라. 양도담보의 판례 법리","q":"동산 양도담보는 ____과 달리, 설정 후 점유를 상실하더라도 유효하게 존속하고 우선변제권도 유지된다.","a":"질권"},{"h":"라. 양도담보의 판례 법리","q":"양도담보 설정자는 반대 특약이 없는 한 목적물의 ____권을 가진다.","a":"사용·수익"},{"h":"라. 양도담보의 판례 법리","q":"부동산을 양도담보로 받은 채권자는 목적물을 계속 쓰는 채무자에게 ____ 상당의 손해배상이나 부당이득반환을 청구할 수 없다.","a":"차임"},{"h":"라. 양도담보의 판례 법리","q":"가담법 시행 전의 약한 의미의 양도담보에서 귀속정산과 처분정산 중 어느 방법으로 실행할지는 ____의 선택에 달려 있다.","a":"채권자"},{"h":"2. 동산담보권·채권담보권","q":"동산채권담보법상 동산담보권은 담보약정과 ____로 성립한다(제7조).","a":"담보등기"}]};
